def _cs408_readiness_matches_terminal_retirement_descriptor(
    readiness: Mapping[str, Any],
) -> bool:
    descriptor = CS408_TERMINAL_RETIREMENT_DESCRIPTOR
    direct_fields = (
        "subject",
        "mode",
        "batch_id",
        "batch_sha256",
        "terminal_receipt_sha256",
        "writer_preimage_sha256",
        "batch_pointer_sha256",
        "snapshot_sha256",
        "source_generation",
        "source_authority_fingerprint",
    )
    return (
        all(readiness.get(key) == descriptor[key] for key in direct_fields)
        and readiness.get("authority_generation")
        == descriptor["target_generation"]
        and readiness.get("authority_fingerprint")
        == descriptor["target_authority_fingerprint"]
    )
