class ReleaseError(RuntimeError):
    pass


def canonical_bytes(value: object) -> bytes:
    return (
        json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        + "\n"
    ).encode("utf-8")


def _authorization_descriptor_sha256(value: object) -> str:
    """Hash an in-memory authorization value, not a newline-terminated file."""

    raw = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def atomic_json(path: Path, value: Mapping[str, Any], *, mode: int = 0o600) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, raw_temp = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temp = Path(raw_temp)
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, "wb") as handle:
            handle.write(canonical_bytes(value))
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
    finally:
        try:
            temp.unlink()
        except FileNotFoundError:
            pass


def _safe_base(path: Path, *, label: str) -> Path:
    resolved = path.expanduser().resolve()
    if resolved in {Path("/"), Path.home().resolve(), SOURCE_ROOT.resolve()}:
        raise ReleaseError(f"{label}_broad_or_source_root")
    return resolved


def source_files(source_root: Path) -> list[Path]:
    result: list[Path] = []
    for directory in ALLOWED_SOURCE_DIRS:
        root = source_root / directory
        if root.is_symlink():
            raise ReleaseError("release_source_symlink_forbidden")
        if not root.is_dir():
            continue
        for path in root.rglob("*"):
            if path.is_symlink():
                raise ReleaseError("release_source_symlink_forbidden")
            if path.is_dir():
                continue
            if not path.is_file():
                raise ReleaseError("release_source_special_file_forbidden")
            relative = path.relative_to(source_root)
            if "__pycache__" in relative.parts or path.suffix in {".pyc", ".pyo"}:
                continue
            if relative.as_posix() in STAGING_GENERATED_SOURCE_PATHS:
                continue
            result.append(path)
    for name in ALLOWED_ROOT_FILES:
        path = source_root / name
        if path.is_symlink():
            raise ReleaseError("release_source_symlink_forbidden")
        if path.is_file():
            result.append(path)
        elif path.exists():
            raise ReleaseError("release_source_special_file_forbidden")
    return sorted(set(result), key=lambda path: str(path.relative_to(source_root)))


def source_hashes(source_root: Path) -> dict[str, str]:
    return {
        str(path.relative_to(source_root)): sha256_file(path)
        for path in source_files(source_root)
    }


def source_modes(source_root: Path) -> dict[str, int]:
    return {
        str(path.relative_to(source_root)): (
            stat.S_IMODE(path.stat().st_mode) & ~0o222
        )
        for path in source_files(source_root)
    }


def file_owners(paths: Iterable[str]) -> dict[str, dict[str, int | str]]:
    return {
        relative: {
            "uid": os.getuid(),
            "gid": os.getgid(),
            "type": "file",
        }
        for relative in paths
    }


def release_id_for(
    hashes: Mapping[str, str],
    modes: Mapping[str, int],
    runtime_data_root: str,
    owners: Mapping[str, Mapping[str, int | str]] | None = None,
    release_profile: str = "concurrent_v2",
    source_release_id: str | None = None,
    model_contract: Mapping[str, Any] | None = None,
    test_results: Mapping[str, Any] | None = None,
    staging_generated_files: Mapping[str, str] | None = None,
) -> str:
    return sha256_bytes(
        canonical_bytes(
            {
                "schema_version": SCHEMA_VERSION,
                "source_files": dict(hashes),
                "source_modes": dict(modes),
                "source_owners": dict(owners or file_owners(hashes)),
                "runtime_data_root": runtime_data_root,
                "release_profile": release_profile,
                "source_release_id": source_release_id,
                "model_contract": dict(
                    model_contract or REQUIRED_MODEL_CONTRACT
                ),
                "test_results": dict(
                    test_results or _not_run_test_results()
                ),
                **(
                    {
                        "staging_generated_files": dict(
                            staging_generated_files
                        )
                    }
                    if staging_generated_files
                    else {}
                ),
            }
        )
    )


def substitute(value: Any, replacements: Mapping[str, str]) -> Any:
    if isinstance(value, dict):
        return {key: substitute(item, replacements) for key, item in value.items()}
    if isinstance(value, list):
        return [substitute(item, replacements) for item in value]
    if isinstance(value, str):
        result = value
        for marker, replacement in replacements.items():
            result = result.replace(marker, replacement)
        return result
    return value


