def _terminate_test_process_group(process: subprocess.Popen[str]) -> None:
    """Reap descendants left in the suite-owned process group."""

    try:
        os.killpg(process.pid, 0)
    except (ProcessLookupError, PermissionError):
        return
    for signal_number, timeout_seconds in ((15, 5.0), (9, 5.0)):
        try:
            os.killpg(process.pid, signal_number)
        except ProcessLookupError:
            return
        deadline = time.monotonic() + timeout_seconds
        while time.monotonic() < deadline:
            try:
                os.killpg(process.pid, 0)
            except ProcessLookupError:
                return
            time.sleep(0.05)


def _run_test_suite(
    command: Sequence[str],
    *,
    source_root: Path,
    environment: Mapping[str, str],
) -> subprocess.CompletedProcess[str]:
    process = subprocess.Popen(
        list(command),
        cwd=source_root,
        env=dict(environment),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        start_new_session=True,
    )
    try:
        stdout, stderr = process.communicate()
        return subprocess.CompletedProcess(
            list(command), process.returncode, stdout, stderr
        )
    finally:
        _terminate_test_process_group(process)


def run_tests(
    source_root: Path,
    historical_test_input_manifest: Path | None = None,
) -> dict[str, Any]:
    environment = dict(os.environ)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    environment.pop("STUDY_PREPROCESSOR_RUN_REAL_RUNTIME_TESTS", None)
    if historical_test_input_manifest is None:
        raise ReleaseError("historical_test_input_manifest_required")
    historical_input = historical_test_input_manifest.expanduser()
    if (
        not historical_input.is_absolute()
        or historical_input.is_symlink()
        or not historical_input.is_file()
        or historical_input.stat().st_mode & 0o222
    ):
        raise ReleaseError("historical_test_input_manifest_invalid")
    historical_input = historical_input.resolve()
    historical_input_sha256 = sha256_file(historical_input)
    if historical_input.name != f"{historical_input_sha256}.json":
        raise ReleaseError("historical_test_input_manifest_not_content_addressed")
    verifier = subprocess.run(
        [
            sys.executable,
            str(source_root / "scripts/historical_test_input.py"),
            "verify",
            "--manifest",
            str(historical_input),
        ],
        cwd=source_root,
        env=environment,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    if verifier.returncode != 0:
        raise ReleaseError("historical_test_input_manifest_verification_failed")
    environment["STUDY_PREPROCESSOR_HISTORICAL_TEST_INPUT_MANIFEST"] = str(
        historical_input
    )
    environment["STUDY_INTAKE_FIXTURE_EXECUTION"] = "1"
    legacy_parity_fixture = source_root / LEGACY_PARITY_FIXTURE
    if legacy_parity_fixture.is_file() and not legacy_parity_fixture.is_symlink():
        environment[LEGACY_PARITY_CONFIG_ENV] = str(legacy_parity_fixture)
    else:
        environment.pop(LEGACY_PARITY_CONFIG_ENV, None)
    commands = (
        (
            "core",
            [sys.executable, "-m", "unittest", *RELEASE_GATE_CORE_TESTS],
        ),
        (
            "dashboard",
            [sys.executable, "-m", "unittest", "discover", "-s", "dashboard/tests", "-p", "test_*.py"],
        ),
    )
    suites: list[dict[str, Any]] = []
    for name, command in commands:
        completed = _run_test_suite(
            command, source_root=source_root, environment=environment
        )
        if completed.returncode != 0:
            raise ReleaseError("release_tests_failed")
        count, skipped = _test_count(completed.stdout + completed.stderr)
        if skipped != 0:
            raise ReleaseError(f"release_tests_skipped:{name}:{skipped}")
        suites.append(
            {
                "name": name,
                "status": "passed",
                "test_count": count,
                "skipped_count": skipped,
                "historical_test_input_manifest_sha256": (
                    historical_input_sha256 if name == "core" else None
                ),
            }
        )
    return {
        "schema_version": "study-intake-release-test-results-v1",
        "status": "passed",
        "suites": suites,
        "formal_surface_gate": {
            "schema_version": FORMAL_GATE_SCHEMA,
            "status": "not_run",
            "verification_status": "not_run",
            "baseline_file_sha256": None,
            "config_file_sha256": None,
            "baseline_manifest_sha256": None,
            "current_manifest_sha256": None,
            "differences": None,
        },
        "real_model_call_count": 0,
        "formal_write_count": 0,
    }


def verify_formal_surfaces(
    source_root: Path,
    *,
    config_path: Path,
    baseline_path: Path,
) -> dict[str, Any]:
    """Run the independent content manifest verifier and bind its hashes.

    This gate intentionally does not trust a reported write counter.  The
    verifier re-reads and hashes every configured formal surface and compares
    those hashes with the caller-provided before snapshot.
    """

    source_root = source_root.resolve()
    tool = source_root / "bin" / "formal_surface_manifest.py"
    if not tool.is_file():
        # A strict legacy rollback snapshot can predate the guard utility.  The
        # current release manager's immutable guard still verifies that
        # snapshot's own configured formal roots.
        tool = SOURCE_ROOT / "bin" / "formal_surface_manifest.py"
    config = config_path.expanduser().resolve()
    baseline = baseline_path.expanduser().resolve()
    for path, code, limit in (
        (tool, "formal_surface_tool_invalid", 1024 * 1024),
        (config, "formal_surface_config_invalid", 4 * 1024 * 1024),
        (baseline, "formal_surface_baseline_invalid", 64 * 1024 * 1024),
    ):
        try:
            node = path.lstat()
        except OSError as exc:
            raise ReleaseError(code) from exc
        if (
            path.is_symlink()
            or not stat.S_ISREG(node.st_mode)
            or node.st_size <= 0
            or node.st_size > limit
        ):
            raise ReleaseError(code)
    try:
        guard_config = json.loads(config.read_text(encoding="utf-8"))
        release_template = json.loads(
            (source_root / "config.example.json").read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("formal_surface_config_invalid") from exc
    guard_adapters = guard_config.get("adapters")
    template_adapters = release_template.get("adapters")
    if not isinstance(guard_adapters, Mapping) or not isinstance(
        template_adapters, Mapping
    ):
        raise ReleaseError("formal_surface_config_binding_mismatch")
    for subject in ("math", "cs408", "english"):
        guard_adapter = guard_adapters.get(subject)
        template_adapter = template_adapters.get(subject)
        if (
            not isinstance(guard_adapter, Mapping)
            or not isinstance(template_adapter, Mapping)
            or guard_adapter.get("repo_root") != template_adapter.get("repo_root")
        ):
            raise ReleaseError("formal_surface_config_binding_mismatch")
    guard_snapshot = guard_config.get("cs408_knowledge_snapshot")
    template_snapshot = release_template.get("cs408_knowledge_snapshot")
    if (
        not isinstance(guard_snapshot, Mapping)
        or not isinstance(template_snapshot, Mapping)
        or guard_snapshot.get("sources") != template_snapshot.get("sources")
    ):
        raise ReleaseError("formal_surface_config_binding_mismatch")
    environment = dict(os.environ)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    completed = subprocess.run(
        [
            sys.executable,
            "-B",
            str(tool),
            "verify",
            "--config",
            str(config),
            "--baseline",
            str(baseline),
            "--all-subjects",
        ],
        cwd=source_root,
        env=environment,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    try:
        value = json.loads(completed.stdout)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("formal_surface_verification_invalid") from exc
    if (
        completed.returncode != 0
        or not isinstance(value, Mapping)
        or value.get("schema_version")
        != "study-intake-formal-surface-verification-v1"
        or value.get("subject_scope") != ["math", "cs408", "english"]
        or value.get("status") != "unchanged"
        or value.get("differences") != {}
        or not isinstance(value.get("baseline_manifest_sha256"), str)
        or SHA256_RE.fullmatch(str(value["baseline_manifest_sha256"])) is None
        or value.get("current_manifest_sha256")
        != value.get("baseline_manifest_sha256")
    ):
        raise ReleaseError("formal_surface_changed_or_unverified")
    return {
        "schema_version": FORMAL_GATE_SCHEMA,
        "status": "passed",
        "verification_status": "unchanged",
        "baseline_file_sha256": sha256_file(baseline),
        "config_file_sha256": sha256_file(config),
        "baseline_manifest_sha256": value["baseline_manifest_sha256"],
        "current_manifest_sha256": value["current_manifest_sha256"],
        "differences": {},
    }


def _load_historical_fixture(source_root: Path, manifest_path: Path) -> Any:
    module_path = source_root / "lib" / "historical_test_input.py"
    if module_path.is_symlink() or not module_path.is_file():
        raise ReleaseError("historical_test_input_loader_missing")
    module_name = (
        "_study_intake_historical_fixture_"
        + hashlib.sha256(str(module_path).encode()).hexdigest()[:16]
    )
    spec = importlib.util.spec_from_file_location(module_name, module_path)
    if spec is None or spec.loader is None:
        raise ReleaseError("historical_test_input_loader_invalid")
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    try:
        spec.loader.exec_module(module)
        return module.HistoricalTestInput.load(manifest_path)
    except Exception as exc:
        raise ReleaseError("historical_test_input_manifest_verification_failed") from exc
    finally:
        sys.modules.pop(module_name, None)


def verify_fixture_formal_surfaces(
    source_root: Path,
    *,
    historical_test_input_manifest: Path,
) -> dict[str, Any]:
    fixture = _load_historical_fixture(
        source_root, historical_test_input_manifest.expanduser().resolve()
    )
    fixture.verify_protected_collections()
    formal_rows = [
        row
        for row in fixture.payload.get("protected_collections", [])
        if isinstance(row, Mapping) and row.get("name") == "formal_surface"
    ]
    if len(formal_rows) != 1:
        raise ReleaseError("formal_surface_fixture_invalid")
    formal_digest = sha256_bytes(canonical_bytes(formal_rows[0]))
    return {
        "schema_version": FORMAL_GATE_SCHEMA,
        "status": "passed",
        "verification_status": "unchanged",
        "baseline_file_sha256": fixture.file_sha256,
        "config_file_sha256": sha256_file(source_root / "config.example.json"),
        "baseline_manifest_sha256": formal_digest,
        "current_manifest_sha256": formal_digest,
        "differences": {},
    }


def _prepare_staging_generated_files(
    source_root: Path,
    *,
    hashes: Mapping[str, str],
    modes: Mapping[str, int],
    verification_root: Path,
) -> tuple[tempfile.TemporaryDirectory[str], Path, dict[str, str]]:
    holder = tempfile.TemporaryDirectory(prefix="study-intake-generated-")
    prepared = Path(holder.name)
    for relative in hashes:
        source = source_root / relative
        target = prepared / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
        # The preparation tree is private and disposable.  Keep its source
        # copies owner-writable while the sole generator runs; the immutable
        # release is sealed only after generated bytes have been compared.
        target.chmod(modes[relative] | stat.S_IWUSR)
    generator = (
        prepared
        / "plugin/kaoyan-study-intake/scripts/generate_manifests.py"
    )
    if not generator.is_file():
        return holder, prepared, {}
    completed = subprocess.run(
        [
            sys.executable,
            str(generator),
            "--verification-root",
            str(verification_root),
        ],
        cwd=generator.parents[1],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    if completed.returncode != 0:
        raise ReleaseError("release_component_generator_failed")
    for relative, expected in hashes.items():
        path = prepared / relative
        if not path.is_file() or sha256_file(path) != expected:
            raise ReleaseError(f"release_generator_unexpected_source_change:{relative}")
    lock_relative = "plugin/kaoyan-study-intake/component-lock.json"
    lock_path = prepared / lock_relative
    if lock_path.is_symlink() or not lock_path.is_file():
        raise ReleaseError("release_component_lock_generation_failed")
    freeze_relative = "validation/source-freeze-sha256-final-20260813.txt"
    freeze_path = prepared / freeze_relative
    freeze_path.parent.mkdir(parents=True, exist_ok=True)
    freeze_rows = dict(hashes)
    freeze_rows[lock_relative] = sha256_file(lock_path)
    freeze_path.write_text(
        "".join(
            f"{digest}  ./{relative}\n"
            for relative, digest in sorted(freeze_rows.items())
        ),
        encoding="utf-8",
    )
    generated = {
        lock_relative: sha256_file(lock_path),
        freeze_relative: sha256_file(freeze_path),
    }
    for relative in generated:
        (prepared / relative).chmod(SEALED_GENERATED_MODE)
    return holder, prepared, generated


def _component_inventory(
    source: Mapping[str, str],
    generated: Mapping[str, str],
    service_topology: Sequence[Mapping[str, str]],
) -> dict[str, dict[str, str]]:
    programs = {
        path: digest
        for path, digest in source.items()
        if Path(path).parts[0] in {"bin", "lib", "dashboard", "scripts"}
    }
    schemas = {
        path: digest
        for path, digest in source.items()
        if Path(path).parts[0] == "schemas"
    }
    evidence_rules = {
        path: digest
        for path, digest in schemas.items()
        if any(
            token in Path(path).name
            for token in ("evidence", "controlled-contract", "trace-supplement")
        )
    }
    service_configs = {
        str(service["template"]): source[str(service["template"])]
        for service in service_topology
    }
    configuration = {
        "config.example.json": source["config.example.json"],
        **dict(sorted(generated.items())),
    }
    plugins = {
        path: digest
        for path, digest in source.items()
        if Path(path).parts[0] == "plugin"
    }
    return {
        "programs": programs,
        "configuration": configuration,
        "evidence_rules": evidence_rules,
        "data_formats": schemas,
        "service_configurations": service_configs,
        "plugins": plugins,
    }


def _component_inventory_for_profile(
    source: Mapping[str, str],
    generated: Mapping[str, str],
    service_topology: Sequence[Mapping[str, str]],
    *,
    profile: str,
) -> dict[str, dict[str, str]]:
    value = _component_inventory(source, generated, service_topology)
    if profile == "full":
        return value
    if profile == "pre_plugins":
        value.pop("plugins", None)
        return value
    raise ReleaseError("release_component_inventory_profile_invalid")


def _model_contract_config_matches(
    model: Mapping[str, Any], model_contract: Mapping[str, Any]
) -> bool:
    if (
        model.get("model") != model_contract.get("model")
        or model.get("reasoning_effort")
        != model_contract.get("reasoning_effort")
    ):
        return False
    if model_contract == REQUIRED_MODEL_CONTRACT:
        return "service_tier" not in model
    if "service_tier" in model_contract:
        return model.get("service_tier") == model_contract["service_tier"]
    return "service_tier" not in model


def _external_runtime_source_sha256(
    raw_path: Any, *, source_name: str
) -> str:
    error_code = f"release_{source_name}_invalid"
    if not isinstance(raw_path, str) or not raw_path:
        raise ReleaseError(error_code)
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        raise ReleaseError(error_code)
    try:
        before = path.lstat()
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
            raise ReleaseError(error_code)
        if not os.access(path, os.R_OK):
            raise ReleaseError(error_code)
        raw = path.read_bytes()
        after = path.lstat()
    except ReleaseError:
        raise
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if (
        stat.S_ISLNK(after.st_mode)
        or not stat.S_ISREG(after.st_mode)
        or (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
        != (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
        or len(raw) != before.st_size
    ):
        raise ReleaseError(error_code)
    return hashlib.sha256(raw).hexdigest()


def _external_status_script_sha256(
    config: Mapping[str, Any], subject: str
) -> str:
    adapters = config.get("adapters")
    adapter = adapters.get(subject) if isinstance(adapters, Mapping) else None
    raw_path = adapter.get("status_script") if isinstance(
        adapter, Mapping
    ) else None
    return _external_runtime_source_sha256(
        raw_path,
        source_name=f"{subject}_status_script",
    )


def _verify_target_external_status_script_contract(
    config: Mapping[str, Any], *, release_root: Path
) -> None:
    invalid = "release_external_runtime_source_binding_mismatch"
    adapters = config.get("adapters")
    math_adapter = adapters.get("math") if isinstance(adapters, Mapping) else None
    cs408_adapter = adapters.get("cs408") if isinstance(adapters, Mapping) else None
    english_adapter = adapters.get("english") if isinstance(adapters, Mapping) else None
    configured_paths = {
        "math_status_script": (
            math_adapter.get("status_script")
            if isinstance(math_adapter, Mapping)
            else None
        ),
        "cs408_status_script": (
            cs408_adapter.get("status_script")
            if isinstance(cs408_adapter, Mapping)
            else None
        ),
        "english_events_module": (
            str(
                Path(str(english_adapter.get("repo_root")))
                / "english_pipeline"
                / "events.py"
            )
            if isinstance(english_adapter, Mapping)
            and isinstance(english_adapter.get("repo_root"), str)
            and english_adapter.get("repo_root")
            else None
        ),
    }
    probe = (
        "import json,sys; from pathlib import Path; "
        "sys.path.insert(0,sys.argv[1]); import preprocessor_core as p; "
        "cfg=p.load_config(Path(sys.argv[2])); "
        "contract=p.cs408_processing_contract(cfg); "
        "print(json.dumps({'status_script_sha256':"
        "contract.get('status_script_sha256') if contract else None,"
        "'processing_contract_sha256':"
        "contract.get('processing_contract_sha256') if contract else None},"
        "sort_keys=True))"
    )
    environment = dict(os.environ)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    try:
        completed = subprocess.run(
            [
                sys.executable,
                "-B",
                "-c",
                probe,
                str(release_root / "lib"),
                str(release_root / "config.json"),
            ],
            cwd=release_root,
            env=environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise ReleaseError("release_cs408_status_contract_probe_failed") from exc
    try:
        value = json.loads(completed.stdout)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("release_cs408_status_contract_probe_failed") from exc
    try:
        plugin_root = release_root / "plugin" / "kaoyan-study-intake"
        component_lock = json.loads(
            (plugin_root / "component-lock.json").read_text(encoding="utf-8")
        )
        component_registry = json.loads(
            (plugin_root / "components.json").read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError(invalid) from exc
    external_sources = component_lock.get("external_runtime_sources")
    registry_sources = component_registry.get("external_runtime_sources")
    source_names = (
        frozenset(external_sources)
        if isinstance(external_sources, Mapping)
        else frozenset()
    )
    if (
        not isinstance(registry_sources, Mapping)
        or external_sources != registry_sources
        or source_names
        not in {
            LEGACY_EXTERNAL_RUNTIME_SOURCE_NAMES,
            CURRENT_EXTERNAL_RUNTIME_SOURCE_NAMES,
        }
    ):
        raise ReleaseError(invalid)
    hashes: dict[str, str] = {}
    for source_name in sorted(source_names):
        source = external_sources.get(source_name)
        configured_path = configured_paths.get(source_name)
        if (
            not isinstance(source, Mapping)
            or set(source) != {"path", "sha256"}
            or source.get("path") != configured_path
        ):
            raise ReleaseError(invalid)
        observed = _external_runtime_source_sha256(
            configured_path,
            source_name=source_name,
        )
        if source.get("sha256") != observed:
            raise ReleaseError(invalid)
        hashes[source_name] = observed
    if (
        completed.returncode != 0
        or not isinstance(value, Mapping)
        or value.get("status_script_sha256")
        != hashes["cs408_status_script"]
        or SHA256_RE.fullmatch(
        str(value.get("processing_contract_sha256") or "")
        )
        is None
    ):
        raise ReleaseError(invalid)


def _validate_target_release_config(
    config: Mapping[str, Any],
    *,
    release_root: Path,
    required_model_contract: Mapping[str, Any] | None = None,
) -> None:
    target_model_contract = dict(
        required_model_contract or REQUIRED_MODEL_CONTRACT
    )
    model = config.get("model")
    dispatch = config.get("dispatch")
    canary = (
        dispatch.get("production_canary")
        if isinstance(dispatch, Mapping)
        else None
    )
    expected_package_schema = str(
        release_root / "schemas" / "preprocess-package-v3.json"
    )
    expected_package_schema_path = Path(expected_package_schema)
    package_profiles = tuple(
        config.get(name)
        for name in (
            "math_deep_v2",
            "cs408_deep_v2",
            "english_two_pass_v1",
        )
    )
    models = config.get("models")
    live_gate = config.get("live_execution_gate")
    scheduler = config.get("branch_scheduler")
    expected_roles = target_model_contract.get("roles")
    multi_agent_contract_required = isinstance(expected_roles, Mapping)
    role_config_valid = (
        isinstance(models, Mapping) and set(models) == set(expected_roles)
        if multi_agent_contract_required
        else True
    )
    if role_config_valid and multi_agent_contract_required:
        for role, expected in expected_roles.items():
            supplied = models.get(role)
            expected_agent_path = str(release_root / expected["agent_config"])
            expected_policy_path = str(release_root / expected["tool_policy"])
            if (
                not isinstance(supplied, Mapping)
                or supplied.get("model") != expected["model"]
                or supplied.get("reasoning_effort")
                != expected["reasoning_effort"]
                or supplied.get("agents_enabled")
                is not expected["agents_enabled"]
                or supplied.get("agent_config_path") != expected_agent_path
                or supplied.get("tool_policy_path") != expected_policy_path
                or sha256_file(Path(expected_agent_path))
                != expected["agent_config_sha256"]
                or sha256_file(Path(expected_policy_path))
                != expected["tool_policy_sha256"]
                or (
                    role == "reader"
                    and (
                        supplied.get("sandbox_mode") != "read-only"
                        or supplied.get("fresh_context") is not True
                    )
                )
                or (
                    role == "critical_reviewer"
                    and (
                        supplied.get("sandbox_mode") != "read-only"
                        or supplied.get("fresh_context") is not True
                    )
                )
            ):
                role_config_valid = False
                break
    if (
        not isinstance(model, Mapping)
        or not _model_contract_config_matches(model, target_model_contract)
        or (
            multi_agent_contract_required
            and (
                config.get("execution_mode") != "offline"
                or not role_config_valid
                or not isinstance(live_gate, Mapping)
                or live_gate.get("enabled") is not True
                or live_gate.get("default_locked") is not True
                or live_gate.get("authorization_required") is not True
                or not isinstance(scheduler, Mapping)
                or scheduler.get("logical_branch_limit") is not None
                or scheduler.get("physical_concurrency_mode") != "dynamic"
                or scheduler.get("overflow_policy") != "queue_in_waves"
                or scheduler.get("drop_policy") != "never"
            )
        )
        or any(not isinstance(profile, Mapping) for profile in package_profiles)
        or expected_package_schema_path.is_symlink()
        or not expected_package_schema_path.is_file()
        or any(
            profile.get("package_output_schema") != expected_package_schema
            for profile in package_profiles
            if isinstance(profile, Mapping)
        )
        or not isinstance(canary, Mapping)
        or set(canary)
        != {
            "enabled",
            "status",
            "admission",
            "keep_backlog_drained",
            "post_activation_only",
            "initial_canary_inflight_limit",
            "continuous_concurrency_limit",
        }
        or canary.get("enabled") is not True
        or canary.get("status") != "production_canary_active"
        or canary.get("admission")
        != "first_post_activation_producer_capture"
        or canary.get("keep_backlog_drained") is not True
        or canary.get("post_activation_only") is not True
        or canary.get("initial_canary_inflight_limit")
        != INITIAL_CANARY_INFLIGHT_LIMIT
        or canary.get("continuous_concurrency_limit")
        != CONTINUOUS_CONCURRENCY_LIMIT
    ):
        raise ReleaseError("release_target_contract_invalid")


def _render_sealed_plugin_launcher(runtime: Mapping[str, Any]) -> bytes:
    flags = runtime.get("python_flags")
    if flags != ["-I", "-S"]:
        raise ReleaseError("release_mcp_sealed_binding_invalid")
    quoted = {
        key: shlex.quote(str(runtime.get(key) or ""))
        for key in (
            "python_executable",
            "sealed_launcher_path",
            "release_root",
            "release_id",
            "release_manifest_sha256",
        )
    }
    lines = [
        "#!/bin/sh",
        "set -eu",
        "exec /usr/bin/env -i \\",
        "  PATH=/usr/bin:/bin \\",
        "  PYTHONUTF8=1 \\",
        "  PYTHONDONTWRITEBYTECODE=1 \\",
        "  PYTHONNOUSERSITE=1 \\",
        "  PYTHONSAFEPATH=1 \\",
        f"  {quoted['python_executable']} \\",
        "  -I \\",
        "  -S \\",
        f"  {quoted['sealed_launcher_path']} \\",
        f"  --release-root {quoted['release_root']} \\",
        f"  --expected-release-id {quoted['release_id']} \\",
        "  --expected-release-manifest-sha256 "
        f"{quoted['release_manifest_sha256']} \\",
        "  --mode server \\",
        '  "$@"',
    ]
    return ("\n".join(lines) + "\n").encode("utf-8")


def _verify_target_sealed_mcp_binding(
    release_root: Path,
    config: Mapping[str, Any],
) -> None:
    """Reopen the complete Study-to-MCP launch chain and fail closed on drift."""

    invalid = "release_mcp_sealed_binding_invalid"
    plugin_root = release_root / "plugin" / "kaoyan-study-intake"
    try:
        components_path = plugin_root / "components.json"
        lock_path = plugin_root / "component-lock.json"
        wrapper_path = plugin_root / "bin" / "kaoyan-read"
        components = json.loads(components_path.read_text(encoding="utf-8"))
        lock = json.loads(lock_path.read_text(encoding="utf-8"))
        processing = config.get("processing_plugin")
        mcp = components.get("mcp") if isinstance(components, Mapping) else None
        runtime = lock.get("mcp_sealed_runtime") if isinstance(lock, Mapping) else None
        if (
            not isinstance(processing, Mapping)
            or not isinstance(mcp, Mapping)
            or not isinstance(runtime, Mapping)
        ):
            raise ReleaseError(invalid)
        expected_runtime = {
            "python_executable": mcp.get("python_executable"),
            "python_flags": mcp.get("python_flags"),
            "sealed_launcher_path": mcp.get("sealed_launcher_path"),
            "sealed_launcher_sha256": mcp.get("sealed_launcher_sha256"),
            "release_root": mcp.get("release_root"),
            "release_id": mcp.get("release_id"),
            "release_manifest_sha256": mcp.get("release_manifest_sha256"),
        }
        if runtime != expected_runtime or set(runtime) != set(expected_runtime):
            raise ReleaseError(invalid)
        mcp_root = Path(str(runtime.get("release_root") or ""))
        python_executable = Path(str(runtime.get("python_executable") or ""))
        launcher_path = Path(str(runtime.get("sealed_launcher_path") or ""))
        manifest_path = mcp_root / "release.json"
        release_id = runtime.get("release_id")
        if (
            runtime.get("python_flags") != ["-I", "-S"]
            or not mcp_root.is_absolute()
            or mcp_root.is_symlink()
            or not mcp_root.is_dir()
            or not isinstance(release_id, str)
            or SHA256_RE.fullmatch(release_id) is None
            or mcp_root.name != release_id
            or not python_executable.is_absolute()
            or not python_executable.is_file()
            or not os.access(python_executable, os.X_OK)
            or launcher_path != mcp_root / "scripts" / "sealed_launcher.py"
            or launcher_path.is_symlink()
            or not launcher_path.is_file()
            or manifest_path.is_symlink()
            or not manifest_path.is_file()
            or stat.S_IMODE(manifest_path.lstat().st_mode) != 0o444
            or stat.S_IMODE(launcher_path.lstat().st_mode) != 0o444
            or sha256_file(launcher_path) != runtime.get("sealed_launcher_sha256")
            or sha256_file(manifest_path) != runtime.get("release_manifest_sha256")
            or mcp.get("release_manifest") != str(manifest_path)
        ):
            raise ReleaseError(invalid)
        launcher_text = launcher_path.read_text(encoding="utf-8")
        if (
            "sys.path.append(str(dependency_root))" not in launcher_text
            or "unlike site.addsitedir" not in launcher_text
            or '        "-I",\n        "-S",' not in launcher_text
        ):
            raise ReleaseError(invalid)
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        source_files = manifest.get("source_files") if isinstance(manifest, Mapping) else None
        if (
            manifest.get("schema_version") != "study-read-mcp-release.v1"
            or manifest.get("release_id") != release_id
            or manifest.get("formal_write_count") != 0
            or not isinstance(source_files, Mapping)
            or not source_files
            or hashlib.sha256(canonical_bytes(dict(source_files))).hexdigest()
            != release_id
            or source_files.get("scripts/sealed_launcher.py")
            != runtime.get("sealed_launcher_sha256")
        ):
            raise ReleaseError(invalid)
        for relative, expected_sha256 in source_files.items():
            if not isinstance(relative, str) or not isinstance(expected_sha256, str):
                raise ReleaseError(invalid)
            relative_path = Path(relative)
            source_path = mcp_root / relative_path
            if (
                relative_path.is_absolute()
                or ".." in relative_path.parts
                or SHA256_RE.fullmatch(expected_sha256) is None
                or source_path.is_symlink()
                or not source_path.is_file()
                or stat.S_IMODE(source_path.lstat().st_mode) != 0o444
                or sha256_file(source_path) != expected_sha256
            ):
                raise ReleaseError(invalid)
        policy = json.loads(
            (mcp_root / "config" / "skill-tool-policy.json").read_text(
                encoding="utf-8"
            )
        )
        expected_profiles = {
            "ordinary": {
                "mode": "server",
                "profile": "ordinary",
                "subjects": "math,cs408,english",
            },
            "background": {
                "mode": "client",
                "profile": "background",
                "subject": "required",
            },
            "morning_preparation": {
                "mode": "client",
                "profile": "morning_preparation",
                "subject": "cs408",
            },
            "analysis": {
                "mode": "subject-server",
                "subject": "required",
                "read_session_manifest": "required",
                "preprocessor_root": "required",
            },
            "critical_review": {
                "mode": "subject-server",
                "subject": "required",
                "read_session_manifest": "required",
                "preprocessor_root": "required",
            },
            "infrastructure_preflight": {
                "mode": "preflight-server",
                "subject": "required",
                "preflight_session_manifest": "required",
                "preprocessor_root": "required",
                "tool_policy": "required",
            },
            "authority_snapshot": {
                "mode": "snapshot",
                "subject": "required",
                "source_root": "required",
                "output_root": "required",
            },
        }
        expected_launcher_contract = {
            "schema_version": "study-read-mcp-sealed-launcher.v1",
            "required_component_fields": [
                "python_executable",
                "release_root",
                "release_id",
                "release_manifest_sha256",
                "sealed_launcher_path",
                "sealed_launcher_sha256",
            ],
            "python_flags": ["-I", "-S"],
            "modes": [
                "server",
                "client",
                "subject-server",
                "preflight-server",
                "snapshot",
            ],
            "environment_allowlist": [
                "PATH",
                "PYTHONUTF8",
                "PYTHONDONTWRITEBYTECODE",
                "PYTHONNOUSERSITE",
                "PYTHONSAFEPATH",
                "PYTHONPATH",
                "STUDY_READ_MCP_EXPECTED_PROJECT_ROOT",
                "STUDY_READ_MCP_EXPECTED_RELEASE_ID",
                "STUDY_READ_MCP_EXPECTED_RELEASE_MANIFEST_SHA256",
            ],
        }
        if (
            policy.get("schema_version") != "study-read-mcp-policy.v4"
            or policy.get("sealed_launcher_contract")
            != expected_launcher_contract
            or policy.get("production_launcher_profiles") != expected_profiles
            or policy.get("subject_preflight_tools")
            != [
                "list_records",
                "get_records",
                "search_records",
                "query_relations",
            ]
        ):
            raise ReleaseError(invalid)
        if (
            lock.get("schema_version")
            != "kaoyan-study-intake-component-lock.v1"
            or lock.get("registry_sha256") != sha256_file(components_path)
            or lock.get("launcher_sha256") != sha256_file(wrapper_path)
            or lock.get("mcp_release_root") != str(mcp_root)
            or lock.get("mcp_release_id") != release_id
            or lock.get("mcp_release_manifest_sha256")
            != runtime.get("release_manifest_sha256")
            or lock.get("mcp_server_release") != manifest.get("server_release")
            or wrapper_path.read_bytes() != _render_sealed_plugin_launcher(runtime)
            or processing.get("root") != str(plugin_root)
            or processing.get("component_lock_path") != str(lock_path)
            or processing.get("mcp_client_python") != str(python_executable)
            or processing.get("mcp_project_root") != str(mcp_root)
            or processing.get("profile") != "background"
        ):
            raise ReleaseError(invalid)
        _render_ordinary_mcp_profile(runtime)
        for subject in ("math", "cs408", "english"):
            component_server = mcp.get("luna_servers", {}).get(subject)
            locked_server = lock.get("luna_mcp_servers", {}).get(subject)
            if (
                component_server
                != {
                    "server_name": f"kaoyan_{subject}_read",
                    "launch_mode": "subject-server",
                }
                or not isinstance(locked_server, Mapping)
                or locked_server.get("server_name") != f"kaoyan_{subject}_read"
                or locked_server.get("launch_mode") != "subject-server"
                or "executable" in locked_server
            ):
                raise ReleaseError(invalid)
    except ReleaseError:
        raise
    except (OSError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ReleaseError(invalid) from exc


def _historical_release_contract(
    model_contract: Mapping[str, Any],
) -> Mapping[str, Any] | None:
    for descriptor in HISTORICAL_ROLLBACK_RELEASE_CONTRACTS:
        if model_contract == descriptor["model_contract"]:
            return descriptor
    return None


def git_commit(source_root: Path) -> str | None:
    completed = subprocess.run(
        ["git", "rev-parse", "HEAD"],
        cwd=source_root,
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True,
        check=False,
    )
    value = completed.stdout.strip()
    return value if completed.returncode == 0 and len(value) == 40 else None


def _clear_extended_metadata(path: Path) -> None:
    if hasattr(os, "chflags"):
        try:
            os.chflags(path, 0, follow_symlinks=False)
        except (NotImplementedError, OSError):
            pass
    try:
        attributes = os.listxattr(path, follow_symlinks=False)
    except (AttributeError, NotImplementedError, OSError):
        attributes = []
    for attribute in attributes:
        try:
            os.removexattr(path, attribute, follow_symlinks=False)
        except (NotImplementedError, OSError):
            pass
    if sys.platform == "darwin":
        subprocess.run(
            ["chmod", "-N", str(path)],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            check=False,
        )


def _node_has_acl(path: Path) -> bool:
    try:
        attributes = os.listxattr(path, follow_symlinks=False)
    except (AttributeError, NotImplementedError, OSError):
        attributes = []
    if any(
        attribute
        in {"com.apple.acl.text", "system.posix_acl_access", "system.posix_acl_default"}
        for attribute in attributes
    ):
        return True
    if sys.platform != "darwin":
        return False
    completed = subprocess.run(
        ["ls", "-lde", str(path)],
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True,
        check=False,
    )
    first = completed.stdout.splitlines()[0].split(maxsplit=1)[0] if completed.stdout else ""
    return first.endswith("+")


def _verify_clean_metadata(path: Path) -> None:
    node_stat = path.lstat()
    if getattr(node_stat, "st_flags", 0):
        raise ReleaseError("release_node_flags_present")
    try:
        attributes = os.listxattr(path, follow_symlinks=False)
    except (AttributeError, NotImplementedError, OSError):
        attributes = []
    if attributes:
        raise ReleaseError("release_node_xattrs_present")
    if _node_has_acl(path):
        raise ReleaseError("release_node_acl_present")


def _directory_metadata(paths: Iterable[str]) -> dict[str, dict[str, int | str]]:
    return {
        relative: {
            "uid": os.getuid(),
            "gid": os.getgid(),
            "mode": SEALED_DIRECTORY_MODE,
            "type": "directory",
        }
        for relative in sorted(paths)
    }


def _seal_release_tree(root: Path) -> None:
    directories = [root]
    for path in root.rglob("*"):
        if path.is_symlink():
            raise ReleaseError("release_tree_symlink_forbidden")
        if path.is_dir():
            directories.append(path)
    for directory in sorted(directories, key=lambda item: len(item.parts), reverse=True):
        _clear_extended_metadata(directory)
        directory.chmod(SEALED_DIRECTORY_MODE)


def _make_tree_removable(root: Path) -> None:
    """Make one exact, newly built tree removable after a failed publication."""

    if not root.exists() or root.is_symlink():
        return
    directories = [root]
    for current, names, files in os.walk(root, topdown=True, followlinks=False):
        current_path = Path(current)
        for name in names:
            path = current_path / name
            if not path.is_symlink():
                directories.append(path)
        for name in files:
            path = current_path / name
            if not path.is_symlink():
                path.chmod(0o600)
    for directory in sorted(directories, key=lambda item: len(item.parts)):
        directory.chmod(0o700)


def _fsync_directory(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY)
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def build_release(
    *,
    source_root: Path,
    release_base: Path,
    runtime_data_root: Path,
    skip_tests: bool,
    release_profile: str = "concurrent_v2",
    source_release_id: str | None = None,
    formal_config: Path | None = None,
    formal_baseline: Path | None = None,
    historical_test_input_manifest: Path | None = None,
    model_contract: Mapping[str, Any] | None = None,
    component_inventory_profile: str = "full",
) -> dict[str, Any]:
    source_root = source_root.resolve()
    release_base = _safe_base(release_base, label="release_base")
    runtime_data_root = _safe_base(runtime_data_root, label="runtime_data_root")
    if release_profile not in RELEASE_PROFILES:
        raise ReleaseError("release_profile_invalid")
    effective_model_contract = dict(model_contract or REQUIRED_MODEL_CONTRACT)
    if release_profile == "legacy_monolith":
        if not isinstance(source_release_id, str) or SHA256_RE.fullmatch(source_release_id) is None:
            raise ReleaseError("legacy_source_release_id_required")
    else:
        if source_release_id is not None:
            raise ReleaseError("concurrent_source_release_id_forbidden")
        if effective_model_contract != REQUIRED_MODEL_CONTRACT:
            raise ReleaseError("concurrent_target_model_contract_required")
        if component_inventory_profile != "full":
            raise ReleaseError("concurrent_target_component_inventory_required")
    if (formal_config is None) != (formal_baseline is None):
        raise ReleaseError("formal_surface_gate_arguments_incomplete")
    if not skip_tests and historical_test_input_manifest is None:
        raise ReleaseError("historical_test_input_manifest_required")
    plugin_generator_root = (
        source_root / "plugin" / "kaoyan-study-intake"
    )
    plugin_generator = (
        plugin_generator_root / "scripts" / "generate_manifests.py"
    )
    fixture = None
    if historical_test_input_manifest is not None:
        fixture = _load_historical_fixture(
            source_root,
            historical_test_input_manifest.expanduser().resolve(),
        )
    if (
        release_profile == "concurrent_v2"
        and plugin_generator.is_file()
        and fixture is None
    ):
        raise ReleaseError("historical_test_input_manifest_required")
    test_results = (
        _not_run_test_results()
        if skip_tests
        else run_tests(source_root, historical_test_input_manifest)
    )
    if fixture is not None:
        test_results["formal_surface_gate"] = verify_fixture_formal_surfaces(
            source_root,
            historical_test_input_manifest=historical_test_input_manifest,
        )
    hashes = source_hashes(source_root)
    modes = source_modes(source_root)
    owners = file_owners(hashes)
    if not hashes or "config.example.json" not in hashes:
        raise ReleaseError("release_source_incomplete")
    if set(modes) != set(hashes):
        raise ReleaseError("release_source_mode_incomplete")
    generated_holder: tempfile.TemporaryDirectory[str] | None = None
    generated_root: Path | None = None
    staging_generated: dict[str, str] = {}
    if fixture is not None and plugin_generator.is_file():
        generated_holder, generated_root, staging_generated = (
            _prepare_staging_generated_files(
                source_root,
                hashes=hashes,
                modes=modes,
                verification_root=fixture.verification_root,
            )
        )
    runtime_data_root_value = str(runtime_data_root)
    release_id = release_id_for(
        hashes,
        modes,
        runtime_data_root_value,
        owners,
        release_profile,
        source_release_id,
        effective_model_contract,
        test_results,
        staging_generated,
    )
    releases = release_base / "releases"
    releases.mkdir(parents=True, exist_ok=True)
    destination = releases / release_id
    if destination.exists():
        verified = _verify_release_with_model_contract(
            destination,
            effective_model_contract,
            component_inventory_profile=component_inventory_profile,
            verify_live_runtime_bindings=False,
        )
        return {**verified, "status": "already_built"}

    staging = Path(tempfile.mkdtemp(prefix=".staging-", dir=releases))
    published = False
    try:
        for relative in hashes:
            source = source_root / relative
            target = staging / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source, target)
            _clear_extended_metadata(target)
            target.chmod(modes[relative])

        if staging_generated:
            if generated_root is None:
                raise ReleaseError("release_generated_staging_missing")
            for relative, expected in staging_generated.items():
                source = generated_root / relative
                target = staging / relative
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(source, target)
                _clear_extended_metadata(target)
                target.chmod(SEALED_GENERATED_MODE)
                if sha256_file(target) != expected:
                    raise ReleaseError("release_generated_staging_drift")

        template_path = staging / "config.example.json"
        template = json.loads(template_path.read_text(encoding="utf-8"))
        rendered = substitute(
            template,
            {
                "${RELEASE_ROOT}": str(destination),
                "${RUNTIME_DATA_ROOT}": runtime_data_root_value,
            },
        )
        atomic_json(staging / "config.json", rendered, mode=SEALED_GENERATED_MODE)
        _clear_extended_metadata(staging / "config.json")
        generated = {
            **staging_generated,
            "config.json": sha256_file(staging / "config.json"),
        }
        generated_modes = {
            name: SEALED_GENERATED_MODE for name in generated
        }
        if release_profile == "legacy_monolith":
            legacy_runtime_manifest = {
                "schema_version": "study-intake-preprocessor-release-v1",
                "release_id": release_id,
                "source_tree_sha256": release_id,
                "runtime_data_root": runtime_data_root_value,
                "release_profile": "legacy_monolith",
                "source_release_id": source_release_id,
                "formal_write_count": 0,
            }
            legacy_runtime_path = staging / LEGACY_RUNTIME_MANIFEST
            atomic_json(
                legacy_runtime_path,
                legacy_runtime_manifest,
                mode=SEALED_GENERATED_MODE,
            )
            _clear_extended_metadata(legacy_runtime_path)
            generated[LEGACY_RUNTIME_MANIFEST] = sha256_file(
                legacy_runtime_path
            )
            generated_modes[LEGACY_RUNTIME_MANIFEST] = SEALED_GENERATED_MODE
        generated_owners = file_owners(generated)
        service_topology = list(RELEASE_PROFILES[release_profile])
        component_inventory = _component_inventory_for_profile(
            hashes,
            generated,
            service_topology,
            profile=component_inventory_profile,
        )
        expected_files = set(hashes) | set(generated) | {"release.json"}
        directories = _directory_metadata(_expected_directories(expected_files))
        manifest = {
            "schema_version": SCHEMA_VERSION,
            "release_id": release_id,
            "release_profile": release_profile,
            "source_release_id": source_release_id,
            "source_tree_sha256": release_id,
            "runtime_data_root": runtime_data_root_value,
            "source_files": hashes,
            "source_modes": modes,
            "source_owners": owners,
            "generated_files": generated,
            "generated_modes": generated_modes,
            "generated_owners": generated_owners,
            "directories": directories,
            "manifest_metadata": {
                "uid": os.getuid(),
                "gid": os.getgid(),
                "mode": SEALED_MANIFEST_MODE,
                "type": "file",
            },
            "service_topology": service_topology,
            "component_inventory": component_inventory,
            "model_contract": effective_model_contract,
            "test_results": test_results,
            "formal_write_count": 0,
        }
        atomic_json(staging / "release.json", manifest, mode=SEALED_MANIFEST_MODE)
        _clear_extended_metadata(staging / "release.json")
        _seal_release_tree(staging)
        os.replace(staging, destination)
        published = True
        _fsync_directory(releases)
        verified = _verify_release_with_model_contract(
            destination,
            effective_model_contract,
            component_inventory_profile=component_inventory_profile,
            verify_live_runtime_bindings=False,
        )
    except Exception:
        cleanup = destination if published else staging
        if cleanup.exists() and cleanup.parent == releases:
            _make_tree_removable(cleanup)
            shutil.rmtree(cleanup)
            _fsync_directory(releases)
        elif staging.exists() and staging.parent == releases:
            _make_tree_removable(staging)
            shutil.rmtree(staging)
        raise
    return {**verified, "status": "built"}


def _safe_relative_file(relative: Any, *, label: str) -> Path:
    if not isinstance(relative, str) or not relative:
        raise ReleaseError(f"{label}_entry_invalid")
    path = Path(relative)
    if (
        path.is_absolute()
        or path == Path(".")
        or any(part in {"", ".", ".."} for part in path.parts)
        or path.as_posix() != relative
    ):
        raise ReleaseError(f"{label}_path_invalid")
    return path


def _source_path_allowed(relative: str) -> bool:
    path = Path(relative)
    if "__pycache__" in path.parts or path.suffix in {".pyc", ".pyo"}:
        return False
    return (
        len(path.parts) >= 2 and path.parts[0] in ALLOWED_SOURCE_DIRS
    ) or relative in ALLOWED_ROOT_FILES


def _verify_hashes(root: Path, values: Mapping[str, Any], *, label: str) -> None:
    for relative, expected in values.items():
        path_relative = _safe_relative_file(relative, label=label)
        if not isinstance(expected, str) or SHA256_RE.fullmatch(expected) is None:
            raise ReleaseError(f"{label}_entry_invalid")
        path = root / path_relative
        if not path.is_file() or sha256_file(path) != expected:
            raise ReleaseError(f"{label}_hash_mismatch")


def _verify_modes(
    root: Path,
    values: Mapping[str, Any],
    *,
    label: str,
) -> None:
    for relative, expected in values.items():
        path_relative = _safe_relative_file(relative, label=label)
        if (
            isinstance(expected, bool)
            or not isinstance(expected, int)
            or not 0 <= expected <= 0o777
            or expected & 0o222
        ):
            raise ReleaseError(f"{label}_entry_invalid")
        path = root / path_relative
        if not path.is_file() or stat.S_IMODE(path.stat().st_mode) != expected:
            raise ReleaseError(f"{label}_mismatch")


def _verify_owners(
    root: Path,
    values: Mapping[str, Any],
    *,
    expected_paths: Iterable[str],
    label: str,
) -> None:
    expected_set = set(expected_paths)
    if set(values) != expected_set:
        raise ReleaseError(f"{label}_identity_mismatch")
    for relative, expected in values.items():
        path_relative = _safe_relative_file(relative, label=label)
        if not isinstance(expected, Mapping) or expected.get("type") != "file":
            raise ReleaseError(f"{label}_identity_mismatch")
        node_stat = (root / path_relative).lstat()
        if (
            not stat.S_ISREG(node_stat.st_mode)
            or expected.get("uid") != node_stat.st_uid
            or expected.get("gid") != node_stat.st_gid
        ):
            raise ReleaseError(f"{label}_identity_mismatch")


def _scan_release_tree(root: Path) -> tuple[set[str], set[str]]:
    files: set[str] = set()
    directories: set[str] = set()
    for current, names, filenames in os.walk(root, topdown=True, followlinks=False):
        current_path = Path(current)
        for name in names:
            path = current_path / name
            mode = path.lstat().st_mode
            if stat.S_ISLNK(mode):
                raise ReleaseError("release_tree_symlink_forbidden")
            if not stat.S_ISDIR(mode):
                raise ReleaseError("release_tree_special_file_forbidden")
            directories.add(path.relative_to(root).as_posix())
        for name in filenames:
            path = current_path / name
            mode = path.lstat().st_mode
            if stat.S_ISLNK(mode):
                raise ReleaseError("release_tree_symlink_forbidden")
            if not stat.S_ISREG(mode):
                raise ReleaseError("release_tree_special_file_forbidden")
            files.add(path.relative_to(root).as_posix())
    return files, directories


def _expected_directories(files: Iterable[str]) -> set[str]:
    directories: set[str] = set()
    for relative in files:
        parent = Path(relative).parent
        while parent != Path("."):
            directories.add(parent.as_posix())
            parent = parent.parent
    return directories


def _expected_config_bytes(
    root: Path,
    runtime_data_root: str,
) -> tuple[bytes, Mapping[str, Any]]:
    try:
        template = json.loads(
            (root / "config.example.json").read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("release_config_template_invalid") from exc
    rendered = substitute(
        template,
        {
            "${RELEASE_ROOT}": str(root),
            "${RUNTIME_DATA_ROOT}": runtime_data_root,
        },
    )
    if not isinstance(rendered, Mapping):
        raise ReleaseError("release_config_template_invalid")
    return canonical_bytes(rendered), rendered


def _verify_release_with_model_contract(
    release_dir: Path,
    required_model_contract: Mapping[str, Any],
    *,
    component_inventory_profile: str = "full",
    target_runtime_contract_required: bool = True,
    verify_live_runtime_bindings: bool = True,
) -> dict[str, Any]:
    if (
        not target_runtime_contract_required
        and (
            required_model_contract != REQUIRED_MODEL_CONTRACT
            or component_inventory_profile != "full"
        )
    ):
        raise ReleaseError("historical_target_runtime_scope_invalid")
    candidate = release_dir.expanduser().absolute()
    if candidate.is_symlink():
        raise ReleaseError("release_root_symlink_forbidden")
    root = candidate.resolve()
    if not root.is_dir():
        raise ReleaseError("release_missing")
    actual_files, actual_directories = _scan_release_tree(root)
    manifest_path = root / "release.json"
    try:
        manifest_stat = manifest_path.lstat()
    except OSError as exc:
        raise ReleaseError("release_manifest_invalid") from exc
    if not stat.S_ISREG(manifest_stat.st_mode):
        raise ReleaseError("release_manifest_invalid")
    try:
        manifest_bytes = manifest_path.read_bytes()
        if len(manifest_bytes) > 1024 * 1024:
            raise ReleaseError("release_manifest_invalid")
        manifest = json.loads(manifest_bytes)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("release_manifest_invalid") from exc
    if (
        not isinstance(manifest, dict)
        or set(manifest) != MANIFEST_KEYS
        or manifest.get("schema_version") != SCHEMA_VERSION
    ):
        raise ReleaseError("release_manifest_invalid")
    if (
        not target_runtime_contract_required
        and manifest.get("release_id")
        not in HISTORICAL_TARGET_RUNTIME_ROLLBACK_RELEASE_IDS
    ):
        raise ReleaseError("historical_target_runtime_release_not_allowlisted")
    source = manifest.get("source_files")
    modes = manifest.get("source_modes")
    source_owners = manifest.get("source_owners")
    generated = manifest.get("generated_files")
    generated_modes = manifest.get("generated_modes")
    generated_owners = manifest.get("generated_owners")
    directories = manifest.get("directories")
    manifest_metadata = manifest.get("manifest_metadata")
    service_topology = manifest.get("service_topology")
    component_inventory = manifest.get("component_inventory")
    model_contract = manifest.get("model_contract")
    test_results = manifest.get("test_results")
    release_profile = manifest.get("release_profile")
    source_release_id = manifest.get("source_release_id")
    runtime_data_root_value = manifest.get("runtime_data_root")
    base_generated = {"config.json"}
    if release_profile == "legacy_monolith":
        base_generated.add(LEGACY_RUNTIME_MANIFEST)
    allowed_generated_sets = {
        frozenset(base_generated),
        frozenset(base_generated | set(STAGING_GENERATED_SOURCE_PATHS)),
    }
    expected_generated = set(generated) if isinstance(generated, dict) else set()
    if (
        not isinstance(source, dict)
        or not isinstance(modes, dict)
        or not isinstance(source_owners, dict)
        or not isinstance(generated, dict)
        or not isinstance(generated_modes, dict)
        or not isinstance(generated_owners, dict)
        or not isinstance(directories, dict)
        or not isinstance(manifest_metadata, dict)
        or not isinstance(component_inventory, dict)
        or model_contract != required_model_contract
        or not isinstance(test_results, dict)
        or set(modes) != set(source)
        or generated_modes
        != {name: SEALED_GENERATED_MODE for name in expected_generated}
        or frozenset(generated) not in allowed_generated_sets
        or not isinstance(runtime_data_root_value, str)
        or not runtime_data_root_value
        or release_profile not in RELEASE_PROFILES
        or service_topology != list(RELEASE_PROFILES.get(str(release_profile), ()))
        or any(
            not isinstance(service.get("template"), str)
            or service.get("template") not in source
            for service in service_topology
            if isinstance(service, Mapping)
        )
        or (
            release_profile == "legacy_monolith"
            and (
                not isinstance(source_release_id, str)
                or SHA256_RE.fullmatch(source_release_id) is None
            )
        )
        or (release_profile == "concurrent_v2" and source_release_id is not None)
        or isinstance(manifest.get("formal_write_count"), bool)
        or manifest.get("formal_write_count") != 0
    ):
        raise ReleaseError("release_manifest_invalid")
    if any(
        not isinstance(relative, str) or not _source_path_allowed(relative)
        for relative in source
    ):
        raise ReleaseError("release_source_path_forbidden")
    runtime_data_root = _safe_base(
        Path(runtime_data_root_value),
        label="runtime_data_root",
    )
    if runtime_data_root_value != str(runtime_data_root):
        raise ReleaseError("release_runtime_data_root_not_canonical")
    expected_release_id = release_id_for(
        source,
        modes,
        runtime_data_root_value,
        source_owners,
        str(release_profile),
        source_release_id,
        model_contract,
        test_results,
        {
            relative: generated[relative]
            for relative in STAGING_GENERATED_SOURCE_PATHS
            if relative in generated
        },
    )
    if (
        manifest.get("release_id") != expected_release_id
        or manifest.get("source_tree_sha256") != expected_release_id
        or root.name != expected_release_id
    ):
        raise ReleaseError("release_identity_mismatch")
    expected_files = set(source) | set(generated) | {"release.json"}
    if actual_files != expected_files:
        raise ReleaseError("release_tree_file_set_mismatch")
    if actual_directories != _expected_directories(expected_files):
        raise ReleaseError("release_tree_directory_set_mismatch")
    if set(directories) != actual_directories:
        raise ReleaseError("release_directory_identity_mismatch")
    if stat.S_IMODE(root.stat().st_mode) != SEALED_DIRECTORY_MODE:
        raise ReleaseError("release_directory_mode_mismatch")
    for relative in actual_directories:
        directory_stat = (root / relative).lstat()
        expected_directory = directories.get(relative)
        if (
            not isinstance(expected_directory, Mapping)
            or expected_directory.get("type") != "directory"
            or expected_directory.get("uid") != directory_stat.st_uid
            or expected_directory.get("gid") != directory_stat.st_gid
            or expected_directory.get("mode") != SEALED_DIRECTORY_MODE
            or stat.S_IMODE(directory_stat.st_mode) != SEALED_DIRECTORY_MODE
        ):
            raise ReleaseError("release_directory_mode_mismatch")
    _verify_hashes(root, source, label="source_file")
    _verify_modes(root, modes, label="source_mode")
    _verify_owners(
        root,
        source_owners,
        expected_paths=source,
        label="source_owner",
    )
    _verify_hashes(root, generated, label="generated_file")
    _verify_modes(root, generated_modes, label="generated_mode")
    _verify_owners(
        root,
        generated_owners,
        expected_paths=generated,
        label="generated_owner",
    )
    if stat.S_IMODE(manifest_path.stat().st_mode) != SEALED_MANIFEST_MODE:
        raise ReleaseError("release_manifest_mode_mismatch")
    if (
        manifest_metadata.get("type") != "file"
        or manifest_metadata.get("uid") != manifest_stat.st_uid
        or manifest_metadata.get("gid") != manifest_stat.st_gid
        or manifest_metadata.get("mode") != SEALED_MANIFEST_MODE
    ):
        raise ReleaseError("release_manifest_metadata_mismatch")
    _verify_clean_metadata(root)
    for relative in sorted(actual_directories | actual_files):
        _verify_clean_metadata(root / relative)
    if manifest_bytes != canonical_bytes(manifest):
        raise ReleaseError("release_manifest_not_canonical")
    expected_config_bytes, config = _expected_config_bytes(
        root,
        runtime_data_root_value,
    )
    if (root / "config.json").read_bytes() != expected_config_bytes:
        raise ReleaseError("release_config_derivation_mismatch")
    release_config = config.get("release")
    expected_runtime_manifest = (
        root / LEGACY_RUNTIME_MANIFEST
        if release_profile == "legacy_monolith"
        else manifest_path
    )
    if (
        not isinstance(release_config, Mapping)
        or release_config.get("manifest_path") != str(expected_runtime_manifest)
        or config.get("runtime_root") != runtime_data_root_value
        or not isinstance(config.get("model"), Mapping)
        or not _model_contract_config_matches(config["model"], model_contract)
    ):
        raise ReleaseError("release_config_manifest_mismatch")
    if (
        target_runtime_contract_required
        and model_contract
        in (REQUIRED_MODEL_CONTRACT, LEGACY_REQUIRED_MODEL_CONTRACT)
    ):
        _validate_target_release_config(
            config,
            release_root=root,
            required_model_contract=model_contract,
        )
        if (
            model_contract == REQUIRED_MODEL_CONTRACT
            and
            verify_live_runtime_bindings
            and (root / "lib/preprocessor_core.py").is_file()
        ):
            _verify_target_external_status_script_contract(
                config, release_root=root
            )
        if (
            model_contract == REQUIRED_MODEL_CONTRACT
            and
            verify_live_runtime_bindings
            and (root / "plugin/kaoyan-study-intake/components.json").is_file()
        ):
            _verify_target_sealed_mcp_binding(root, config)
    if release_profile == "legacy_monolith":
        legacy_runtime_manifest = _bounded_manifest(expected_runtime_manifest)
        if legacy_runtime_manifest != {
            "schema_version": "study-intake-preprocessor-release-v1",
            "release_id": expected_release_id,
            "source_tree_sha256": expected_release_id,
            "runtime_data_root": runtime_data_root_value,
            "release_profile": "legacy_monolith",
            "source_release_id": source_release_id,
            "formal_write_count": 0,
        }:
            raise ReleaseError("legacy_runtime_manifest_invalid")
    expected_components = _component_inventory_for_profile(
        source,
        generated,
        service_topology,
        profile=component_inventory_profile,
    )
    if component_inventory != expected_components:
        raise ReleaseError("release_component_inventory_mismatch")
    expected_suite_names = ["core", "dashboard"]
    suites = test_results.get("suites")
    formal_gate = test_results.get("formal_surface_gate")
    if (
        set(test_results)
        != {
            "schema_version",
            "status",
            "suites",
            "formal_surface_gate",
            "real_model_call_count",
            "formal_write_count",
        }
        or
        test_results.get("schema_version")
        != "study-intake-release-test-results-v1"
        or test_results.get("status") not in {"passed", "not_run"}
        or not isinstance(suites, list)
        or [suite.get("name") for suite in suites if isinstance(suite, Mapping)]
        != expected_suite_names
        or len(suites) != len(expected_suite_names)
        or test_results.get("real_model_call_count") != 0
        or test_results.get("formal_write_count") != 0
        or not isinstance(formal_gate, Mapping)
    ):
        raise ReleaseError("release_test_results_invalid")
    for suite in suites:
        if (
            not isinstance(suite, Mapping)
            or suite.get("status") != test_results["status"]
            or (
                test_results["status"] == "passed"
                and (
                    isinstance(suite.get("test_count"), bool)
                    or not isinstance(suite.get("test_count"), int)
                    or suite["test_count"] < 1
                    or isinstance(suite.get("skipped_count"), bool)
                    or not isinstance(suite.get("skipped_count"), int)
                    or not 0 <= suite["skipped_count"] <= suite["test_count"]
                )
            )
            or (
                test_results["status"] == "not_run"
                and (
                    suite.get("test_count") is not None
                    or suite.get("skipped_count") is not None
                )
            )
        ):
            raise ReleaseError("release_test_results_invalid")
    expected_formal_keys = {
        "schema_version",
        "status",
        "verification_status",
        "baseline_file_sha256",
        "config_file_sha256",
        "baseline_manifest_sha256",
        "current_manifest_sha256",
        "differences",
    }
    if (
        set(formal_gate) != expected_formal_keys
        or formal_gate.get("schema_version") != FORMAL_GATE_SCHEMA
        or formal_gate.get("status") not in {"passed", "not_run"}
        or (
            formal_gate.get("status") == "passed"
            and (
                formal_gate.get("verification_status") != "unchanged"
                or formal_gate.get("differences") != {}
                or any(
                    not isinstance(formal_gate.get(field), str)
                    or SHA256_RE.fullmatch(str(formal_gate[field])) is None
                    for field in (
                        "baseline_file_sha256",
                        "config_file_sha256",
                        "baseline_manifest_sha256",
                        "current_manifest_sha256",
                    )
                )
                or formal_gate.get("current_manifest_sha256")
                != formal_gate.get("baseline_manifest_sha256")
            )
        )
        or (
            formal_gate.get("status") == "not_run"
            and formal_gate
            != {
                "schema_version": FORMAL_GATE_SCHEMA,
                "status": "not_run",
                "verification_status": "not_run",
                "baseline_file_sha256": None,
                "config_file_sha256": None,
                "baseline_manifest_sha256": None,
                "current_manifest_sha256": None,
                "differences": None,
            }
            )
    ):
        raise ReleaseError("release_formal_surface_gate_invalid")
    return {
        "schema_version": SCHEMA_VERSION,
        "status": "verified",
        "release_id": expected_release_id,
        "release_profile": release_profile,
        "source_release_id": source_release_id,
        "runtime_data_root": runtime_data_root_value,
        "service_topology": service_topology,
        "model_contract": model_contract,
        "test_results": test_results,
        "component_inventory": component_inventory,
        "release_dir": str(root),
        "source_file_count": len(source),
        "generated_file_count": len(generated),
        "formal_write_count": manifest["formal_write_count"],
    }


def verify_release(release_dir: Path) -> dict[str, Any]:
    manifest = _bounded_manifest(
        release_dir.expanduser().absolute() / "release.json"
    )
    observed_contract = manifest.get("model_contract")
    if observed_contract == REQUIRED_MODEL_CONTRACT:
        required = REQUIRED_MODEL_CONTRACT
    elif observed_contract == LEGACY_REQUIRED_MODEL_CONTRACT:
        required = LEGACY_REQUIRED_MODEL_CONTRACT
    else:
        raise ReleaseError("release_manifest_invalid")
    return _verify_release_with_model_contract(
        release_dir,
        required,
        component_inventory_profile="full",
    )


def verify_rollback_release(release_dir: Path) -> dict[str, Any]:
    try:
        verified = verify_release(release_dir)
    except ReleaseError as target_error:
        try:
            declared_release_id = _bounded_manifest(
                release_dir.expanduser().absolute() / "release.json"
            ).get("release_id")
        except ReleaseError:
            declared_release_id = None
        descriptors = HISTORICAL_ROLLBACK_RELEASE_CONTRACTS
        if declared_release_id in HISTORICAL_TARGET_RUNTIME_ROLLBACK_RELEASE_IDS:
            descriptors = (
                HISTORICAL_TARGET_RUNTIME_ROLLBACK_CONTRACT,
                HISTORICAL_LEGACY_TARGET_RUNTIME_ROLLBACK_CONTRACT,
                *descriptors,
            )
        for descriptor in descriptors:
            try:
                historical = _verify_release_with_model_contract(
                    release_dir,
                    descriptor["model_contract"],
                    component_inventory_profile=str(
                        descriptor["component_inventory_profile"]
                    ),
                    target_runtime_contract_required=bool(
                        descriptor.get("target_runtime_contract_required", True)
                    ),
                )
            except ReleaseError:
                continue
            return {
                **historical,
                "verification_role": "historical_reopen_or_rollback_only",
                "historical_contract": descriptor["name"],
            }
        raise target_error
    return {**verified, "verification_role": "target_or_rollback"}


def _legacy_smoke_config(release_dir: Path, isolated_runtime: Path) -> dict[str, Any]:
    template_path = release_dir / "config.example.json"
    try:
        template = json.loads(template_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("legacy_smoke_config_invalid") from exc
    rendered = substitute(
        template,
        {
            "${RELEASE_ROOT}": str(release_dir),
            "${RUNTIME_DATA_ROOT}": str(isolated_runtime),
        },
    )
    if not isinstance(rendered, dict):
        raise ReleaseError("legacy_smoke_config_invalid")
    adapters = rendered.get("adapters")
    if not isinstance(adapters, dict):
        raise ReleaseError("legacy_smoke_adapters_missing")
    for value in adapters.values():
        if isinstance(value, dict):
            value["enabled"] = False
    model = rendered.get("model")
    if isinstance(model, dict):
        # Any accidental model invocation makes the bounded smoke fail closed.
        model["codex_path"] = "/usr/bin/false"
    return rendered


def _parameterize_legacy_config(
    value: Any, *, source_release_root: str, runtime_data_root: str
) -> Any:
    if isinstance(value, dict):
        return {
            key: _parameterize_legacy_config(
                nested,
                source_release_root=source_release_root,
                runtime_data_root=runtime_data_root,
            )
            for key, nested in value.items()
        }
    if isinstance(value, list):
        return [
            _parameterize_legacy_config(
                nested,
                source_release_root=source_release_root,
                runtime_data_root=runtime_data_root,
            )
            for nested in value
        ]
    if isinstance(value, str):
        # The release path is nested beneath the runtime root.  Replace the
        # longer path first so release-bound files do not become runtime-bound.
        return value.replace(
            source_release_root, "${RELEASE_ROOT}"
        ).replace(runtime_data_root, "${RUNTIME_DATA_ROOT}")
    return value


def _prepare_legacy_snapshot(
    snapshot: Path, source_root: Path
) -> dict[str, Any]:
    """Bind the rollback template to the config the live legacy worker uses.

    The c3ff test suite contains one machine-global parity reference.  That
    mutable file can drift after c3ff was built even though launchd still runs
    c3ff's immutable ``current/config.json``.  Keep the assertion, but redirect
    only that reference to a hermetic normalization of the actual immutable
    config.  No test is skipped and no runtime program is changed.
    """

    concrete_path = source_root / "config.json"
    template_path = snapshot / "config.example.json"
    concrete = _bounded_manifest(concrete_path)
    runtime_data_root = concrete.get("runtime_root")
    if (
        not isinstance(runtime_data_root, str)
        or not runtime_data_root.startswith("/")
        or runtime_data_root in {"/", str(Path.home())}
    ):
        raise ReleaseError("legacy_current_config_runtime_root_invalid")
    rebuilt = _parameterize_legacy_config(
        concrete,
        source_release_root=str(source_root),
        runtime_data_root=runtime_data_root,
    )
    if not isinstance(rebuilt, dict):
        raise ReleaseError("legacy_current_config_invalid")
    rerendered = substitute(
        rebuilt,
        {
            "${RELEASE_ROOT}": str(source_root),
            "${RUNTIME_DATA_ROOT}": runtime_data_root,
        },
    )
    if rerendered != concrete:
        raise ReleaseError("legacy_config_template_rebuild_mismatch")
    release_binding = rebuilt.get("release")
    if not isinstance(release_binding, dict):
        raise ReleaseError("legacy_current_config_release_binding_invalid")
    # The wrapper release uses the new sealed v2 manifest.  The old monolith
    # only understands v1, so its config points at a generated v1 identity
    # capsule bound to the wrapper release ID instead of weakening the worker's
    # release check or reusing the stale c3ff ID.
    release_binding["manifest_path"] = (
        "${RELEASE_ROOT}/" + LEGACY_RUNTIME_MANIFEST
    )
    template_mode = stat.S_IMODE(
        (source_root / "config.example.json").lstat().st_mode
    ) & ~0o222
    atomic_json(template_path, rebuilt, mode=template_mode)

    parity_template = copy.deepcopy(rebuilt)
    # The c3ff parity assertion deliberately excludes the release wrapper and
    # the then-new English additions before comparing legacy semantics.  Its
    # hermetic reference must apply the same documented projection.
    parity_template.pop("release", None)
    parity_template.pop("english_single_pass_v1", None)
    adapters = parity_template.get("adapters")
    if isinstance(adapters, dict):
        adapters.pop("english", None)
    worker = parity_template.get("worker")
    if isinstance(worker, dict):
        worker.pop("english_poll_interval_seconds", None)
    parity_config = substitute(
        parity_template,
        {
            "${RELEASE_ROOT}": str(DEFAULT_RUNTIME_DATA_ROOT),
            "${RUNTIME_DATA_ROOT}": runtime_data_root,
        },
    )
    fixture = snapshot / LEGACY_PARITY_FIXTURE
    atomic_json(fixture, parity_config, mode=0o444)

    test_path = snapshot / "tests" / "test_release_manager.py"
    test_adjusted = False
    if test_path.is_file():
        try:
            test_text = test_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise ReleaseError("legacy_parity_test_unreadable") from exc
        old_reference = '''LIVE_CONFIG = Path(
    "/Users/xiazhibin/.codex/study-intake-preprocessor/config.json"
)'''
        if LEGACY_PARITY_CONFIG_ENV not in test_text:
            if old_reference not in test_text or "import json\n" not in test_text:
                raise ReleaseError("legacy_parity_test_shape_invalid")
            test_text = test_text.replace("import json\n", "import json\nimport os\n", 1)
            test_text = test_text.replace(
                old_reference,
                '''LIVE_CONFIG = Path(
    os.environ.get(
        "STUDY_PREPROCESSOR_LEGACY_PARITY_CONFIG",
        "/Users/xiazhibin/.codex/study-intake-preprocessor/config.json",
    )
)''',
                1,
            )
            source_mode = stat.S_IMODE(
                (source_root / "tests" / "test_release_manager.py").lstat().st_mode
            ) & ~0o222
            _atomic_bytes(test_path, test_text.encode("utf-8"), mode=source_mode)
            test_adjusted = True
    return {
        "schema_version": "study-intake-legacy-snapshot-proof-v1",
        "source_release_id": source_root.name,
        "source_config_sha256": sha256_file(concrete_path),
        "rebuilt_template_sha256": sha256_file(template_path),
        "parity_fixture_sha256": sha256_file(fixture),
        "parity_reference_adjusted": test_adjusted,
        "runtime_data_root": runtime_data_root,
        "formal_write_count": 0,
    }


def verify_legacy_rollback(
    *,
    release_dir: Path,
    release_base: Path,
    expected_source_release_id: str,
    timeout_seconds: float = 30.0,
) -> dict[str, Any]:
    verified = verify_rollback_release(release_dir)
    if verified.get("release_profile") != "legacy_monolith":
        raise ReleaseError("legacy_profile_required")
    if verified.get("source_release_id") != expected_source_release_id:
        raise ReleaseError("legacy_source_release_mismatch")
    root = Path(str(verified["release_dir"]))
    worker = root / "bin" / "preprocess_worker.py"
    if not worker.is_file() or worker.is_symlink():
        raise ReleaseError("legacy_worker_missing")
    if timeout_seconds <= 0 or timeout_seconds > 60:
        raise ReleaseError("legacy_smoke_timeout_invalid")
    with tempfile.TemporaryDirectory(prefix="legacy-rollback-smoke-") as raw_temp:
        isolated_root = Path(raw_temp)
        isolated_runtime = isolated_root / "runtime"
        isolated_config = isolated_root / "config.json"
        config = _legacy_smoke_config(root, isolated_runtime)
        atomic_json(isolated_config, config)
        environment = dict(os.environ)
        environment["PYTHONDONTWRITEBYTECODE"] = "1"
        environment.pop("STUDY_PREPROCESSOR_RUN_REAL_RUNTIME_TESTS", None)
        commands = (
            [sys.executable, str(worker), "--help"],
            [
                sys.executable,
                str(worker),
                "--config",
                str(isolated_config),
                "run-once",
            ],
        )
        command_receipts: list[dict[str, Any]] = []
        for command in commands:
            try:
                completed = subprocess.run(
                    command,
                    cwd=root,
                    env=environment,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True,
                    check=False,
                    timeout=timeout_seconds,
                )
            except subprocess.TimeoutExpired as exc:
                raise ReleaseError("legacy_smoke_timeout") from exc
            if completed.returncode != 0:
                raise ReleaseError("legacy_smoke_failed")
            command_receipts.append(
                {
                    "argv_role": "help" if "--help" in command else "disabled_run_once",
                    "returncode": completed.returncode,
                    "stdout_sha256": sha256_bytes(completed.stdout.encode("utf-8")),
                    "stderr_sha256": sha256_bytes(completed.stderr.encode("utf-8")),
                }
            )
        if not isolated_runtime.exists():
            raise ReleaseError("legacy_smoke_runtime_not_created")
    receipt = {
        "schema_version": "study-intake-legacy-rollback-verification-v1",
        "status": "verified",
        "release_id": verified["release_id"],
        "release_profile": "legacy_monolith",
        "source_release_id": expected_source_release_id,
        "service_topology": verified["service_topology"],
        "source_file_count": verified["source_file_count"],
        "generated_file_count": verified["generated_file_count"],
        "pycache_file_count": 0,
        "all_adapters_disabled": True,
        "model_executable": "/usr/bin/false",
        "commands": command_receipts,
        "verified_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "model_call_count": 0,
        "formal_write_count": 0,
    }
    receipt_id = sha256_bytes(canonical_bytes(receipt))
    atomic_json(
        _safe_base(release_base, label="release_base")
        / "rollback-verifications"
        / f"{receipt_id}.json",
        receipt,
    )
    return {**receipt, "verification_receipt_sha256": receipt_id}


def build_legacy_rollback(
    *,
    current_link: Path,
    expected_current: str,
    release_base: Path,
    runtime_data_root: Path,
    skip_tests: bool,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    formal_config: Path | None = None,
    formal_baseline: Path | None = None,
    historical_test_input_manifest: Path | None = None,
) -> dict[str, Any]:
    if SHA256_RE.fullmatch(expected_current) is None:
        raise ReleaseError("expected_current_invalid")
    observed_id, observed_path = _current_release(current_link.expanduser().absolute())
    if observed_id != expected_current or observed_path is None:
        raise ReleaseError("expected_current_mismatch")
    source_root = Path(observed_path)
    source_manifest = _bounded_manifest(source_root / "release.json")
    if source_manifest.get("release_id") != expected_current:
        raise ReleaseError("legacy_source_manifest_mismatch")
    source_contract = source_manifest.get("model_contract")
    inventory_profile = "full"
    if source_contract == REQUIRED_MODEL_CONTRACT:
        rollback_model_contract = dict(REQUIRED_MODEL_CONTRACT)
    else:
        historical = (
            _historical_release_contract(source_contract)
            if isinstance(source_contract, Mapping)
            else None
        )
        if historical is None:
            source_config = _bounded_manifest(source_root / "config.json")
            source_model = source_config.get("model")
            if not isinstance(source_model, Mapping):
                raise ReleaseError("legacy_source_model_contract_invalid")
            historical = next(
                (
                    descriptor
                    for descriptor in HISTORICAL_ROLLBACK_RELEASE_CONTRACTS
                    if _model_contract_config_matches(
                        source_model, descriptor["model_contract"]
                    )
                ),
                None,
            )
        if historical is None:
            raise ReleaseError("legacy_source_model_contract_invalid")
        rollback_model_contract = dict(historical["model_contract"])
        inventory_profile = str(historical["component_inventory_profile"])
    launchagent_dir = launchagent_dir.expanduser().absolute()
    with tempfile.TemporaryDirectory(prefix="legacy-rollback-source-") as raw_snapshot:
        snapshot = Path(raw_snapshot)
        hashes = source_hashes(source_root)
        modes = source_modes(source_root)
        for relative in hashes:
            target = snapshot / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source_root / relative, target)
            # Tests execute in this temporary source snapshot before the new
            # release is sealed.  Preserve c3ff's actual source mode here so
            # fixtures that intentionally overwrite a copied file remain
            # usable; build_release independently strips all write bits when
            # it records and publishes the immutable rollback tree.
            target.chmod(
                stat.S_IMODE((source_root / relative).lstat().st_mode)
            )
        snapshot_proof = _prepare_legacy_snapshot(snapshot, source_root)
        for service in LEGACY_MONOLITH_TOPOLOGY:
            label = str(service["label"])
            source_plist = launchagent_dir / f"{label}.plist"
            if source_plist.is_symlink() or not source_plist.is_file():
                raise ReleaseError(f"legacy_launchagent_missing:{label}")
            raw_plist = source_plist.read_bytes()
            try:
                payload = plistlib.loads(raw_plist)
            except Exception as exc:
                raise ReleaseError(f"legacy_launchagent_invalid:{label}") from exc
            if not isinstance(payload, dict) or payload.get("Label") != label:
                raise ReleaseError(f"legacy_launchagent_label_mismatch:{label}")
            target = snapshot / str(service["template"])
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(raw_plist)
            target.chmod(0o644)
        snapshot_proof["installed_launchagent_sha256"] = {
            str(service["label"]): sha256_file(
                snapshot / str(service["template"])
            )
            for service in LEGACY_MONOLITH_TOPOLOGY
        }
        built = build_release(
            source_root=snapshot,
            release_base=release_base,
            runtime_data_root=runtime_data_root,
            skip_tests=skip_tests,
            release_profile="legacy_monolith",
            source_release_id=expected_current,
            formal_config=formal_config,
            formal_baseline=formal_baseline,
            historical_test_input_manifest=historical_test_input_manifest,
            model_contract=rollback_model_contract,
            component_inventory_profile=inventory_profile,
        )
    after_id, _ = _current_release(current_link.expanduser().absolute())
    if after_id != expected_current:
        raise ReleaseError("expected_current_changed_during_legacy_build")
    verification = verify_legacy_rollback(
        release_dir=Path(str(built["release_dir"])),
        release_base=release_base,
        expected_source_release_id=expected_current,
    )
    return {
        **built,
        "legacy_snapshot_proof": snapshot_proof,
        "rollback_verification": verification,
    }


def _bounded_manifest(path: Path) -> dict[str, Any]:
    try:
        if path.lstat().st_size > 1024 * 1024 or path.is_symlink():
            raise ReleaseError("release_manifest_invalid")
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("release_manifest_invalid") from exc
    if not isinstance(value, dict):
        raise ReleaseError("release_manifest_invalid")
    return value


def _subprocess_command_runner(command: Sequence[str]) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        list(command),
        stdin=subprocess.DEVNULL,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )


def _service_commands(
    services: Iterable[Mapping[str, Any]],
    launchagent_dir: Path,
    uid: int | None = None,
) -> list[dict[str, Any]]:
    resolved_uid = os.getuid() if uid is None else uid
    return [
        {
            **service,
            "plist_path": str(launchagent_dir / f"{service['label']}.plist"),
            "disable": [
                "launchctl",
                "disable",
                f"gui/{resolved_uid}/{service['label']}",
            ],
            "bootout": [
                "launchctl",
                "bootout",
                f"gui/{resolved_uid}",
                str(launchagent_dir / f"{service['label']}.plist"),
            ],
            "enable": [
                "launchctl",
                "enable",
                f"gui/{resolved_uid}/{service['label']}",
            ],
            "bootstrap": [
                "launchctl",
                "bootstrap",
                f"gui/{resolved_uid}",
                str(launchagent_dir / f"{service['label']}.plist"),
            ],
            "verify": [
                "launchctl",
                "print",
                f"gui/{resolved_uid}/{service['label']}",
            ],
            "disabled_status": [
                "launchctl",
                "print-disabled",
                f"gui/{resolved_uid}",
            ],
        }
        for service in services
    ]


def _command_returncode(result: Any) -> int:
    if isinstance(result, Mapping):
        value = result.get("returncode")
    else:
        value = getattr(result, "returncode", None)
    return value if isinstance(value, int) and not isinstance(value, bool) else 1


def _command_stdout(result: Any) -> str:
    value = result.get("stdout") if isinstance(result, Mapping) else getattr(result, "stdout", "")
    return value if isinstance(value, str) else ""


def _run_service_bootout_idempotent(
    service: Mapping[str, Any],
    runner: CommandRunner,
) -> bool:
    """Boot out one service, accepting only a verified already-absent target."""

    command = service.get("bootout")
    if not isinstance(command, list):
        return False
    result = runner(command)
    if _command_returncode(result) == 0:
        return True

    verify = service.get("verify")
    if not isinstance(verify, list):
        return False
    verification = runner(verify)
    return (
        _command_returncode(verification)
        == LAUNCHCTL_SERVICE_NOT_FOUND_RETURN_CODE
    )


def _run_service_transition(
    previous_topology: Iterable[Mapping[str, Any]],
    target_topology: Iterable[Mapping[str, Any]],
    runner: CommandRunner,
) -> None:
    _run_service_deactivation(
        previous_topology, runner, paused_services=PAUSED_CONCURRENT_SERVICES
    )
    _run_service_activation(
        target_topology, runner, paused_services=PAUSED_CONCURRENT_SERVICES
    )


def _run_service_deactivation(
    topology: Iterable[Mapping[str, Any]],
    runner: CommandRunner,
    *,
    paused_services: frozenset[str] = frozenset(),
) -> None:
    for service in topology:
        for phase in ("disable", "bootout"):
            command = service.get(phase)
            if phase == "bootout":
                succeeded = _run_service_bootout_idempotent(service, runner)
            else:
                result = runner(command) if isinstance(command, list) else None
                succeeded = (
                    isinstance(command, list)
                    and _command_returncode(result) == 0
                )
            if (
                not succeeded
                and not (
                    phase == "bootout"
                    and service.get("name") in paused_services
                )
            ):
                raise ReleaseError(f"service_{phase}_failed:{service.get('name')}")


def _run_service_activation(
    topology: Iterable[Mapping[str, Any]],
    runner: CommandRunner,
    *,
    paused_services: frozenset[str] = frozenset(),
) -> None:
    for service in topology:
        if service.get("name") in paused_services:
            for phase in ("disable", "bootout"):
                command = service.get(phase)
                result = runner(command) if isinstance(command, list) else None
                if (
                    not isinstance(command, list)
                    or (
                        phase == "disable"
                        and _command_returncode(result) != 0
                    )
                ):
                    raise ReleaseError(
                        f"service_{phase}_failed:{service.get('name')}"
                    )
            continue
        for phase in ("enable", "bootstrap", "verify"):
            command = service.get(phase)
            if not isinstance(command, list) or _command_returncode(runner(command)) != 0:
                raise ReleaseError(f"service_{phase}_failed:{service.get('name')}")


def _run_service_deactivation_best_effort(
    topology: Iterable[Mapping[str, Any]],
    runner: CommandRunner,
    *,
    paused_services: frozenset[str] = frozenset(),
) -> list[str]:
    errors: list[str] = []
    for service in topology:
        for phase in ("disable", "bootout"):
            command = service.get(phase)
            if phase == "bootout":
                succeeded = _run_service_bootout_idempotent(service, runner)
            else:
                result = runner(command) if isinstance(command, list) else None
                succeeded = (
                    isinstance(command, list)
                    and _command_returncode(result) == 0
                )
            if (
                not succeeded
                and not (
                    phase == "bootout"
                    and service.get("name") in paused_services
                )
            ):
                errors.append(f"service_{phase}_failed:{service.get('name')}")
    return errors


def _run_service_phase(
    topology: Iterable[Mapping[str, Any]],
    phase: str,
    runner: CommandRunner,
    *,
    paused_services: frozenset[str] = frozenset(),
) -> None:
    if phase not in {"disable", "bootout"}:
        raise ReleaseError("service_phase_invalid")
    for service in topology:
        command = service.get(phase)
        if phase == "bootout":
            succeeded = _run_service_bootout_idempotent(service, runner)
        else:
            result = runner(command) if isinstance(command, list) else None
            succeeded = (
                isinstance(command, list)
                and _command_returncode(result) == 0
            )
        if (
            not succeeded
            and not (
                phase == "bootout"
                and service.get("name") in paused_services
            )
        ):
            raise ReleaseError(f"service_{phase}_failed:{service.get('name')}")


def _safe_launchagent_dir(path: Path, *, create: bool) -> Path:
    candidate = path.expanduser().absolute()
    if candidate in {Path("/"), Path.home()} or candidate.is_symlink():
        raise ReleaseError("launchagent_dir_invalid")
    if create:
        candidate.mkdir(parents=True, exist_ok=True, mode=0o700)
    elif candidate.exists() and not candidate.is_dir():
        raise ReleaseError("launchagent_dir_invalid")
    return candidate.resolve(strict=False)


def _render_launchagent_plists(
    release_root: Path,
    topology: Iterable[Mapping[str, Any]],
    active_link: Path,
    runtime_data_root: Path,
) -> dict[str, bytes]:
    rendered: dict[str, bytes] = {}
    for service in topology:
        label = service.get("label")
        template = service.get("template")
        if not isinstance(label, str) or not isinstance(template, str):
            raise ReleaseError("release_service_template_invalid")
        path = release_root / _safe_relative_file(template, label="service_template")
        if path.is_symlink() or not path.is_file() or path.stat().st_size > 256 * 1024:
            raise ReleaseError(f"release_service_template_missing:{label}")
        try:
            payload = plistlib.loads(path.read_bytes())
        except Exception as exc:
            raise ReleaseError(f"release_service_template_invalid:{label}") from exc
        payload = substitute(
            payload,
            {
                "${CURRENT_ROOT}": str(active_link),
                "${RELEASE_ROOT}": str(active_link),
                "${RUNTIME_DATA_ROOT}": str(runtime_data_root),
            },
        )
        if not isinstance(payload, dict) or payload.get("Label") != label:
            raise ReleaseError(f"release_service_template_label_mismatch:{label}")
        raw_rendered = plistlib.dumps(payload, fmt=plistlib.FMT_XML, sort_keys=True)
        if b"${" in raw_rendered:
            raise ReleaseError(f"release_service_template_placeholder_unresolved:{label}")
        rendered[label] = raw_rendered
    return rendered


def _atomic_bytes(path: Path, value: bytes, *, mode: int = 0o644) -> None:
    descriptor, raw_temp = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temp = Path(raw_temp)
    try:
        os.fchmod(descriptor, mode)
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(value)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp, path)
        _fsync_directory(path.parent)
    finally:
        try:
            temp.unlink()
        except FileNotFoundError:
            pass


def _snapshot_optional_file_bytes(path: Path) -> dict[str, Any]:
    """Capture exact rollback bytes without creating the optional file."""

    candidate = path.expanduser().absolute()
    try:
        node = candidate.lstat()
    except FileNotFoundError:
        return {
            "path": str(candidate),
            "existed": False,
            "value": None,
            "mode": None,
            "sha256": None,
        }
    if not stat.S_ISREG(node.st_mode) or candidate.is_symlink():
        raise ReleaseError("dashboard_projection_snapshot_invalid")
    value = candidate.read_bytes()
    return {
        "path": str(candidate),
        "existed": True,
        "value": value,
        "mode": stat.S_IMODE(node.st_mode),
        "sha256": sha256_bytes(value),
    }


def _previous_canary_continuity_activated_at(
    snapshots: Mapping[str, Mapping[str, Any]],
    *,
    previous_release_id: str,
) -> dt.datetime | None:
    """Carry the authenticated discovery floor across an immutable upgrade.

    A Capture's study_date is learning provenance.  Captures appended after
    the active canary began must not become historical merely because a new
    immutable release is deployed before they are discovered.  The stopped
    predecessor gates are byte-locked and independently validated by
    _deactivate_previous_canary_states before this value is used.
    """

    if set(snapshots) != set(RESUMABLE_SUBJECTS):
        raise ReleaseError("previous_canary_continuity_invalid")
    gates: list[Mapping[str, Any]] = []
    incompatible_count = 0
    for subject in RESUMABLE_SUBJECTS:
        snapshot = snapshots.get(subject)
        if not isinstance(snapshot, Mapping):
            raise ReleaseError("previous_canary_continuity_invalid")
        if snapshot.get("existed") is False:
            return None
        raw = snapshot.get("value")
        try:
            gate = json.loads(raw) if isinstance(raw, bytes) else None
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise ReleaseError("previous_canary_continuity_invalid") from exc
        state = gate.get("state") if isinstance(gate, Mapping) else None
        expected_consumer_enabled = (
            True
            if state in {"armed", "continuous_concurrent_unlocked"}
            else False
            if state in {"failed_drained", "paused_drained"}
            else None
        )
        compatible = (
            isinstance(gate, Mapping)
            and gate.get("subject") == subject
            and gate.get("release_id") == previous_release_id
            and gate.get("status") == "production_canary_active"
            and expected_consumer_enabled is not None
            and gate.get("post_activation_only") is True
            and gate.get("producer_capture_enabled") is True
            and gate.get("luna_consumer_enabled")
            is expected_consumer_enabled
            and gate.get("active_task_count") == 0
            and gate.get("formal_write_count") == 0
            and gate.get("sol_enabled") is False
        )
        if compatible:
            gates.append(gate)
        else:
            incompatible_count += 1
    # Recovery fixtures and older inactive deployments have no discovery
    # floor to carry.  A partial match is unsafe because it would combine
    # different subject epochs; all three must authenticate the same floor.
    if incompatible_count == len(RESUMABLE_SUBJECTS):
        return None
    if incompatible_count:
        raise ReleaseError("previous_canary_continuity_invalid")
    values = {str(gate.get("activated_at") or "") for gate in gates}
    if len(values) != 1:
        raise ReleaseError("previous_canary_continuity_invalid")
    try:
        activated_at = dt.datetime.fromisoformat(
            next(iter(values)).replace("Z", "+00:00")
        )
    except ValueError as exc:
        raise ReleaseError("previous_canary_continuity_invalid") from exc
    if activated_at.tzinfo is None:
        raise ReleaseError("previous_canary_continuity_invalid")
    return activated_at.astimezone(dt.timezone.utc)


def _restore_optional_file_bytes(snapshot: Mapping[str, Any]) -> dict[str, Any]:
    """Atomically restore exact bytes, or restore the original absence."""

    path = Path(str(snapshot.get("path") or "")).expanduser().absolute()
    existed = snapshot.get("existed")
    expected_sha256 = snapshot.get("sha256")
    if existed is True:
        value = snapshot.get("value")
        mode = snapshot.get("mode")
        if (
            not isinstance(value, bytes)
            or not isinstance(mode, int)
            or isinstance(mode, bool)
            or SHA256_RE.fullmatch(str(expected_sha256 or "")) is None
            or sha256_bytes(value) != expected_sha256
        ):
            raise ReleaseError("dashboard_projection_snapshot_invalid")
        path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_bytes(path, value, mode=mode)
        if path.is_symlink() or not path.is_file() or sha256_file(path) != expected_sha256:
            raise ReleaseError("dashboard_projection_restore_mismatch")
        restored_state = "present"
        restored_sha256 = str(expected_sha256)
    elif existed is False:
        if path.exists() or path.is_symlink():
            if path.is_symlink() or not path.is_file():
                raise ReleaseError("dashboard_projection_restore_target_invalid")
            path.unlink()
            _fsync_directory(path.parent)
        if path.exists() or path.is_symlink():
            raise ReleaseError("dashboard_projection_restore_mismatch")
        restored_state = "absent"
        restored_sha256 = None
    else:
        raise ReleaseError("dashboard_projection_snapshot_invalid")
    proof = {
        "path": str(path),
        "snapshot_state": "present" if existed is True else "absent",
        "snapshot_sha256": expected_sha256,
        "restored_state": restored_state,
        "restored_sha256": restored_sha256,
    }
    return {
        **proof,
        "proof_sha256": sha256_bytes(canonical_bytes(proof)),
    }


def _backup_launchagent_plists(
    launchagent_dir: Path,
    topology: Iterable[Mapping[str, Any]],
    backup_root: Path,
) -> dict[str, dict[str, Any]]:
    backup_root.mkdir(parents=True, exist_ok=False, mode=0o700)
    records: dict[str, dict[str, Any]] = {}
    labels = sorted({str(service["label"]) for service in topology})
    for label in labels:
        source = launchagent_dir / f"{label}.plist"
        record: dict[str, Any] = {"existed": False, "live_path": str(source)}
        if source.exists() or source.is_symlink():
            if source.is_symlink() or not source.is_file() or source.stat().st_size > 256 * 1024:
                raise ReleaseError(f"installed_launchagent_invalid:{label}")
            value = source.read_bytes()
            try:
                payload = plistlib.loads(value)
            except Exception as exc:
                raise ReleaseError(f"installed_launchagent_invalid:{label}") from exc
            if not isinstance(payload, dict) or payload.get("Label") != label:
                raise ReleaseError(f"installed_launchagent_label_mismatch:{label}")
            backup = backup_root / f"{label}.plist"
            _atomic_bytes(backup, value, mode=0o600)
            record.update(
                {
                    "existed": True,
                    "backup_path": str(backup),
                    "sha256": sha256_bytes(value),
                }
            )
        records[label] = record
    atomic_json(backup_root / "inventory.json", records, mode=0o600)
    return records


def _install_launchagent_plists(
    launchagent_dir: Path,
    rendered: Mapping[str, bytes],
) -> None:
    for label in sorted(rendered):
        _atomic_bytes(launchagent_dir / f"{label}.plist", rendered[label])


def _restore_launchagent_plists(records: Mapping[str, Mapping[str, Any]]) -> None:
    for label in sorted(records):
        record = records[label]
        live = Path(str(record.get("live_path")))
        if record.get("existed") is True:
            backup = Path(str(record.get("backup_path")))
            value = backup.read_bytes()
            if sha256_bytes(value) != record.get("sha256"):
                raise ReleaseError(f"launchagent_backup_hash_mismatch:{label}")
            _atomic_bytes(live, value)
        elif live.exists() or live.is_symlink():
            if live.is_symlink() or not live.is_file():
                raise ReleaseError(f"installed_launchagent_invalid:{label}")
            live.unlink()
            _fsync_directory(live.parent)


def _external_profile_target_enabled(target: Path) -> bool:
    """Return whether this release owns the sealed plugin/profile surfaces."""

    plugin_root = target / "plugin" / "kaoyan-study-intake"
    return all(
        path.is_file() and not path.is_symlink()
        for path in (
            plugin_root / "components.json",
            plugin_root / "component-lock.json",
            plugin_root / "bin" / "kaoyan-read",
        )
    )


def _ordinary_mcp_profile_span(value: bytes) -> tuple[int, int, bytes]:
    """Locate one exact ordinary MCP TOML table without parsing/reformatting peers."""

    invalid = "ordinary_mcp_profile_invalid"
    try:
        text = value.decode("utf-8")
    except UnicodeError as exc:
        raise ReleaseError(invalid) from exc
    lines = text.splitlines(keepends=True)
    matches = [
        index
        for index, line in enumerate(lines)
        if line.strip() == "[mcp_servers.kaoyan_read]"
    ]
    if len(matches) != 1:
        raise ReleaseError(invalid)
    start_line = matches[0]
    end_line = len(lines)
    for index in range(start_line + 1, len(lines)):
        stripped = lines[index].lstrip()
        header = re.match(
            r"^\[\[?([^\]\r\n]+)\]\]?\s*(?:#.*)?(?:\r?\n)?$",
            stripped,
        )
        if header is not None:
            table_name = header.group(1).strip()
            if not table_name.startswith("mcp_servers.kaoyan_read."):
                end_line = index
                break
    start = len("".join(lines[:start_line]).encode("utf-8"))
    end = len("".join(lines[:end_line]).encode("utf-8"))
    block = value[start:end]
    try:
        parsed = tomllib.loads(block.decode("utf-8"))
        profile = parsed["mcp_servers"]["kaoyan_read"]
    except (KeyError, TypeError, tomllib.TOMLDecodeError, UnicodeError) as exc:
        raise ReleaseError(invalid) from exc
    if not isinstance(profile, Mapping):
        raise ReleaseError(invalid)
    return start, end, block


def _render_ordinary_mcp_profile(runtime: Mapping[str, Any]) -> bytes:
    """Render the ordinary profile from the content-addressed MCP template."""

    invalid = "ordinary_mcp_profile_target_invalid"
    if runtime.get("python_flags") != ["-I", "-S"]:
        raise ReleaseError(invalid)
    release_root = Path(str(runtime.get("release_root") or ""))
    template_path = release_root / "config" / "codex-mcp-snippet.toml"
    try:
        template = template_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ReleaseError(invalid) from exc
    marker = "[mcp_servers.kaoyan_read]"
    if template.count(marker) != 1:
        raise ReleaseError(invalid)
    template = template[template.index(marker):]
    substitutions = {
        "__MCP_PYTHON_EXECUTABLE__": runtime.get("python_executable"),
        "__MCP_SEALED_LAUNCHER_PATH__": runtime.get("sealed_launcher_path"),
        "__MCP_RELEASE_ROOT__": runtime.get("release_root"),
        "__MCP_RELEASE_ID__": runtime.get("release_id"),
        "__MCP_RELEASE_MANIFEST_SHA256__": runtime.get(
            "release_manifest_sha256"
        ),
    }
    for token, replacement in substitutions.items():
        if (
            template.count(token) < 1
            or not isinstance(replacement, str)
            or not replacement
            or any(character in replacement for character in ('"', "\r", "\n"))
        ):
            raise ReleaseError(invalid)
        template = template.replace(token, replacement)
    if "__MCP_" in template:
        raise ReleaseError(invalid)
    if not template.endswith("\n"):
        template += "\n"
    try:
        parsed = tomllib.loads(template)
        profile = parsed["mcp_servers"]["kaoyan_read"]
    except (KeyError, TypeError, tomllib.TOMLDecodeError) as exc:
        raise ReleaseError(invalid) from exc
    expected_args = [
        "-I",
        "-S",
        str(runtime["sealed_launcher_path"]),
        "--release-root",
        str(runtime["release_root"]),
        "--expected-release-id",
        str(runtime["release_id"]),
        "--expected-release-manifest-sha256",
        str(runtime["release_manifest_sha256"]),
        "--mode",
        "server",
        "--profile",
        "ordinary",
        "--subjects",
        "math,cs408,english",
    ]
    if (
        profile.get("command") != runtime.get("python_executable")
        or profile.get("args") != expected_args
        or profile.get("cwd") != runtime.get("release_root")
        or profile.get("env") != {}
        or profile.get("env_vars") != []
        or profile.get("enabled") is not True
    ):
        raise ReleaseError(invalid)
    return template.encode("utf-8")


def _replace_ordinary_mcp_profile(config: bytes, profile: bytes) -> bytes:
    start, end, _old = _ordinary_mcp_profile_span(config)
    candidate = config[:start] + profile + config[end:]
    try:
        parsed = tomllib.loads(candidate.decode("utf-8"))
    except (UnicodeError, tomllib.TOMLDecodeError) as exc:
        raise ReleaseError("ordinary_profile_target_invalid") from exc
    if not isinstance(parsed.get("mcp_servers", {}).get("kaoyan_read"), Mapping):
        raise ReleaseError("ordinary_profile_target_invalid")
    return candidate


def _directory_inventory(
    root: Path,
    *,
    error_code: str,
    maximum_files: int = 4096,
    maximum_bytes: int = 64 * 1024 * 1024,
) -> dict[str, Any]:
    candidate = root.expanduser().absolute()
    try:
        node = candidate.lstat()
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if candidate.is_symlink() or not stat.S_ISDIR(node.st_mode):
        raise ReleaseError(error_code)
    files: dict[str, dict[str, Any]] = {}
    directories: dict[str, int] = {".": stat.S_IMODE(node.st_mode)}
    total_bytes = 0
    for path in sorted(candidate.rglob("*"), key=lambda item: item.as_posix()):
        try:
            child = path.lstat()
        except OSError as exc:
            raise ReleaseError(error_code) from exc
        relative = path.relative_to(candidate).as_posix()
        if path.is_symlink():
            raise ReleaseError(error_code)
        if stat.S_ISDIR(child.st_mode):
            directories[relative] = stat.S_IMODE(child.st_mode)
            continue
        if not stat.S_ISREG(child.st_mode):
            raise ReleaseError(error_code)
        total_bytes += child.st_size
        if len(files) >= maximum_files or total_bytes > maximum_bytes:
            raise ReleaseError(error_code)
        files[relative] = {
            "sha256": sha256_file(path),
            "size": child.st_size,
            "mode": stat.S_IMODE(child.st_mode),
        }
    payload = {
        "file_count": len(files),
        "total_bytes": total_bytes,
        "files": files,
        "directories": directories,
    }
    return {
        **payload,
        "tree_sha256": sha256_bytes(canonical_bytes(payload)),
    }


def _optional_directory_preimage(
    root: Path, *, error_code: str
) -> dict[str, Any]:
    """Describe an exact directory preimage, including legitimate absence."""

    candidate = root.expanduser().absolute()
    if candidate in {Path("/"), Path.home()} or candidate.parent in {
        Path("/"),
        Path.home(),
    }:
        raise ReleaseError(error_code)
    if candidate.exists() or candidate.is_symlink():
        inventory = _directory_inventory(candidate, error_code=error_code)
        return {"state": "present", **inventory}
    parent = candidate.parent
    try:
        parent_stat = parent.lstat()
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if (
        parent.is_symlink()
        or not stat.S_ISDIR(parent_stat.st_mode)
        or not os.access(parent, os.W_OK | os.X_OK)
    ):
        raise ReleaseError(error_code)
    return {
        "state": "absent",
        "tree_sha256": None,
        "file_count": 0,
        "total_bytes": 0,
        "files": {},
        "directories": {},
    }


def _copy_verified_directory(source: Path, destination: Path) -> dict[str, Any]:
    expected = _directory_inventory(source, error_code="external_profile_tree_invalid")
    if destination.exists() or destination.is_symlink():
        raise ReleaseError("external_profile_copy_destination_exists")
    try:
        shutil.copytree(source, destination, symlinks=False, copy_function=shutil.copy2)
    except OSError as exc:
        raise ReleaseError("external_profile_copy_failed") from exc
    actual = _directory_inventory(destination, error_code="external_profile_tree_invalid")
    if actual != expected:
        raise ReleaseError("external_profile_copy_mismatch")
    return actual


def _make_directory_entry_replaceable(path: Path) -> int:
    """Temporarily make one directory entry movable on Darwin.

    Darwin rejects a rename that moves a read-only directory entry between
    different parents, even when both parents are owner-writable.  External
    profile payloads are intentionally sealed with a read-only root mode, so
    preserve that exact mode while granting only temporary owner write access
    for the directory-entry move.
    """

    try:
        node = path.lstat()
    except OSError as exc:
        raise ReleaseError("external_profile_replace_source_invalid") from exc
    if path.is_symlink() or not stat.S_ISDIR(node.st_mode):
        raise ReleaseError("external_profile_replace_source_invalid")
    original_mode = stat.S_IMODE(node.st_mode)
    replaceable_mode = original_mode | stat.S_IWUSR
    if replaceable_mode != original_mode:
        try:
            path.chmod(replaceable_mode)
        except OSError as exc:
            raise ReleaseError("external_profile_replace_mode_failed") from exc
    return original_mode


def _restore_directory_entry_mode(path: Path, mode: int) -> None:
    try:
        node = path.lstat()
        if path.is_symlink() or not stat.S_ISDIR(node.st_mode):
            raise ReleaseError("external_profile_replace_target_invalid")
        path.chmod(mode)
        if stat.S_IMODE(path.lstat().st_mode) != mode:
            raise ReleaseError("external_profile_replace_mode_restore_failed")
    except ReleaseError:
        raise
    except OSError as exc:
        raise ReleaseError("external_profile_replace_mode_restore_failed") from exc


def _atomic_replace_directory(
    live: Path,
    source: Path,
    *,
    token: str,
) -> dict[str, Any]:
    live = live.expanduser().absolute()
    if live in {Path("/"), Path.home()} or live.parent in {Path("/"), Path.home()}:
        raise ReleaseError("external_profile_path_broad")
    live.parent.mkdir(parents=True, exist_ok=True)
    stage_root = Path(
        tempfile.mkdtemp(prefix=f".{live.name}.{token}.stage-", dir=live.parent)
    )
    stage = stage_root / live.name
    rollover = live.parent / f".{live.name}.{token}.rollback"
    if rollover.exists() or rollover.is_symlink():
        raise ReleaseError("external_profile_rollover_exists")
    moved_live = False
    installed = False
    expected: dict[str, Any] | None = None
    moved_live_mode: int | None = None
    try:
        expected = _copy_verified_directory(source, stage)
        if live.exists() or live.is_symlink():
            _directory_inventory(live, error_code="external_profile_tree_invalid")
            moved_live_mode = _make_directory_entry_replaceable(live)
            try:
                os.replace(live, rollover)
                moved_live = True
            finally:
                moved_path = rollover if moved_live else live
                if moved_path.exists() or moved_path.is_symlink():
                    _restore_directory_entry_mode(moved_path, moved_live_mode)
            _fsync_directory(live.parent)
        stage_mode = _make_directory_entry_replaceable(stage)
        try:
            os.replace(stage, live)
            installed = True
        finally:
            installed_path = live if installed else stage
            if installed_path.exists() or installed_path.is_symlink():
                _restore_directory_entry_mode(installed_path, stage_mode)
        _fsync_directory(live.parent)
        actual = _directory_inventory(live, error_code="external_profile_tree_invalid")
        if actual != expected:
            raise ReleaseError("external_profile_install_mismatch")
        if moved_live:
            _make_tree_removable(rollover)
            shutil.rmtree(rollover)
            _fsync_directory(live.parent)
        return actual
    except Exception:
        if installed and (live.exists() or live.is_symlink()):
            if live.is_symlink() or not live.is_dir():
                raise ReleaseError("external_profile_install_rollback_invalid")
            _make_tree_removable(live)
            shutil.rmtree(live)
        if moved_live and rollover.exists() and not live.exists():
            rollback_mode = _make_directory_entry_replaceable(rollover)
            rollback_moved = False
            try:
                os.replace(rollover, live)
                rollback_moved = True
            finally:
                rollback_path = live if rollback_moved else rollover
                if rollback_path.exists() or rollback_path.is_symlink():
                    _restore_directory_entry_mode(
                        rollback_path,
                        moved_live_mode
                        if moved_live_mode is not None
                        else rollback_mode,
                    )
            _fsync_directory(live.parent)
        raise
    finally:
        if stage_root.exists():
            _make_tree_removable(stage_root)
            shutil.rmtree(stage_root)


def _sealed_runtime_from_target(target: Path) -> tuple[dict[str, Any], dict[str, Any]]:
    plugin_root = target / "plugin" / "kaoyan-study-intake"
    invalid = "external_profile_target_invalid"
    try:
        components = json.loads(
            (plugin_root / "components.json").read_text(encoding="utf-8")
        )
        lock = json.loads(
            (plugin_root / "component-lock.json").read_text(encoding="utf-8")
        )
        mcp = components["mcp"]
        runtime = lock["mcp_sealed_runtime"]
    except (OSError, UnicodeError, json.JSONDecodeError, KeyError, TypeError) as exc:
        raise ReleaseError(invalid) from exc
    if not isinstance(mcp, Mapping) or not isinstance(runtime, Mapping):
        raise ReleaseError(invalid)
    expected = {
        "python_executable": mcp.get("python_executable"),
        "python_flags": mcp.get("python_flags"),
        "sealed_launcher_path": mcp.get("sealed_launcher_path"),
        "sealed_launcher_sha256": mcp.get("sealed_launcher_sha256"),
        "release_root": mcp.get("release_root"),
        "release_id": mcp.get("release_id"),
        "release_manifest_sha256": mcp.get("release_manifest_sha256"),
    }
    if dict(runtime) != expected or set(runtime) != set(expected):
        raise ReleaseError(invalid)
    return dict(runtime), dict(mcp)


def _morning_pointer_bytes(
    runtime: Mapping[str, Any], mcp: Mapping[str, Any]
) -> bytes:
    value = {
        "plugin_version": str(mcp.get("minimum_server_release") or ""),
        "python": runtime["python_executable"],
        "release_id": runtime["release_id"],
        "release_root": runtime["release_root"],
        "schema": "study_read_mcp_morning_preparation_pointer_v1",
        "server_release": mcp["server_release"],
        "release_manifest_sha256": runtime["release_manifest_sha256"],
        "python_flags": runtime["python_flags"],
        "sealed_launcher_path": runtime["sealed_launcher_path"],
        "sealed_launcher_sha256": runtime["sealed_launcher_sha256"],
        "launcher_mode": "client",
        "profile": "morning_preparation",
        "subject": "cs408",
    }
    if not value["plugin_version"] or not value["server_release"]:
        raise ReleaseError("morning_pointer_target_invalid")
    return canonical_bytes(value)


def _external_profile_target_material(target: Path) -> dict[str, Any]:
    runtime, mcp = _sealed_runtime_from_target(target)
    ordinary_mcp_profile = _render_ordinary_mcp_profile(runtime)
    plugin_root = target / "plugin" / "kaoyan-study-intake"
    plugin_version = mcp.get("plugin_version")
    try:
        components = json.loads(
            (plugin_root / "components.json").read_text(encoding="utf-8")
        )
        plugin_version = components["plugin"]["version"]
    except (OSError, UnicodeError, json.JSONDecodeError, KeyError, TypeError) as exc:
        raise ReleaseError("external_profile_target_invalid") from exc
    if not isinstance(plugin_version, str) or not plugin_version or "/" in plugin_version:
        raise ReleaseError("external_profile_target_invalid")
    plugin_inventory = _directory_inventory(
        plugin_root, error_code="external_profile_target_invalid"
    )
    morning_pointer = _morning_pointer_bytes(runtime, mcp)
    return {
        "runtime": runtime,
        "ordinary_mcp_profile": ordinary_mcp_profile,
        "ordinary_mcp_profile_sha256": sha256_bytes(ordinary_mcp_profile),
        "morning_pointer": morning_pointer,
        "morning_pointer_sha256": sha256_bytes(morning_pointer),
        "plugin_root": plugin_root,
        "plugin_version": plugin_version,
        "plugin_inventory": plugin_inventory,
    }


def _external_profile_plan(
    target: Path,
    *,
    codex_config_path: Path,
    morning_pointer_path: Path,
    plugin_cache_root: Path,
) -> dict[str, Any] | None:
    if not _external_profile_target_enabled(target):
        return None
    material = _external_profile_target_material(target)
    plugin_cache_path = plugin_cache_root.expanduser().absolute() / str(
        material["plugin_version"]
    )
    preimage_audit = _audit_external_profile_preimages(
        codex_config_path=codex_config_path,
        morning_pointer_path=morning_pointer_path,
        plugin_cache_path=plugin_cache_path,
    )
    value = {
        "schema_version": "study-intake-external-profile-plan-v1",
        "ordinary_profile_path": str(codex_config_path.expanduser().absolute()),
        "mcp_profile_target_sha256": material["ordinary_mcp_profile_sha256"],
        "morning_pointer_path": str(morning_pointer_path.expanduser().absolute()),
        "morning_pointer_target_sha256": material["morning_pointer_sha256"],
        "plugin_cache_path": str(plugin_cache_path),
        "plugin_cache_target_tree_sha256": material["plugin_inventory"][
            "tree_sha256"
        ],
        "mcp_release_id": material["runtime"]["release_id"],
        "mcp_release_manifest_sha256": material["runtime"][
            "release_manifest_sha256"
        ],
        "sealed_launcher_sha256": material["runtime"][
            "sealed_launcher_sha256"
        ],
        "preimage_audit": preimage_audit,
    }
    return {**value, "plan_sha256": sha256_bytes(canonical_bytes(value))}


def _required_external_file(path: Path, *, error_code: str, maximum_bytes: int) -> bytes:
    candidate = path.expanduser().absolute()
    if candidate in {Path("/"), Path.home()}:
        raise ReleaseError(error_code)
    try:
        node = candidate.lstat()
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if (
        candidate.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or node.st_size > maximum_bytes
    ):
        raise ReleaseError(error_code)
    try:
        return candidate.read_bytes()
    except OSError as exc:
        raise ReleaseError(error_code) from exc


def _audit_external_profile_preimages(
    *,
    codex_config_path: Path,
    morning_pointer_path: Path,
    plugin_cache_path: Path,
) -> dict[str, Any]:
    """Read-only proof that every external activation preimage can be backed up.

    Preview uses the same strict readers as the apply transaction.  This keeps
    a dry run from reporting a usable target while the live ordinary profile,
    morning pointer, or plugin-cache tree is already unopenable.
    """

    config_path = codex_config_path.expanduser().absolute()
    pointer_path = morning_pointer_path.expanduser().absolute()
    cache_path = plugin_cache_path.expanduser().absolute()
    config = _required_external_file(
        config_path,
        error_code="ordinary_profile_invalid",
        maximum_bytes=16 * 1024 * 1024,
    )
    _start, _end, mcp_profile = _ordinary_mcp_profile_span(config)
    pointer = _required_external_file(
        pointer_path,
        error_code="morning_pointer_invalid",
        maximum_bytes=1024 * 1024,
    )
    try:
        pointer_value = json.loads(pointer.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("morning_pointer_invalid") from exc
    if not isinstance(pointer_value, Mapping):
        raise ReleaseError("morning_pointer_invalid")
    cache_inventory = _optional_directory_preimage(
        cache_path,
        error_code="plugin_cache_invalid",
    )
    proof = {
        "schema_version": "study-intake-external-profile-preimage-audit-v1",
        "status": "verified_backup_ready",
        "ordinary_config_sha256": sha256_bytes(config),
        "ordinary_config_mode": stat.S_IMODE(config_path.lstat().st_mode),
        "ordinary_mcp_profile_sha256": sha256_bytes(mcp_profile),
        "morning_pointer_sha256": sha256_bytes(pointer),
        "morning_pointer_mode": stat.S_IMODE(pointer_path.lstat().st_mode),
        "plugin_cache_state": cache_inventory["state"],
        "plugin_cache_tree_sha256": cache_inventory["tree_sha256"],
        "plugin_cache_file_count": cache_inventory["file_count"],
        "plugin_cache_total_bytes": cache_inventory["total_bytes"],
        "formal_write_count": 0,
    }
    return {**proof, "proof_sha256": sha256_bytes(canonical_bytes(proof))}


def _backup_external_profiles(
    target: Path,
    *,
    codex_config_path: Path,
    morning_pointer_path: Path,
    plugin_cache_root: Path,
    backup_root: Path,
) -> dict[str, Any] | None:
    if not _external_profile_target_enabled(target):
        return None
    if backup_root.exists() or backup_root.is_symlink():
        raise ReleaseError("external_profile_backup_exists")
    material = _external_profile_target_material(target)
    config_path = codex_config_path.expanduser().absolute()
    pointer_path = morning_pointer_path.expanduser().absolute()
    cache_path = plugin_cache_root.expanduser().absolute() / str(
        material["plugin_version"]
    )
    config = _required_external_file(
        config_path, error_code="ordinary_profile_invalid", maximum_bytes=16 * 1024 * 1024
    )
    _start, _end, old_mcp_profile = _ordinary_mcp_profile_span(config)
    pointer = _required_external_file(
        pointer_path, error_code="morning_pointer_invalid", maximum_bytes=1024 * 1024
    )
    try:
        pointer_value = json.loads(pointer.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("morning_pointer_invalid") from exc
    if not isinstance(pointer_value, Mapping):
        raise ReleaseError("morning_pointer_invalid")
    cache_inventory = _optional_directory_preimage(
        cache_path, error_code="plugin_cache_invalid"
    )
    backup_root.mkdir(parents=True, exist_ok=False, mode=0o700)
    _atomic_bytes(backup_root / "ordinary-config.toml", config, mode=0o600)
    _atomic_bytes(backup_root / "ordinary-mcp-profile.toml", old_mcp_profile, mode=0o600)
    _atomic_bytes(backup_root / "morning-pointer.json", pointer, mode=0o600)
    plugin_backup_path: str | None = None
    if cache_inventory["state"] == "present":
        copied_inventory = _copy_verified_directory(
            cache_path, backup_root / "plugin-cache"
        )
        expected_copy = {
            key: value
            for key, value in cache_inventory.items()
            if key != "state"
        }
        if copied_inventory != expected_copy:
            raise ReleaseError("plugin_cache_backup_mismatch")
        plugin_backup_path = str(backup_root / "plugin-cache")
    inventory = {
        "schema_version": "study-intake-external-profile-backup-v1",
        "ordinary_profile": {
            "path": str(config_path),
            "sha256": sha256_bytes(config),
            "mode": stat.S_IMODE(config_path.lstat().st_mode),
            "backup_path": str(backup_root / "ordinary-config.toml"),
        },
        "mcp_profile": {
            "sha256": sha256_bytes(old_mcp_profile),
            "backup_path": str(backup_root / "ordinary-mcp-profile.toml"),
        },
        "morning_pointer": {
            "path": str(pointer_path),
            "sha256": sha256_bytes(pointer),
            "mode": stat.S_IMODE(pointer_path.lstat().st_mode),
            "backup_path": str(backup_root / "morning-pointer.json"),
        },
        "plugin_cache": {
            "path": str(cache_path),
            "state": cache_inventory["state"],
            "tree_sha256": cache_inventory["tree_sha256"],
            "backup_path": plugin_backup_path,
        },
    }
    inventory_id = sha256_bytes(canonical_bytes(inventory))
    complete = {**inventory, "inventory_sha256": inventory_id}
    atomic_json(backup_root / "inventory.json", complete, mode=0o600)
    return complete


def _apply_external_profiles(
    target: Path,
    snapshot: Mapping[str, Any],
    *,
    token: str,
) -> dict[str, Any]:
    material = _external_profile_target_material(target)
    ordinary = snapshot.get("ordinary_profile")
    pointer = snapshot.get("morning_pointer")
    plugin = snapshot.get("plugin_cache")
    if not all(isinstance(row, Mapping) for row in (ordinary, pointer, plugin)):
        raise ReleaseError("external_profile_snapshot_invalid")
    config_path = Path(str(ordinary["path"])).expanduser().absolute()
    pointer_path = Path(str(pointer["path"])).expanduser().absolute()
    cache_path = Path(str(plugin["path"])).expanduser().absolute()
    current_config = _required_external_file(
        config_path, error_code="ordinary_profile_invalid", maximum_bytes=16 * 1024 * 1024
    )
    if sha256_bytes(current_config) != ordinary.get("sha256"):
        raise ReleaseError("ordinary_profile_changed_after_backup")
    current_pointer = _required_external_file(
        pointer_path, error_code="morning_pointer_invalid", maximum_bytes=1024 * 1024
    )
    if sha256_bytes(current_pointer) != pointer.get("sha256"):
        raise ReleaseError("morning_pointer_changed_after_backup")
    current_cache = _optional_directory_preimage(
        cache_path, error_code="plugin_cache_invalid"
    )
    if (
        current_cache["state"] != plugin.get("state")
        or current_cache["tree_sha256"] != plugin.get("tree_sha256")
    ):
        raise ReleaseError("plugin_cache_changed_after_backup")
    target_config = _replace_ordinary_mcp_profile(
        current_config, material["ordinary_mcp_profile"]
    )
    _atomic_bytes(config_path, target_config, mode=int(ordinary["mode"]))
    _atomic_bytes(
        pointer_path,
        material["morning_pointer"],
        mode=int(pointer["mode"]),
    )
    installed_cache = _atomic_replace_directory(
        cache_path,
        Path(str(material["plugin_root"])),
        token=token,
    )
    _start, _end, installed_mcp_profile = _ordinary_mcp_profile_span(
        config_path.read_bytes()
    )
    proof = {
        "schema_version": "study-intake-external-profile-apply-proof-v1",
        "status": "applied",
        "ordinary_profile_sha256": sha256_file(config_path),
        "mcp_profile_sha256": sha256_bytes(installed_mcp_profile),
        "morning_pointer_sha256": sha256_file(pointer_path),
        "plugin_cache_tree_sha256": installed_cache["tree_sha256"],
        "mcp_release_id": material["runtime"]["release_id"],
        "mcp_release_manifest_sha256": material["runtime"][
            "release_manifest_sha256"
        ],
    }
    if (
        proof["mcp_profile_sha256"] != material["ordinary_mcp_profile_sha256"]
        or proof["morning_pointer_sha256"] != material["morning_pointer_sha256"]
        or proof["plugin_cache_tree_sha256"]
        != material["plugin_inventory"]["tree_sha256"]
    ):
        raise ReleaseError("external_profile_apply_mismatch")
    return {**proof, "proof_sha256": sha256_bytes(canonical_bytes(proof))}


def _restore_external_profiles(
    snapshot: Mapping[str, Any],
    *,
    token: str,
) -> dict[str, Any]:
    ordinary = snapshot.get("ordinary_profile")
    mcp_profile = snapshot.get("mcp_profile")
    pointer = snapshot.get("morning_pointer")
    plugin = snapshot.get("plugin_cache")
    if not all(
        isinstance(row, Mapping)
        for row in (ordinary, mcp_profile, pointer, plugin)
    ):
        raise ReleaseError("external_profile_snapshot_invalid")
    config_backup = Path(str(ordinary["backup_path"]))
    pointer_backup = Path(str(pointer["backup_path"]))
    plugin_state = plugin.get("state")
    plugin_backup = (
        Path(str(plugin["backup_path"]))
        if plugin_state == "present"
        else None
    )
    config = _required_external_file(
        config_backup,
        error_code="external_profile_backup_invalid",
        maximum_bytes=16 * 1024 * 1024,
    )
    pointer_bytes = _required_external_file(
        pointer_backup,
        error_code="external_profile_backup_invalid",
        maximum_bytes=1024 * 1024,
    )
    if (
        sha256_bytes(config) != ordinary.get("sha256")
        or sha256_bytes(pointer_bytes) != pointer.get("sha256")
        or plugin_state not in {"present", "absent"}
        or (
            plugin_state == "present"
            and (
                plugin_backup is None
                or _directory_inventory(
                    plugin_backup,
                    error_code="external_profile_backup_invalid",
                )["tree_sha256"]
                != plugin.get("tree_sha256")
            )
        )
        or (
            plugin_state == "absent"
            and (
                plugin.get("tree_sha256") is not None
                or plugin.get("backup_path") is not None
            )
        )
    ):
        raise ReleaseError("external_profile_backup_hash_mismatch")
    config_path = Path(str(ordinary["path"]))
    pointer_path = Path(str(pointer["path"]))
    plugin_path = Path(str(plugin["path"]))
    _atomic_bytes(config_path, config, mode=int(ordinary["mode"]))
    _atomic_bytes(pointer_path, pointer_bytes, mode=int(pointer["mode"]))
    if plugin_state == "present":
        assert plugin_backup is not None
        restored_plugin = _atomic_replace_directory(
            plugin_path, plugin_backup, token=f"{token}-restore"
        )
        restored_plugin_state = "present"
        restored_plugin_sha256 = restored_plugin["tree_sha256"]
    else:
        if plugin_path.exists() or plugin_path.is_symlink():
            _directory_inventory(
                plugin_path, error_code="external_profile_restore_target_invalid"
            )
            _make_tree_removable(plugin_path)
            shutil.rmtree(plugin_path)
            _fsync_directory(plugin_path.parent)
        if plugin_path.exists() or plugin_path.is_symlink():
            raise ReleaseError("external_profile_restore_mismatch")
        restored_plugin_state = "absent"
        restored_plugin_sha256 = None
    _start, _end, restored_mcp_profile = _ordinary_mcp_profile_span(
        config_path.read_bytes()
    )
    proof = {
        "schema_version": "study-intake-external-profile-restore-proof-v1",
        "status": "restored",
        "ordinary_profile_sha256": sha256_file(config_path),
        "mcp_profile_sha256": sha256_bytes(restored_mcp_profile),
        "morning_pointer_sha256": sha256_file(pointer_path),
        "plugin_cache_state": restored_plugin_state,
        "plugin_cache_tree_sha256": restored_plugin_sha256,
    }
    if (
        proof["ordinary_profile_sha256"] != ordinary.get("sha256")
        or proof["mcp_profile_sha256"] != mcp_profile.get("sha256")
        or proof["morning_pointer_sha256"] != pointer.get("sha256")
        or proof["plugin_cache_state"] != plugin_state
        or proof["plugin_cache_tree_sha256"] != plugin.get("tree_sha256")
    ):
        raise ReleaseError("external_profile_restore_mismatch")
    return {**proof, "proof_sha256": sha256_bytes(canonical_bytes(proof))}


def _deployment_authority_key(release_base: Path, *, create: bool) -> bytes:
    path = release_base / "deployments" / "authority.key"
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if create and not path.exists():
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(secrets.token_bytes(32))
                handle.flush()
                os.fsync(handle.fileno())
        except Exception:
            try:
                path.unlink()
            except FileNotFoundError:
                pass
            raise
    try:
        node = path.lstat()
        key = path.read_bytes()
    except OSError as exc:
        raise ReleaseError("deployment_authority_unavailable") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or node.st_uid != os.getuid()
        or stat.S_IMODE(node.st_mode) != 0o600
        or len(key) != 32
    ):
        raise ReleaseError("deployment_authority_invalid")
    return key


def _seal_deployment_value(
    value: Mapping[str, Any], *, release_base: Path, purpose: str
) -> dict[str, Any]:
    core = dict(value)
    core.pop("authority", None)
    key = _deployment_authority_key(release_base, create=True)
    mac = hmac.new(key, canonical_bytes(core), hashlib.sha256).hexdigest()
    return {
        **core,
        "authority": {
            "schema_version": DRAIN_AUTHORITY_SCHEMA,
            "algorithm": "HMAC-SHA256",
            "key_id": sha256_bytes(key),
            "purpose": purpose,
            "hmac_sha256": mac,
        },
    }


def _verify_deployment_authority(
    value: Mapping[str, Any], *, release_base: Path, purpose: str
) -> None:
    authority = value.get("authority")
    if not isinstance(authority, Mapping):
        raise ReleaseError("deployment_authority_missing")
    core = dict(value)
    core.pop("authority", None)
    key = _deployment_authority_key(release_base, create=False)
    expected = hmac.new(key, canonical_bytes(core), hashlib.sha256).hexdigest()
    if (
        set(authority)
        != {"schema_version", "algorithm", "key_id", "purpose", "hmac_sha256"}
        or authority.get("schema_version") != DRAIN_AUTHORITY_SCHEMA
        or authority.get("algorithm") != "HMAC-SHA256"
        or authority.get("key_id") != sha256_bytes(key)
        or authority.get("purpose") != purpose
        or not hmac.compare_digest(str(authority.get("hmac_sha256") or ""), expected)
    ):
        raise ReleaseError("deployment_authority_invalid")


def _validate_subject_batch_recovery_canary_binding(
    value: Any,
    *,
    release_id: str,
) -> dict[str, Any]:
    hashes = (
        "original_preclaim_failure_receipt_sha256",
        "recovery_receipt_sha256",
        "target_release_id",
        "target_activation_id",
        "staged_activation_proof_sha256",
        "supersede_receipt_sha256",
        "replacement_queue_entry_sha256",
        "arm_proof_sha256",
    )
    replacement_hashes = (
        "unit_sha256",
        "frozen_payload_sha256",
        "task_object_sha256",
        "producer_input_contract_sha256",
        "source_event_set_sha256",
    )
    expected_keys = {
        "schema_version",
        "subject",
        *hashes,
        "replacement_task",
        "formal_write_count",
        "sol_enabled",
    }
    replacement = (
        value.get("replacement_task")
        if isinstance(value, Mapping)
        else None
    )
    if (
        not isinstance(value, Mapping)
        or set(value) != expected_keys
        or value.get("schema_version")
        != "study-intake-subject-batch-recovery-canary-binding-v1"
        or value.get("subject") != "english"
        or any(
            SHA256_RE.fullmatch(str(value.get(key) or "")) is None
            for key in hashes
        )
        or value.get("target_release_id") != release_id
        or not isinstance(replacement, Mapping)
        or set(replacement) != set(replacement_hashes)
        or any(
            SHA256_RE.fullmatch(str(replacement.get(key) or "")) is None
            for key in replacement_hashes
        )
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
    ):
        raise ReleaseError(
            "three_subject_canary_recovery_binding_invalid"
        )
    return copy.deepcopy(dict(value))


def _validate_cs408_terminal_retirement_canary_binding(
    value: Any,
    *,
    release_id: str,
    activation_id: str,
    release_base: Path,
) -> dict[str, Any]:
    descriptor = CS408_TERMINAL_RETIREMENT_DESCRIPTOR
    exact_descriptor_fields = {
        "subject",
        "batch_id",
        "batch_sha256",
        "terminal_receipt_sha256",
        "writer_preimage_sha256",
        "batch_pointer_sha256",
        "snapshot_sha256",
        "source_generation",
        "source_authority_fingerprint",
        "target_generation",
        "target_authority_fingerprint",
    }
    expected_keys = {
        "schema_version",
        *exact_descriptor_fields,
        "mode",
        "authorization_descriptor_sha256",
        "target_release_id",
        "target_activation_id",
        "retirement_receipt_sha256",
        "retirement_receipt_path",
        "retirement_receipt_path_sha256",
        "retirement_rollback_token",
        "writer_postimage_sha256",
        "postimage_verification_sha256",
        "post_retirement_readiness_sha256",
        "locked_preflight_authority_snapshot_mcp_tool_call_count",
        "retirement_authority_snapshot_mcp_tool_call_count",
        "english_recovery_authority_snapshot_mcp_tool_call_count",
        "arm_preflight_authority_snapshot_mcp_tool_call_count",
        "apply_authority_snapshot_mcp_tool_call_count",
        "authority_snapshot_count",
        "authority_snapshot_mcp_tool_call_count",
        "model_mcp_tool_call_count",
        "model_call_count",
        "provider_request_count",
        "formal_write_count",
        "sol_enabled",
        "queue_entry_created_count",
        "replacement_task_created_count",
        "capture_replay_count",
    }
    receipt_sha256 = str(
        value.get("retirement_receipt_sha256") or ""
    ) if isinstance(value, Mapping) else ""
    receipt_path_raw = (
        value.get("retirement_receipt_path")
        if isinstance(value, Mapping)
        else None
    )
    expected_receipt_path: Path | None = None
    if SHA256_RE.fullmatch(receipt_sha256) is not None:
        try:
            config_path = (
                release_base / "releases" / release_id / "config.json"
            )
            config = json.loads(config_path.read_text(encoding="utf-8"))
            runtime_root = Path(str(config["runtime_root"])).resolve()
            expected_receipt_path = (
                runtime_root
                / "dispatch"
                / "control-receipts"
                / "cs408-terminal-batch-retirements"
                / "sha256"
                / receipt_sha256[:2]
                / f"{receipt_sha256}.json"
            )
        except (OSError, UnicodeError, json.JSONDecodeError, KeyError, TypeError):
            expected_receipt_path = None
    if (
        not isinstance(value, Mapping)
        or set(value) != expected_keys
        or value.get("schema_version")
        != CS408_TERMINAL_RETIREMENT_BINDING_SCHEMA
        or any(value.get(key) != descriptor[key] for key in exact_descriptor_fields)
        or value.get("mode") != descriptor["mode"]
        or value.get("authorization_descriptor_sha256")
        != _authorization_descriptor_sha256(descriptor)
        or value.get("target_release_id") != release_id
        or value.get("target_activation_id") != activation_id
        or SHA256_RE.fullmatch(
            receipt_sha256
        )
        is None
        or not isinstance(receipt_path_raw, str)
        or not Path(receipt_path_raw).is_absolute()
        or expected_receipt_path is None
        or Path(receipt_path_raw) != expected_receipt_path
        or SHA256_RE.fullmatch(
            str(value.get("retirement_receipt_path_sha256") or "")
        )
        is None
        or value.get("retirement_receipt_path_sha256")
        != sha256_bytes(receipt_path_raw.encode("utf-8"))
        or SHA256_RE.fullmatch(
            str(value.get("retirement_rollback_token") or "")
        )
        is None
        or any(
            SHA256_RE.fullmatch(str(value.get(key) or "")) is None
            for key in (
                "writer_postimage_sha256",
                "postimage_verification_sha256",
                "post_retirement_readiness_sha256",
            )
        )
        or value.get("authority_snapshot_count") != 2
        or value.get("authority_snapshot_mcp_tool_call_count") != 2
        or value.get("model_mcp_tool_call_count") != 0
        or value.get(
            "locked_preflight_authority_snapshot_mcp_tool_call_count"
        )
        != 3
        or value.get(
            "retirement_authority_snapshot_mcp_tool_call_count"
        )
        != 2
        or value.get(
            "english_recovery_authority_snapshot_mcp_tool_call_count"
        )
        != 2
        or value.get(
            "arm_preflight_authority_snapshot_mcp_tool_call_count"
        )
        != 3
        or value.get("apply_authority_snapshot_mcp_tool_call_count") != 10
        or value.get("model_call_count") != 0
        or value.get("provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
        or value.get("queue_entry_created_count") != 0
        or value.get("replacement_task_created_count") != 0
        or value.get("capture_replay_count") != 0
    ):
        raise ReleaseError(
            "three_subject_canary_cs408_retirement_binding_invalid"
        )
    return copy.deepcopy(dict(value))


