def _bind_cs408_terminal_retirement_to_canary_proof(
    proof: Mapping[str, Any],
    *,
    retirement: Mapping[str, Any],
    release_id: str,
    activation_id: str,
    release_base: Path,
) -> dict[str, Any]:
    descriptor = CS408_TERMINAL_RETIREMENT_DESCRIPTOR
    cs408_row = next(
        (
            row
            for row in proof.get("subjects", [])
            if isinstance(row, Mapping) and row.get("subject") == "cs408"
        ),
        None,
    )
    if (
        not isinstance(cs408_row, Mapping)
        or cs408_row.get("cs408_terminal_retirement_required") is not True
        or cs408_row.get("cs408_terminal_retirement_already_applied") is not True
        or cs408_row.get("cs408_terminal_retirement_receipt_sha256")
        != retirement.get("retirement_receipt_sha256")
        or cs408_row.get("cs408_terminal_retirement_receipt_path")
        != retirement.get("retirement_receipt_path")
        or cs408_row.get("cs408_terminal_retirement_rollback_token")
        != retirement.get("rollback_token")
    ):
        raise ReleaseError("cs408_terminal_batch_retirement_chain_invalid")
    binding = {
        "schema_version": CS408_TERMINAL_RETIREMENT_BINDING_SCHEMA,
        **descriptor,
        "authorization_descriptor_sha256": _authorization_descriptor_sha256(
            descriptor
        ),
        "target_release_id": release_id,
        "target_activation_id": activation_id,
        "retirement_receipt_sha256": retirement[
            "retirement_receipt_sha256"
        ],
        "retirement_receipt_path": retirement["retirement_receipt_path"],
        "retirement_receipt_path_sha256": sha256_bytes(
            str(retirement["retirement_receipt_path"]).encode("utf-8")
        ),
        "retirement_rollback_token": retirement["rollback_token"],
        "writer_postimage_sha256": retirement["writer_postimage_sha256"],
        "postimage_verification_sha256": retirement[
            "postimage_verification_sha256"
        ],
        "post_retirement_readiness_sha256": cs408_row[
            "subject_batch_readiness_sha256"
        ],
        "authority_snapshot_count": retirement["authority_snapshot_count"],
        "authority_snapshot_mcp_tool_call_count": retirement[
            "authority_snapshot_mcp_tool_call_count"
        ],
        "model_mcp_tool_call_count": retirement[
            "model_mcp_tool_call_count"
        ],
        "locked_preflight_authority_snapshot_mcp_tool_call_count": 3,
        "retirement_authority_snapshot_mcp_tool_call_count": 2,
        "english_recovery_authority_snapshot_mcp_tool_call_count": 2,
        "arm_preflight_authority_snapshot_mcp_tool_call_count": 3,
        "apply_authority_snapshot_mcp_tool_call_count": 10,
        "model_call_count": 0,
        "provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
        "queue_entry_created_count": 0,
        "replacement_task_created_count": 0,
        "capture_replay_count": 0,
    }
    _validate_cs408_terminal_retirement_canary_binding(
        binding,
        release_id=release_id,
        activation_id=activation_id,
        release_base=release_base,
    )
    result = copy.deepcopy(dict(proof))
    if "cs408_writer_retirement_binding" in result:
        raise ReleaseError("cs408_terminal_batch_retirement_binding_conflict")
    result["cs408_writer_retirement_binding"] = binding
    return result


def _cs408_retirement_apply_mcp_accounting(
    *,
    retirement_completed: bool,
    english_recovery_completed: bool,
    arm_preflight_completed: bool,
) -> dict[str, Any]:
    retirement_count = 2 if retirement_completed else 0
    english_count = 2 if english_recovery_completed else 0
    arm_count = 3 if arm_preflight_completed else 0
    return {
        "schema_version": (
            "study-intake-cs408-terminal-retirement-mcp-accounting-v1"
        ),
        "locked_preflight_authority_snapshot_mcp_tool_call_count": 3,
        "retirement_authority_snapshot_mcp_tool_call_count": retirement_count,
        "english_recovery_authority_snapshot_mcp_tool_call_count": (
            english_count
        ),
        "arm_preflight_authority_snapshot_mcp_tool_call_count": arm_count,
        "apply_authority_snapshot_mcp_tool_call_count": 3
        + retirement_count
        + english_count
        + arm_count,
        "model_mcp_tool_call_count": 0,
        "model_call_count": 0,
        "provider_request_count": 0,
        "formal_write_count": 0,
    }


def _default_canary_rollback_controller(
    *,
    release_id: str,
    target: Path,
    runtime_data_root: Path,
    runner: CommandRunner,
    canary_context: Mapping[str, Any],
) -> dict[str, Any]:
    del runtime_data_root, canary_context

    def run_json(subject: str, suffix: Sequence[str]) -> dict[str, Any]:
        command = [
            sys.executable,
            str(target / "bin" / "preprocess_dispatcher.py"),
            "--config",
            str(target / "config.json"),
            "--subject",
            subject,
            *suffix,
        ]
        completed = runner(command)
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(
                f"three_subject_canary_rollback_invalid:{subject}"
            ) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(f"three_subject_canary_rollback_invalid:{subject}")
        return payload

    subjects: list[dict[str, Any]] = []
    for subject in RESUMABLE_SUBJECTS:
        before = run_json(subject, ["status"])
        gate = before.get("canary_gate")
        if gate is None:
            state = "not_armed"
            after = before
        else:
            if (
                not isinstance(gate, Mapping)
                or gate.get("release_id") != release_id
            ):
                raise ReleaseError(
                    f"three_subject_canary_rollback_invalid:{subject}"
                )
            if gate.get("state") != "inactive_rolled_back":
                rolled_back = run_json(
                    subject,
                    [
                        "deactivate-canary",
                        "--expected-release-id",
                        release_id,
                    ],
                )
                if (
                    rolled_back.get("status") != "production_canary_inactive"
                    or rolled_back.get("state") != "inactive_rolled_back"
                    or rolled_back.get("subject") != subject
                    or rolled_back.get("release_id") != release_id
                    or rolled_back.get("producer_capture_enabled") is not True
                    or rolled_back.get("luna_consumer_enabled") is not False
                    or rolled_back.get("formal_write_count") != 0
                    or rolled_back.get("sol_enabled") is not False
                ):
                    raise ReleaseError(
                        f"three_subject_canary_rollback_invalid:{subject}"
                    )
            state = "inactive_rolled_back"
            after = run_json(subject, ["status"])
            after_gate = after.get("canary_gate")
            if (
                not isinstance(after_gate, Mapping)
                or after_gate.get("status") != "production_canary_inactive"
                or after_gate.get("state") != "inactive_rolled_back"
                or after_gate.get("release_id") != release_id
                or after_gate.get("luna_consumer_enabled") is not False
            ):
                raise ReleaseError(
                    f"three_subject_canary_rollback_invalid:{subject}"
                )
        subjects.append(
            {
                "subject": subject,
                "state": state,
                "producer_queue_preserved": True,
                "status_sha256": sha256_bytes(canonical_bytes(after)),
            }
        )
    return {
        "schema_version": "study-intake-three-subject-canary-rollback-v1",
        "status": "canary_activation_rolled_back",
        "release_id": release_id,
        "producer_queues_preserved": True,
        "subjects": subjects,
        "formal_write_count": 0,
    }


def _deactivate_previous_canary_states(
    *,
    previous_release_id: str,
    previous_release: Path,
    active_link: Path,
    runtime_data_root: Path,
    previous_canary_state_snapshots: Mapping[str, Mapping[str, Any]],
    runner: CommandRunner,
) -> dict[str, Any]:
    """Deactivate byte-locked stopped-release gates before successor arm."""

    def run_json(subject: str, suffix: Sequence[str]) -> dict[str, Any]:
        completed = runner(
            [
                sys.executable,
                str(previous_release / "bin" / "preprocess_dispatcher.py"),
                "--config",
                str(previous_release / "config.json"),
                "--subject",
                subject,
                *suffix,
            ]
        )
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(
                f"previous_canary_deactivation_invalid:{subject}"
            ) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(
                f"previous_canary_deactivation_invalid:{subject}"
            )
        return payload

    if (
        not isinstance(previous_canary_state_snapshots, Mapping)
        or set(previous_canary_state_snapshots) != set(RESUMABLE_SUBJECTS)
    ):
        raise ReleaseError("previous_canary_deactivation_invalid:snapshots")

    state_root = (
        runtime_data_root / "dispatch" / "state" / "production-canary"
    ).expanduser().absolute()
    rows: list[dict[str, Any]] = []
    for subject in RESUMABLE_SUBJECTS:
        error_code = f"previous_canary_deactivation_invalid:{subject}"
        expected_path = (state_root / f"{subject}.json").absolute()
        snapshot = previous_canary_state_snapshots.get(subject)
        if (
            not isinstance(snapshot, Mapping)
            or set(snapshot)
            != {"path", "existed", "value", "mode", "sha256"}
            or Path(str(snapshot.get("path") or "")).expanduser().absolute()
            != expected_path
        ):
            raise ReleaseError(error_code)

        if snapshot.get("existed") is False:
            if (
                snapshot.get("value") is not None
                or snapshot.get("mode") is not None
                or snapshot.get("sha256") is not None
            ):
                raise ReleaseError(error_code)
            try:
                expected_path.lstat()
            except FileNotFoundError:
                pass
            else:
                raise ReleaseError(error_code)
            rows.append({"subject": subject, "state": "not_armed"})
            continue

        value = snapshot.get("value")
        mode = snapshot.get("mode")
        expected_sha256 = snapshot.get("sha256")
        try:
            node = expected_path.lstat()
            current = expected_path.read_bytes()
            gate = json.loads(current)
        except (FileNotFoundError, OSError, json.JSONDecodeError) as exc:
            raise ReleaseError(error_code) from exc
        if (
            snapshot.get("existed") is not True
            or not isinstance(value, bytes)
            or not isinstance(mode, int)
            or isinstance(mode, bool)
            or SHA256_RE.fullmatch(str(expected_sha256 or "")) is None
            or sha256_bytes(value) != expected_sha256
            or not stat.S_ISREG(node.st_mode)
            or expected_path.is_symlink()
            or stat.S_IMODE(node.st_mode) != mode
            or current != value
            or sha256_bytes(current) != expected_sha256
            or not isinstance(gate, Mapping)
            or gate.get("subject") != subject
            or gate.get("release_id") != previous_release_id
            or isinstance(gate.get("active_task_count"), bool)
            or gate.get("active_task_count") != 0
            or gate.get("formal_write_count") != 0
            or gate.get("sol_enabled") is not False
        ):
            raise ReleaseError(error_code)

        # A prior failed transaction may already have durably deactivated an
        # old subject gate while the shared concurrency telemetry now belongs
        # to the current mixed-state release.  Re-running deactivate-canary in
        # that state is both unnecessary and guaranteed to fail its telemetry
        # binding.  The byte-locked signed inactive gate is the complete
        # idempotent postimage, so accept it without invoking the old runtime.
        if (
            gate.get("status") == "production_canary_inactive"
            and gate.get("state") == "inactive_rolled_back"
            and gate.get("luna_consumer_enabled") is False
        ):
            rows.append(
                {
                    "subject": subject,
                    "state": "inactive_rolled_back",
                    "gate_sha256": sha256_bytes(current),
                }
            )
            continue

        # Do not ask the stopped release for a pre-deactivation status.  A
        # failed target may have left the shared concurrency projection bound
        # to itself while this exact gate snapshot was restored.  The old
        # release's direct deactivation validates the signed gate and zero
        # active_task_count, then atomically recomputes that projection.
        run_json(
            subject,
            [
                "deactivate-canary",
                "--expected-release-id",
                previous_release_id,
            ],
        )
        status = run_json(subject, ["status"])
        post_gate = status.get("canary_gate")
        if (
            status.get("active_count") != 0
            or status.get("claimed_total") != 0
            or not isinstance(post_gate, Mapping)
            or post_gate.get("status") != "production_canary_inactive"
            or post_gate.get("state") != "inactive_rolled_back"
            or post_gate.get("subject") != subject
            or post_gate.get("release_id") != previous_release_id
            or isinstance(post_gate.get("active_task_count"), bool)
            or post_gate.get("active_task_count") != 0
            or post_gate.get("luna_consumer_enabled") is not False
            or post_gate.get("formal_write_count") != 0
            or post_gate.get("sol_enabled") is not False
        ):
            raise ReleaseError(error_code)
        try:
            persisted = json.loads(expected_path.read_bytes())
        except (FileNotFoundError, OSError, json.JSONDecodeError) as exc:
            raise ReleaseError(error_code) from exc
        if persisted != post_gate:
            raise ReleaseError(error_code)
        rows.append(
            {
                "subject": subject,
                "state": "inactive_rolled_back",
                "gate_sha256": sha256_bytes(canonical_bytes(post_gate)),
            }
        )
    return {
        "schema_version": "study-intake-previous-canary-deactivation-v1",
        "status": "previous_canary_deactivated",
        "previous_release_id": previous_release_id,
        "active_link": str(active_link),
        "subjects": rows,
        "formal_write_count": 0,
    }


def _validate_canary_rollback_proof(
    value: Mapping[str, Any], *, release_id: str
) -> dict[str, Any]:
    subjects = value.get("subjects")
    if (
        value.get("schema_version")
        != "study-intake-three-subject-canary-rollback-v1"
        or value.get("status") != "canary_activation_rolled_back"
        or value.get("release_id") != release_id
        or value.get("producer_queues_preserved") is not True
        or not isinstance(subjects, list)
        or len(subjects) != len(RESUMABLE_SUBJECTS)
        or {row.get("subject") for row in subjects if isinstance(row, Mapping)}
        != set(RESUMABLE_SUBJECTS)
        or any(
            not isinstance(row, Mapping)
            or row.get("state") not in {"not_armed", "inactive_rolled_back"}
            or row.get("producer_queue_preserved") is not True
            or SHA256_RE.fullmatch(str(row.get("status_sha256") or "")) is None
            for row in subjects
        )
        or value.get("formal_write_count") != 0
    ):
        raise ReleaseError("three_subject_canary_rollback_invalid")
    return copy.deepcopy(dict(value))


def _default_canary_shutdown_before_activation_rollback(
    *,
    release_id: str,
    target: Path,
    runtime_data_root: Path,
    topology: Sequence[Mapping[str, Any]],
    runner: CommandRunner,
    shutdown_timeout_seconds: float = 15.0,
) -> dict[str, Any]:
    """Fence every live Canary lease before deactivating a failed activation."""

    def run_json(
        subject: str, suffix: Sequence[str], error_code: str
    ) -> dict[str, Any]:
        completed = runner(
            [
                sys.executable,
                str(target / "bin" / "preprocess_dispatcher.py"),
                "--config",
                str(target / "config.json"),
                "--subject",
                subject,
                *suffix,
            ]
        )
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(error_code) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(error_code)
        return payload

    gate_before: dict[str, dict[str, Any]] = {}
    for subject in RESUMABLE_SUBJECTS:
        status = run_json(
            subject,
            ["status"],
            f"canary_activation_failure_status_invalid:{subject}",
        )
        active_count = status.get("active_count")
        claimed_total = status.get("claimed_total")
        gate = status.get("canary_gate")
        if (
            status.get("subject") != subject
            or not isinstance(active_count, int)
            or isinstance(active_count, bool)
            or not 0 <= active_count <= CONTINUOUS_CONCURRENCY_LIMIT
            or not isinstance(claimed_total, int)
            or isinstance(claimed_total, bool)
            or not 0 <= claimed_total <= CONTINUOUS_CONCURRENCY_LIMIT
        ):
            raise ReleaseError(
                f"canary_activation_failure_status_invalid:{subject}"
            )
        if gate is None:
            if active_count != 0 or claimed_total != 0:
                raise ReleaseError(
                    f"canary_activation_failure_gate_missing:{subject}"
                )
            continue
        # A failed activation may have armed only a prefix of the subjects.
        # An untouched source-release gate is already safely inactive and must
        # not be treated as a malformed target gate.  Leave it out of
        # gate_before so the rollback routine fences only gates belonging to
        # the release that actually mutated state.
        if (
            isinstance(gate, Mapping)
            and gate.get("status") == "production_canary_inactive"
            and gate.get("state") == "inactive_rolled_back"
            and gate.get("subject") == subject
            and gate.get("release_id") != release_id
            and gate.get("luna_consumer_enabled") is False
            and gate.get("active_task_count") == 0
            and gate.get("formal_write_count") == 0
            and gate.get("sol_enabled") is False
            and gate.get("production_accepted") is False
        ):
            continue
        if (
            not isinstance(gate, Mapping)
            or not _canary_v2_common_controls_valid(gate)
            or gate.get("subject") != subject
            or gate.get("release_id") != release_id
            or gate.get("active_task_count") != active_count
            or active_count > _canary_active_limit(gate)
            or claimed_total > _canary_active_limit(gate)
        ):
            raise ReleaseError(
                f"canary_activation_failure_gate_invalid:{subject}"
            )
        gate_before[subject] = copy.deepcopy(dict(gate))

    drained, paused_gates, errors = _rollback_three_subject_dispatchers(
        release_id=release_id,
        subjects=RESUMABLE_SUBJECTS,
        services=topology,
        run_json=run_json,
        runner=runner,
        gate_before=gate_before,
        shutdown_timeout_seconds=shutdown_timeout_seconds,
        require_complete_gate_set=False,
    )
    if errors:
        raise ReleaseError(
            "canary_activation_failure_shutdown_incomplete:"
            + "|".join(errors)
        )
    rows: list[dict[str, Any]] = []
    for subject in RESUMABLE_SUBJECTS:
        status = drained.get(subject)
        if not isinstance(status, Mapping):
            raise ReleaseError(
                f"canary_activation_failure_shutdown_incomplete:{subject}"
            )
        stale_count = status.get("stale_count")
        if (
            status.get("active_count") != 0
            or status.get("claimed_total") != 0
            or not isinstance(stale_count, int)
            or isinstance(stale_count, bool)
            or stale_count < 0
            or SHA256_RE.fullmatch(str(status.get("status_sha256") or ""))
            is None
        ):
            raise ReleaseError(
                f"canary_activation_failure_shutdown_incomplete:{subject}"
            )
        paused = paused_gates.get(subject)
        rows.append(
            {
                "subject": subject,
                "active_count": 0,
                "claimed_total": 0,
                "stale_count": stale_count,
                "status_sha256": status["status_sha256"],
                "emergency_cancel": (
                    copy.deepcopy(paused.get("emergency_cancel"))
                    if isinstance(paused, Mapping)
                    else None
                ),
            }
        )
    return {
        "schema_version": "study-intake-rollback-drain-v1",
        "status": "drained",
        "release_id": release_id,
        "runtime_data_root": str(runtime_data_root),
        "shutdown_order": [
            "disable_keepalive",
            "bootout_sigterm",
            "verify_hard_cancel_and_late_fence",
            "verify_zero_active_claimed",
            "pause_before_deactivate",
        ],
        "subjects": rows,
        "formal_write_count": 0,
    }


def _validate_canary_preflight_proof(
    value: Mapping[str, Any], *, release_id: str, apply: bool
) -> dict[str, Any]:
    deployment_status = (
        "verified_deployment_controls_and_slots_armed"
        if apply
        else "verified_deployment_controls_and_slots_planned"
    )
    if value.get("status") == deployment_status:
        subjects = value.get("subjects")
        expected_state = "armed" if apply else "planned"
        if (
            value.get("schema_version") != THREE_SUBJECT_CANARY_PREFLIGHT_SCHEMA
            or value.get("release_id") != release_id
            or value.get("post_activation_only") is not True
            or not isinstance(subjects, list)
            or len(subjects) != len(RESUMABLE_SUBJECTS)
            or {
                row.get("subject")
                for row in subjects
                if isinstance(row, Mapping)
            }
            != set(RESUMABLE_SUBJECTS)
            or any(
                not isinstance(row, Mapping)
                or row.get("gate_state") != expected_state
                or row.get("active_count") != 0
                or row.get("claimed_total") != 0
                or (
                    apply
                    and SHA256_RE.fullmatch(
                        str(
                            row.get("producer_high_watermark_sha256") or ""
                        )
                    )
                    is None
                )
                or (
                    not apply
                    and row.get("producer_high_watermark_sha256") is not None
                )
                or SHA256_RE.fullmatch(
                    str(row.get("deployment_snapshot_sha256") or "")
                )
                is None
                or (
                    apply
                    and SHA256_RE.fullmatch(
                        str(row.get("gate_sha256") or "")
                    )
                    is None
                )
                or (not apply and row.get("gate_sha256") is not None)
                for row in subjects
            )
            or value.get("verification_model_call_count") != 0
            or value.get("verification_provider_request_count") != 0
            or value.get("verification_mcp_tool_call_count") != 0
            or value.get("formal_write_count") != 0
            or value.get("sol_enabled") is not False
        ):
            raise ReleaseError("three_subject_canary_preflight_invalid")
        return copy.deepcopy(dict(value))
    subjects = value.get("subjects")
    expected_state = "armed" if apply else "planned"

    def row_invalid(row: Any) -> bool:
        if not isinstance(row, Mapping):
            return True
        historical = row.get("historical_eligible_count")
        common_invalid = (
            row.get("gate_state") != expected_state
            or not isinstance(historical, int)
            or isinstance(historical, bool)
            or historical < 0
            or row.get("active_count") != 0
            or row.get("claimed_total") != 0
            or row.get("initial_canary_inflight_limit")
            != INITIAL_CANARY_INFLIGHT_LIMIT
            or row.get("continuous_concurrency_limit")
            != CONTINUOUS_CONCURRENCY_LIMIT
            or row.get("requested_service_tier") is not REQUESTED_SERVICE_TIER
            or row.get("fast_mode_requested") is not FAST_MODE_REQUESTED
            or row.get("fast_mode_effective") != FAST_MODE_EFFECTIVE
            or SHA256_RE.fullmatch(str(row.get("status_sha256") or "")) is None
            or SHA256_RE.fullmatch(str(row.get("audit_sha256") or "")) is None
        )
        if common_invalid:
            return True
        readiness_fields = (
            "subject_batch_readiness",
            "subject_batch_readiness_sha256",
            "subject_recovery_required",
            "subject_recovery_already_applied",
            "subject_recovery_original_preclaim_failure_receipt_sha256",
            "subject_recovery_receipt_sha256",
            "subject_recovery_receipt_path",
            "subject_recovery_rollback_token",
            "subject_readiness_mcp_tool_call_count",
            "subject_authority_generation",
            "subject_authority_fingerprint",
        )
        readiness_values_present = any(
            field in row for field in readiness_fields
        )
        recovery_required = False
        if readiness_values_present:
            recovery_required = row.get("subject_recovery_required")
            recovery_already_applied = row.get(
                "subject_recovery_already_applied"
            )
            readiness = row.get("subject_batch_readiness")
            recovery_sha256 = row.get(
                "subject_recovery_original_preclaim_failure_receipt_sha256"
            )
            recovery_receipt_sha256 = row.get(
                "subject_recovery_receipt_sha256"
            )
            recovery_receipt_path = row.get(
                "subject_recovery_receipt_path"
            )
            recovery_rollback_token = row.get(
                "subject_recovery_rollback_token"
            )
            if (
                not all(field in row for field in readiness_fields)
                or readiness
                not in {
                    "ready",
                    "recoverable_terminal_batch",
                    "recoverable_review_correction",
                    "recoverable_math_pending_queue_migration",
                }
                or SHA256_RE.fullmatch(
                    str(row.get("subject_batch_readiness_sha256") or "")
                )
                is None
                or type(recovery_required) is not bool
                or type(recovery_already_applied) is not bool
                or row.get("subject_readiness_mcp_tool_call_count") != 1
                or not isinstance(row.get("subject_authority_generation"), str)
                or not str(row["subject_authority_generation"]).strip()
                or SHA256_RE.fullmatch(
                    str(row.get("subject_authority_fingerprint") or "")
                )
                is None
                or (
                    recovery_required
                    and (
                        row.get("subject") != "english"
                        or readiness
                        not in {"recoverable_terminal_batch", "ready"}
                        or SHA256_RE.fullmatch(str(recovery_sha256 or ""))
                        is None
                    )
                )
                or (
                    recovery_already_applied
                    and (
                        not recovery_required
                        or readiness != "ready"
                        or SHA256_RE.fullmatch(
                            str(recovery_receipt_sha256 or "")
                        )
                        is None
                        or not isinstance(recovery_receipt_path, str)
                        or not Path(recovery_receipt_path).is_absolute()
                        or SHA256_RE.fullmatch(
                            str(recovery_rollback_token or "")
                        )
                        is None
                    )
                )
                or (
                    not recovery_already_applied
                    and any(
                        value is not None
                        for value in (
                            recovery_receipt_sha256,
                            recovery_receipt_path,
                            recovery_rollback_token,
                        )
                    )
                )
                or (
                    not recovery_required
                    and (
                        recovery_sha256 is not None
                        or recovery_already_applied
                    )
                )
                or (
                    apply
                    and readiness
                    not in {
                        "ready",
                        "recoverable_math_pending_queue_migration",
                    }
                )
            ):
                return True
        review_correction_fields = (
            "english_preserved_review_repair_required",
            "english_preserved_review_repair_descriptor_sha256",
            "english_preserved_review_repair_preview_sha256",
            "english_preserved_review_repair_source_gate_preimage_sha256",
        )
        review_correction_values_present = any(
            field in row for field in review_correction_fields
        )
        if review_correction_values_present:
            required = row.get("english_preserved_review_repair_required")
            descriptor_sha256 = row.get(
                "english_preserved_review_repair_descriptor_sha256"
            )
            preview_sha256 = row.get(
                "english_preserved_review_repair_preview_sha256"
            )
            source_gate_sha256 = row.get(
                "english_preserved_review_repair_source_gate_preimage_sha256"
            )
            if (
                not all(
                    field in row for field in review_correction_fields
                )
                or type(required) is not bool
                or (
                    required
                    and (
                        apply
                        or row.get("subject") != "english"
                        or row.get("subject_batch_readiness")
                        != "recoverable_review_correction"
                        or descriptor_sha256
                        != ENGLISH_PRESERVED_REVIEW_REPAIR_DESCRIPTOR_SHA256
                        or SHA256_RE.fullmatch(str(preview_sha256 or ""))
                        is None
                        or source_gate_sha256
                        != ENGLISH_PRESERVED_REVIEW_REPAIR_SOURCE_GATE_SHA256
                        or row.get("subject_recovery_required") is not False
                        or row.get("subject_recovery_already_applied")
                        is not False
                    )
                )
                or (
                    not required
                    and (
                        row.get("subject_batch_readiness")
                        == "recoverable_review_correction"
                        or any(
                            value is not None
                            for value in (
                                descriptor_sha256,
                                preview_sha256,
                                source_gate_sha256,
                            )
                        )
                    )
                )
            ):
                return True
        elif row.get("subject_batch_readiness") == (
            "recoverable_review_correction"
        ):
            return True
        math_migration_fields = (
            "math_pending_queue_migration_required",
            "math_pending_queue_migration_intent_sha256",
            "math_pending_queue_migration_archive_sha256",
        )
        math_migration_values_present = any(
            field in row for field in math_migration_fields
        )
        if math_migration_values_present:
            math_migration_required = row.get(
                "math_pending_queue_migration_required"
            )
            math_migration_intent_sha256 = row.get(
                "math_pending_queue_migration_intent_sha256"
            )
            math_migration_archive_sha256 = row.get(
                "math_pending_queue_migration_archive_sha256"
            )
            if (
                not all(field in row for field in math_migration_fields)
                or type(math_migration_required) is not bool
                or (
                    math_migration_required
                    and (
                        row.get("subject") != "math"
                        or row.get("subject_batch_readiness")
                        != "recoverable_math_pending_queue_migration"
                        or SHA256_RE.fullmatch(
                            str(math_migration_intent_sha256 or "")
                        )
                        is None
                        or SHA256_RE.fullmatch(
                            str(math_migration_archive_sha256 or "")
                        )
                        is None
                        or row.get("subject_recovery_required") is not False
                        or row.get("subject_recovery_already_applied") is not False
                    )
                )
                or (
                    not math_migration_required
                    and (
                        row.get("subject_batch_readiness")
                        == "recoverable_math_pending_queue_migration"
                        or math_migration_intent_sha256 is not None
                        or math_migration_archive_sha256 is not None
                    )
                )
            ):
                return True
        elif row.get("subject_batch_readiness") == (
            "recoverable_math_pending_queue_migration"
        ):
            return True
        retirement_fields = (
            "cs408_terminal_retirement_required",
            "cs408_terminal_retirement_already_applied",
            "cs408_terminal_retirement_terminal_receipt_sha256",
            "cs408_terminal_retirement_receipt_sha256",
            "cs408_terminal_retirement_receipt_path",
            "cs408_terminal_retirement_rollback_token",
        )
        retirement_values_present = any(
            field in row for field in retirement_fields
        )
        if retirement_values_present:
            required = row.get("cs408_terminal_retirement_required")
            already_applied = row.get(
                "cs408_terminal_retirement_already_applied"
            )
            authorized_receipt = row.get(
                "cs408_terminal_retirement_terminal_receipt_sha256"
            )
            retirement_receipt = row.get(
                "cs408_terminal_retirement_receipt_sha256"
            )
            retirement_path = row.get(
                "cs408_terminal_retirement_receipt_path"
            )
            rollback_token = row.get(
                "cs408_terminal_retirement_rollback_token"
            )
            if (
                not all(field in row for field in retirement_fields)
                or type(required) is not bool
                or type(already_applied) is not bool
                or (
                    required
                    and (
                        row.get("subject") != "cs408"
                        or authorized_receipt
                        != CS408_TERMINAL_RETIREMENT_DESCRIPTOR[
                            "terminal_receipt_sha256"
                        ]
                        or row.get("subject_batch_readiness")
                        not in {"recoverable_terminal_batch", "ready"}
                    )
                )
                or (
                    already_applied
                    and (
                        not required
                        or row.get("subject_batch_readiness") != "ready"
                        or SHA256_RE.fullmatch(
                            str(retirement_receipt or "")
                        )
                        is None
                        or not isinstance(retirement_path, str)
                        or not Path(retirement_path).is_absolute()
                        or SHA256_RE.fullmatch(str(rollback_token or ""))
                        is None
                    )
                )
                or (
                    not already_applied
                    and any(
                        item is not None
                        for item in (
                            retirement_receipt,
                            retirement_path,
                            rollback_token,
                        )
                    )
                )
                or (
                    not required
                    and (
                        already_applied
                        or authorized_receipt is not None
                    )
                )
                or (apply and required and not already_applied)
            ):
                return True
        if not apply:
            return any(
                row.get(field) is not None
                for field in (
                    "excluded_by_high_watermark_count",
                    "canary_queue_count",
                    "producer_high_watermark_sha256",
                    "queue_classification_sha256",
                )
            )
        excluded = row.get("excluded_by_high_watermark_count")
        queued = row.get("canary_queue_count")
        return (
            not isinstance(excluded, int)
            or isinstance(excluded, bool)
            or (
                recovery_required
                and excluded + 1 != historical
            )
            or (
                not recovery_required
                and excluded < historical
            )
            or not isinstance(queued, int)
            or isinstance(queued, bool)
            or queued < 0
            or SHA256_RE.fullmatch(
                str(row.get("producer_high_watermark_sha256") or "")
            )
            is None
            or SHA256_RE.fullmatch(
                str(row.get("queue_classification_sha256") or "")
            )
            is None
        )

    if (
        value.get("schema_version") != THREE_SUBJECT_CANARY_PREFLIGHT_SCHEMA
        or value.get("status")
        != (
            "verified_historical_backlog_drained_and_slots_armed"
            if apply
            else "verified_historical_backlog_drained_and_slots_planned"
        )
        or value.get("release_id") != release_id
        or value.get("historical_backlog_drained") is not True
        or value.get("post_activation_only") is not True
        or value.get("initial_canary_inflight_limit")
        != INITIAL_CANARY_INFLIGHT_LIMIT
        or value.get("continuous_concurrency_limit")
        != CONTINUOUS_CONCURRENCY_LIMIT
        or value.get("requested_service_tier") is not REQUESTED_SERVICE_TIER
        or value.get("fast_mode_requested") is not FAST_MODE_REQUESTED
        or value.get("fast_mode_effective") != FAST_MODE_EFFECTIVE
        or not isinstance(subjects, list)
        or len(subjects) != len(RESUMABLE_SUBJECTS)
        or {row.get("subject") for row in subjects if isinstance(row, Mapping)}
        != set(RESUMABLE_SUBJECTS)
        or any(row_invalid(row) for row in subjects)
        or value.get("verification_model_call_count") != 0
        or value.get("verification_provider_request_count") != 0
        or value.get("verification_mcp_tool_call_count")
        != len(RESUMABLE_SUBJECTS)
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
    ):
        raise ReleaseError("three_subject_canary_preflight_invalid")
    return copy.deepcopy(dict(value))


def _validate_post_canary_proof(
    value: Mapping[str, Any], *, release_id: str,
    math_migration_paused: bool = False,
) -> dict[str, Any]:
    controls = value.get("subject_controls")
    service_release_ids = value.get("service_release_ids")
    if (
        value.get("schema_version")
        != THREE_SUBJECT_CANARY_POST_ACTIVATION_SCHEMA
        or value.get("status") != "verified_production_canary_active"
        or value.get("release_id") != release_id
        or value.get("service_count") != 4
        or value.get("running_service_count") != 4
        or value.get("disabled_service_count") != 0
        or value.get("dispatcher_heartbeat_count") != 3
        or value.get("post_activation_only") is not True
        or value.get("initial_canary_inflight_limit")
        != INITIAL_CANARY_INFLIGHT_LIMIT
        or value.get("continuous_concurrency_limit")
        != CONTINUOUS_CONCURRENCY_LIMIT
        or value.get("requested_service_tier") is not REQUESTED_SERVICE_TIER
        or value.get("fast_mode_requested") is not FAST_MODE_REQUESTED
        or value.get("fast_mode_effective") != FAST_MODE_EFFECTIVE
        or not isinstance(service_release_ids, Mapping)
        or set(service_release_ids)
        != {"math", "cs408", "english", "dashboard"}
        or any(item != release_id for item in service_release_ids.values())
        or not isinstance(controls, list)
        or len(controls) != len(RESUMABLE_SUBJECTS)
        or {row.get("subject") for row in controls if isinstance(row, Mapping)}
        != set(RESUMABLE_SUBJECTS)
        or any(
            not isinstance(row, Mapping)
            or row.get("enabled") is not True
            or row.get("running") is not True
            or row.get("draining") is not True
            or row.get("gate_state")
            != (
                "paused_drained"
                if math_migration_paused and row.get("subject") == "math"
                else "armed"
            )
            or row.get("post_activation_only") is not True
            or row.get("initial_canary_inflight_limit")
            != INITIAL_CANARY_INFLIGHT_LIMIT
            or row.get("continuous_concurrency_limit")
            != CONTINUOUS_CONCURRENCY_LIMIT
            or row.get("requested_service_tier") is not REQUESTED_SERVICE_TIER
            or row.get("fast_mode_requested") is not FAST_MODE_REQUESTED
            or row.get("fast_mode_effective") != FAST_MODE_EFFECTIVE
            or row.get("producer_capture_enabled") is not True
            or row.get("luna_consumer_enabled")
            is not (
                False
                if math_migration_paused and row.get("subject") == "math"
                else True
            )
            or not isinstance(row.get("active_count"), int)
            or isinstance(row.get("active_count"), bool)
            or row.get("active_count") < 0
            or row.get("active_count") > 1
            or not isinstance(row.get("claimed_total"), int)
            or isinstance(row.get("claimed_total"), bool)
            or row.get("claimed_total") < 0
            or row.get("claimed_total") > 1
            or SHA256_RE.fullmatch(
                str(row.get("producer_high_watermark_sha256") or "")
            )
            is None
            for row in controls
        )
        or value.get("model") != REQUIRED_MODEL_CONTRACT["model"]
        or value.get("reasoning_effort")
        != REQUIRED_MODEL_CONTRACT["reasoning_effort"]
        or value.get("verification_model_call_count") != 0
        or value.get("verification_provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
        or value.get("production_accepted") is not False
    ):
        raise ReleaseError("three_subject_canary_post_activation_invalid")
    return copy.deepcopy(dict(value))


def _write_deployment_receipt(
    release_base: Path, receipt: Mapping[str, Any]
) -> str:
    receipt_id = sha256_bytes(canonical_bytes(receipt))
    atomic_json(release_base / "deployments" / f"{receipt_id}.json", receipt)
    return receipt_id


def _deployment_receipt_objects(release_base: Path) -> dict[str, dict[str, Any]]:
    """Reopen content-addressed deployment receipts without writing.

    Draining is recorded outside the content-addressed deployment ledger so a
    completed drain cannot be mistaken for a transaction receipt.  A drain
    record is therefore admitted only under its exact, target-bound filename
    and after its own authority envelope has been verified; it is then ignored
    by the deployment transaction scanner.
    """

    root = release_base / "deployments"
    if not root.exists():
        return {}
    if root.is_symlink() or not root.is_dir():
        raise ReleaseError("deployment_receipt_root_invalid")
    values: dict[str, dict[str, Any]] = {}
    for path in sorted(root.glob("*.json"), key=lambda item: item.name):
        if path.is_symlink():
            raise ReleaseError("deployment_receipt_invalid")
        try:
            raw = path.read_bytes()
            value = json.loads(raw)
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ReleaseError("deployment_receipt_invalid") from exc
        if not isinstance(value, dict) or raw != canonical_bytes(value):
            raise ReleaseError("deployment_receipt_invalid")
        if SHA256_RE.fullmatch(path.stem) is not None:
            if sha256_bytes(raw) != path.stem:
                raise ReleaseError("deployment_receipt_invalid")
            values[path.stem] = value
            continue
        drain_match = re.fullmatch(r"drain-([0-9a-f]{64})", path.stem)
        if drain_match is None:
            raise ReleaseError("deployment_receipt_invalid")
        target_release_id = drain_match.group(1)
        if (
            value.get("schema_version") != DRAIN_RECEIPT_SCHEMA
            or value.get("target_release_id") != target_release_id
            or type(value.get("formal_write_count")) is not int
            or value.get("formal_write_count") != 0
        ):
            raise ReleaseError("deployment_receipt_invalid")
        try:
            _verify_deployment_authority(
                value,
                release_base=release_base,
                purpose="release-drain-receipt",
            )
        except ReleaseError as exc:
            raise ReleaseError("deployment_receipt_invalid") from exc
    return values


def _verify_deployment_recovery_marker(
    value: Mapping[str, Any],
    *,
    release_base: Path,
    prepare_sha256: str,
    prepare: Mapping[str, Any],
) -> dict[str, Any]:
    if (
        prepare.get("schema_version") != DEPLOYMENT_PREPARE_SCHEMA
        or prepare.get("operation") not in {"activate", "rollback"}
        or not isinstance(prepare.get("release_id"), str)
        or SHA256_RE.fullmatch(str(prepare.get("release_id"))) is None
        or prepare.get("formal_write_count") != 0
    ):
        raise ReleaseError("deployment_recovery_marker_invalid")

    def reopen_inventory(path: Path, *, external: bool) -> str:
        try:
            stat_result = path.lstat()
            raw = path.read_bytes()
            inventory = json.loads(raw)
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ReleaseError("deployment_recovery_marker_invalid") from exc
        if (
            not stat.S_ISREG(stat_result.st_mode)
            or path.is_symlink()
            or len(raw) > 16 * 1024 * 1024
            or not isinstance(inventory, dict)
            or raw != canonical_bytes(inventory)
        ):
            raise ReleaseError("deployment_recovery_marker_invalid")
        if external:
            embedded = inventory.get("inventory_sha256")
            core = dict(inventory)
            core.pop("inventory_sha256", None)
            if (
                not isinstance(embedded, str)
                or SHA256_RE.fullmatch(embedded) is None
                or embedded != sha256_bytes(canonical_bytes(core))
            ):
                raise ReleaseError("deployment_recovery_marker_invalid")
        return sha256_bytes(raw)

    try:
        resolved_at = dt.datetime.fromisoformat(
            str(value.get("resolved_at") or "").replace("Z", "+00:00")
        )
    except ValueError:
        resolved_at = None
    expected_keys = {
        "schema_version",
        "prepare_receipt_sha256",
        "observed_current_release_id",
        "launchagent_backup_inventory_sha256",
        "external_profile_backup_inventory_sha256",
        "current_surface_sha256s",
        "outcome",
        "resolved_at",
        "formal_write_count",
        "authority",
    }
    surfaces = value.get("current_surface_sha256s")
    expected_surface_keys = {
        "current_symlink",
        "launchagent_plists",
        "ordinary_profile",
        "morning_pointer",
        "plugin_cache",
    }
    launchagent_inventory_sha256 = reopen_inventory(
        release_base
        / "deployments"
        / "launchagent-backups"
        / prepare_sha256
        / "inventory.json",
        external=False,
    )
    external_inventory_sha256 = reopen_inventory(
        release_base
        / "deployments"
        / "external-profile-backups"
        / prepare_sha256
        / "inventory.json",
        external=True,
    )
    if (
        set(value) != expected_keys
        or value.get("schema_version") != DEPLOYMENT_RECOVERY_MARKER_SCHEMA
        or value.get("prepare_receipt_sha256") != prepare_sha256
        or value.get("observed_current_release_id")
        != prepare.get("observed_current")
        or not isinstance(value.get("launchagent_backup_inventory_sha256"), str)
        or SHA256_RE.fullmatch(
            str(value.get("launchagent_backup_inventory_sha256") or "")
        )
        is None
        or value.get("launchagent_backup_inventory_sha256")
        != launchagent_inventory_sha256
        or not isinstance(
            value.get("external_profile_backup_inventory_sha256"), str
        )
        or SHA256_RE.fullmatch(
            str(value.get("external_profile_backup_inventory_sha256") or "")
        )
        is None
        or value.get("external_profile_backup_inventory_sha256")
        != external_inventory_sha256
        or not isinstance(surfaces, Mapping)
        or set(surfaces) != expected_surface_keys
        or any(
            not isinstance(surfaces.get(name), str)
            or SHA256_RE.fullmatch(str(surfaces.get(name) or "")) is None
            for name in expected_surface_keys
        )
        or value.get("outcome")
        not in {"verified_no_mutation", "verified_exact_restore"}
        or not isinstance(value.get("resolved_at"), str)
        or resolved_at is None
        or resolved_at.tzinfo is None
        or value.get("formal_write_count") != 0
    ):
        raise ReleaseError("deployment_recovery_marker_invalid")
    try:
        _verify_deployment_authority(
            value,
            release_base=release_base,
            purpose=DEPLOYMENT_RECOVERY_MARKER_PURPOSE,
        )
    except ReleaseError as exc:
        raise ReleaseError("deployment_recovery_marker_invalid") from exc
    return copy.deepcopy(dict(value))


def _deployment_receipt_timestamp(
    value: Mapping[str, Any], field: str
) -> dt.datetime:
    raw = value.get(field)
    if not isinstance(raw, str):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    try:
        parsed = dt.datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if parsed.tzinfo is None:
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    return parsed


def _verify_historical_manager_script(
    *, release_base: Path, release_id: str, expected_sha256: str
) -> None:
    path = release_base / "releases" / release_id / "scripts" / "release_manager.py"
    try:
        node = path.lstat()
        actual_sha256 = sha256_file(path)
    except OSError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or actual_sha256 != expected_sha256
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _verify_historical_executor_release(
    *, release_base: Path, release_id: str, expected_manifest_sha256: str
) -> None:
    path = release_base / "releases" / release_id / "release.json"
    try:
        node = path.lstat()
        actual_sha256 = sha256_file(path)
    except OSError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or actual_sha256 != expected_manifest_sha256
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _recovery_v2_read_json_snapshot(path: Path) -> dict[str, Any]:
    try:
        node = path.lstat()
        raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or len(raw) > 16 * 1024 * 1024
        or not isinstance(value, dict)
        or raw != canonical_bytes(value)
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    return {
        "path": str(path),
        "sha256": sha256_bytes(raw),
        "value": value,
    }


def _verify_recovery_v2_dispatch_authority(
    value: Mapping[str, Any], *, runtime_root: Path, purpose: str
) -> None:
    authority = value.get("authority")
    key_path = runtime_root / "dispatch" / "state" / "authority.key"
    try:
        node = key_path.lstat()
        key = key_path.read_bytes()
    except OSError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    core = dict(value)
    core.pop("authority", None)
    expected = hmac.new(
        key,
        json.dumps(
            {"purpose": purpose, "payload": core},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()
    if (
        key_path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or stat.S_IMODE(node.st_mode) != 0o600
        or len(key) != 32
        or not isinstance(authority, Mapping)
        or authority.get("schema_version") != "study-intake-dispatch-authority-v1"
        or authority.get("algorithm") != "HMAC-SHA256"
        or authority.get("key_id") != sha256_bytes(key)
        or authority.get("purpose") != purpose
        or not hmac.compare_digest(
            str(authority.get("hmac_sha256") or ""), expected
        )
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _verify_recovery_v2_immutable_source(
    path: Path, *, expected_sha256: str
) -> None:
    """Require the exact a4ff compatibility implementation before using it."""

    try:
        node = path.lstat()
    except OSError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if (
        path.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or SHA256_RE.fullmatch(expected_sha256) is None
        or sha256_file(path) != expected_sha256
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _verify_recovery_v2_member_semantics(
    evidence: Mapping[str, Any], *, member: str
) -> None:
    """Validate the durable a4ff v2 receipt/index semantics, not only HMAC."""

    if member == "activation_receipt":
        if (
            evidence.get("schema_version")
            != "study-intake-production-canary-activation-receipt-v2"
            or evidence.get("model_call_count") != 0
            or evidence.get("provider_request_count") != 0
            or evidence.get("mcp_tool_call_count") != 0
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        return
    outcomes = evidence.get("terminal_by_outcome")
    units = evidence.get("units")
    task_count = evidence.get("terminal_task_count")
    if (
        evidence.get("schema_version")
        != "study-intake-production-canary-terminal-index-v2"
        or evidence.get("counter_scope")
        != "current_activation_latest_terminal_per_unit"
        or evidence.get("model_call_count") != 0
        or evidence.get("provider_request_count") != 0
        or not isinstance(outcomes, Mapping)
        or set(outcomes)
        != {"cancelled", "failed", "needs_rework", "succeeded", "timed_out"}
        or any(isinstance(raw, bool) or not isinstance(raw, int) or raw < 0 for raw in outcomes.values())
        or isinstance(task_count, bool)
        or not isinstance(task_count, int)
        or task_count < 0
        or sum(outcomes.values()) != task_count
        or not isinstance(units, Mapping)
        or len(units) != task_count
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _verify_recovery_v2_member_cross_bindings(
    state: Mapping[str, Any],
    *,
    activation: Mapping[str, Any],
    terminal_index: Mapping[str, Any],
) -> None:
    if (
        state.get("activation_gate_authority_sha256")
        != sha256_bytes(
            json.dumps(
                activation.get("authority"),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
            ).encode("utf-8")
        )
        or state.get("terminal_by_outcome")
        != terminal_index.get("terminal_by_outcome")
        or state.get("terminal_task_count")
        != terminal_index.get("terminal_task_count")
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _recovery_v2_public_canary_gate(
    state: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    release_base: Path,
    descriptor: Mapping[str, Any],
) -> dict[str, Any]:
    """Rebuild the public gate through the sealed a4ff v2 implementation."""

    release_root = release_base / "releases" / release_id
    library_root = release_root / "lib"
    dashboard_path = library_root / "dashboard_projection.py"
    concurrent_path = library_root / "concurrent_dispatch.py"
    _verify_recovery_v2_immutable_source(
        dashboard_path,
        expected_sha256=str(descriptor["resolution_dashboard_projection_sha256"]),
    )
    _verify_recovery_v2_immutable_source(
        concurrent_path,
        expected_sha256=str(descriptor["resolution_concurrent_dispatch_sha256"]),
    )
    script = """import importlib.util\nimport json\nimport sys\nfrom pathlib import Path\nlibrary_root = Path(sys.argv[1])\nsubject = sys.argv[2]\nrelease_id = sys.argv[3]\nsys.path.insert(0, str(library_root))\nspec = importlib.util.spec_from_file_location('_study_intake_recovery_v2_dashboard_projection', library_root / 'dashboard_projection.py')\nif spec is None or spec.loader is None:\n    raise RuntimeError('dashboard_projection_load_failed')\nmodule = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(module)\nvalue = json.load(sys.stdin)\ngate = module._public_canary_gate(value, subject=subject, release_id=release_id)\nif not isinstance(gate, dict):\n    raise RuntimeError('production_canary_gate_missing')\nsys.stdout.buffer.write((json.dumps(gate, ensure_ascii=False, sort_keys=True, separators=(',', ':')) + '\\n').encode('utf-8'))\n"""
    try:
        completed = subprocess.run(
            [
                sys.executable,
                "-I",
                "-S",
                "-c",
                script,
                str(library_root),
                subject,
                release_id,
            ],
            input=canonical_bytes(state),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=10,
        )
        raw = completed.stdout
        result = json.loads(raw)
    except (OSError, UnicodeError, ValueError, subprocess.TimeoutExpired) as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    if (
        completed.returncode != 0
        or not isinstance(result, dict)
        or raw != canonical_bytes(result)
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    return result


def _capture_recovery_v2_resolution_evidence_once(
    *,
    current_release: Path,
    release_id: str,
    release_base: Path,
    descriptor: Mapping[str, Any],
) -> dict[str, Any]:
    try:
        config = json.loads((current_release / "config.json").read_text("utf-8"))
        runtime_root = Path(str(config["runtime_root"])).expanduser().resolve()
    except (OSError, UnicodeError, json.JSONDecodeError, KeyError) as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    states: dict[str, dict[str, Any]] = {}
    for subject in RESUMABLE_SUBJECTS:
        expected_state_path = (
            runtime_root / "dispatch" / "state" / "production-canary" / f"{subject}.json"
        )
        snapshot = _recovery_v2_read_json_snapshot(
            expected_state_path
        )
        state = snapshot["value"]
        if (
            snapshot["path"] != str(expected_state_path)
            or
            state.get("schema_version")
            != "study-intake-production-canary-state-v2"
            or state.get("subject") != subject
            or state.get("release_id") != release_id
            or state.get("formal_write_count") != 0
            or state.get("sol_enabled") is not False
            or not isinstance(state.get("authority"), Mapping)
            or not isinstance(state.get("terminal_index_sha256"), str)
            or SHA256_RE.fullmatch(str(state.get("terminal_index_sha256") or ""))
            is None
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        _verify_recovery_v2_dispatch_authority(
            state,
            runtime_root=runtime_root,
            purpose="dispatch-production-canary-state",
        )
        if (
            state.get("active_task_count") != 0
            or state.get("selected") is not None
            or state.get("active_selections") != {}
            or not isinstance(state.get("activation_receipt_path"), str)
            or not isinstance(state.get("terminal_index_path"), str)
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        activation = _recovery_v2_read_json_snapshot(
            Path(str(state["activation_receipt_path"]))
        )
        terminal_index = _recovery_v2_read_json_snapshot(
            Path(str(state["terminal_index_path"]))
        )
        activation_root = runtime_root / "dispatch" / "production-canary" / "receipts" / subject
        terminal_root = runtime_root / "dispatch" / "production-canary" / "terminal-indexes" / subject
        if (
            activation["path"] != state["activation_receipt_path"]
            or terminal_index["path"] != state["terminal_index_path"]
            or activation_root not in Path(activation["path"]).parents
            or terminal_root not in Path(terminal_index["path"]).parents
            or Path(activation["path"]).name != f"{activation['sha256']}.json"
            or Path(terminal_index["path"]).name != f"{terminal_index['sha256']}.json"
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        for evidence, purpose in (
            (activation["value"], "dispatch-production-canary-activation"),
            (terminal_index["value"], "dispatch-production-canary-terminal-index"),
        ):
            if (
                evidence.get("subject") != subject
                or evidence.get("release_id") != release_id
                or evidence.get("activation_id") != state.get("activation_id")
                or evidence.get("formal_write_count") != 0
                or evidence.get("sol_enabled") is not False
            ):
                raise ReleaseError("deployment_recovery_marker_v2_invalid")
            _verify_recovery_v2_dispatch_authority(
                evidence, runtime_root=runtime_root, purpose=purpose
            )
            _verify_recovery_v2_member_semantics(
                evidence,
                member=(
                    "activation_receipt"
                    if purpose == "dispatch-production-canary-activation"
                    else "terminal_index"
                ),
            )
        if (
            state.get("activation_receipt_sha256") != activation["sha256"]
            or state.get("terminal_index_sha256") != terminal_index["sha256"]
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        _verify_recovery_v2_member_cross_bindings(
            state,
            activation=activation["value"],
            terminal_index=terminal_index["value"],
        )
        snapshot["activation_receipt"] = activation
        snapshot["terminal_index"] = terminal_index
        states[subject] = snapshot
    dashboard = _recovery_v2_read_json_snapshot(
        runtime_root / "state" / "dashboard_projection.json"
    )
    _verify_recovery_v2_dashboard_identity(
        dashboard,
        states=states,
        runtime_root=runtime_root,
        release_id=release_id,
        release_base=release_base,
        descriptor=descriptor,
    )
    return {
        "current_release_id": release_id,
        "current_link_target": str(current_release),
        "states": states,
        "dashboard_projection": dashboard,
        "formal_write_count": 0,
    }


def _verify_recovery_v2_dashboard_identity(
    dashboard_snapshot: Mapping[str, Any],
    *,
    states: Mapping[str, Mapping[str, Any]],
    runtime_root: Path,
    release_id: str,
    release_base: Path,
    descriptor: Mapping[str, Any],
) -> None:
    """Verify the a4ff Dashboard projection is bound to all sealed inputs."""

    dashboard_value = dashboard_snapshot.get("value")
    if (
        not isinstance(dashboard_snapshot, Mapping)
        or set(dashboard_snapshot) != {"path", "sha256", "value"}
        or dashboard_snapshot.get("path")
        != str(runtime_root / "state" / "dashboard_projection.json")
        or not isinstance(dashboard_value, Mapping)
        or sha256_bytes(canonical_bytes(dashboard_value))
        != dashboard_snapshot.get("sha256")
        or dashboard_value.get("schema_version")
        != "study-intake-dashboard-projection-v3"
        or not isinstance(dashboard_value.get("subjects"), Mapping)
        or set(dashboard_value["subjects"]) != set(RESUMABLE_SUBJECTS)
        or not isinstance(dashboard_value.get("dispatchers"), Mapping)
        or set(dashboard_value["dispatchers"]) != set(RESUMABLE_SUBJECTS)
        or not isinstance(dashboard_value.get("global_sol"), Mapping)
        or dashboard_value["global_sol"].get("formal_write_count") not in {0, None}
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    concurrency = dashboard_value.get("concurrency")
    if (
        not isinstance(concurrency, Mapping)
        or concurrency.get("release_id") != release_id
        or concurrency.get("status") != "verified"
        or not isinstance(concurrency.get("source_telemetry"), Mapping)
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    telemetry = concurrency["source_telemetry"]
    telemetry_authority = telemetry.get("authority")
    if (
        telemetry.get("release_id") != release_id
        or telemetry.get("formal_write_count") != 0
        or telemetry.get("sol_enabled") is not False
        or not isinstance(telemetry_authority, Mapping)
        or telemetry_authority.get("purpose")
        != "dispatch-production-canary-concurrency-telemetry"
        or telemetry.get("authority_sha256")
        != sha256_bytes(canonical_bytes(telemetry_authority))
        or concurrency.get("telemetry_authority_sha256")
        != telemetry.get("authority_sha256")
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    telemetry_signed_view = dict(telemetry)
    telemetry_signed_view.pop("authority_sha256", None)
    _verify_recovery_v2_dispatch_authority(
        telemetry_signed_view,
        runtime_root=runtime_root,
        purpose="dispatch-production-canary-concurrency-telemetry",
    )
    terminal_index_sha256_by_subject = telemetry.get("terminal_index_sha256_by_subject")
    activation_ids = telemetry.get("activation_ids")
    active_by_subject = telemetry.get("active_by_subject")
    terminal_task_count_by_subject = telemetry.get("terminal_task_count_by_subject")
    terminal_by_outcome_by_subject = telemetry.get("terminal_by_outcome_by_subject")
    if not all(
        isinstance(member, Mapping)
        for member in (
            terminal_index_sha256_by_subject,
            activation_ids,
            active_by_subject,
            terminal_task_count_by_subject,
            terminal_by_outcome_by_subject,
        )
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    for subject in RESUMABLE_SUBJECTS:
        state_snapshot = states.get(subject)
        if not isinstance(state_snapshot, Mapping) or not isinstance(
            state_snapshot.get("value"), Mapping
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        state = state_snapshot["value"]
        subject_projection = dashboard_value["subjects"].get(subject)
        dispatcher_projection = dashboard_value["dispatchers"].get(subject)
        expected_gate = _recovery_v2_public_canary_gate(
            state,
            subject=subject,
            release_id=release_id,
            release_base=release_base,
            descriptor=descriptor,
        )
        if (
            terminal_index_sha256_by_subject.get(subject)
            != state.get("terminal_index_sha256")
            or activation_ids.get(subject) != state.get("activation_id")
            or active_by_subject.get(subject) != state.get("active_task_count")
            or terminal_task_count_by_subject.get(subject)
            != state.get("terminal_task_count")
            or terminal_by_outcome_by_subject.get(subject)
            != state.get("terminal_by_outcome")
            or not isinstance(subject_projection, Mapping)
            or subject_projection.get("canary_gate") != expected_gate
            or not isinstance(dispatcher_projection, Mapping)
            or dispatcher_projection.get("canary_gate") != expected_gate
            or any(
                dispatcher_projection.get(field) != release_id
                for field in (
                    "release_id",
                    "active_release_id",
                    "heartbeat_release_id",
                )
            )
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _capture_recovery_v2_resolution_evidence(
    *,
    current_release: Path,
    release_id: str,
    release_base: Path,
    descriptor: Mapping[str, Any],
) -> dict[str, Any]:
    """Take a bounded stable read of all mutable signing inputs.

    The marker embeds both readings' shared canonical snapshot, so later
    verification never depends on a future dashboard heartbeat or live state.
    """

    first = _capture_recovery_v2_resolution_evidence_once(
        current_release=current_release,
        release_id=release_id,
        release_base=release_base,
        descriptor=descriptor,
    )
    second = _capture_recovery_v2_resolution_evidence_once(
        current_release=current_release,
        release_id=release_id,
        release_base=release_base,
        descriptor=descriptor,
    )
    if first != second:
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    return first


def create_superseded_transaction_recovery_marker_core(
    *,
    release_base: Path,
    active_link: Path,
    historical_prepare_receipt_sha256: str,
    resolved_at: str,
) -> dict[str, Any]:
    """Return, but never write, a v2 marker core for an audited descriptor."""

    descriptor = SUPERSEDED_TRANSACTION_RECOVERY_DESCRIPTORS.get(
        historical_prepare_receipt_sha256
    )
    if descriptor is None:
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    _deployment_receipt_timestamp({"resolved_at": resolved_at}, "resolved_at")
    with _activation_lock(release_base / "deployments" / "activation.lock", 3.0):
        current_release_id, current_release = _current_release(active_link)
        if current_release_id != descriptor["resolution_head_release_id"]:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        if current_release is None:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        _verify_historical_executor_release(
            release_base=release_base,
            release_id=str(descriptor["historical_executor_release_id"]),
            expected_manifest_sha256=str(
                descriptor["historical_executor_release_manifest_sha256"]
            ),
        )
        _verify_historical_manager_script(
            release_base=release_base,
            release_id=str(descriptor["historical_manager_release_id"]),
            expected_sha256=str(descriptor["historical_manager_sha256"]),
        )
        resolution_evidence = _capture_recovery_v2_resolution_evidence(
            current_release=Path(current_release),
            release_id=str(descriptor["resolution_head_release_id"]),
            release_base=release_base,
            descriptor=descriptor,
        )
    return {
        "schema_version": DEPLOYMENT_RECOVERY_MARKER_V2_SCHEMA,
        "outcome": DEPLOYMENT_RECOVERY_MARKER_V2_OUTCOME,
        "historical_prepare_receipt_sha256": historical_prepare_receipt_sha256,
        "historical_incomplete_postcommit_receipt_sha256": descriptor[
            "historical_incomplete_postcommit_receipt_sha256"
        ],
        "successor_prepare_receipt_sha256": descriptor[
            "successor_prepare_receipt_sha256"
        ],
        "successor_postcommit_receipt_sha256": descriptor[
            "successor_postcommit_receipt_sha256"
        ],
        "successor_release_id": descriptor["successor_release_id"],
        "successor_post_activation_proof_sha256": descriptor[
            "successor_post_activation_proof_sha256"
        ],
        "historical_executor_release_id": descriptor[
            "historical_executor_release_id"
        ],
        "historical_superseded_endpoint_release_id": descriptor[
            "historical_superseded_endpoint_release_id"
        ],
        "historical_manager_sha256": descriptor[
            "historical_manager_sha256"
        ],
        "historical_manager_mutation_scope": descriptor[
            "historical_manager_mutation_scope"
        ],
        "continuation_transactions": [
            dict(item) for item in descriptor.get("continuation_transactions", ())
        ],
        "resolution_evidence": resolution_evidence,
        "resolved_at": resolved_at,
        "formal_write_count": 0,
    }


def _verify_superseded_transaction_recovery_marker(
    value: Mapping[str, Any],
    *,
    release_base: Path,
    receipts: Mapping[str, Mapping[str, Any]],
    historical_prepare_sha256: str,
    historical_prepare: Mapping[str, Any],
) -> None:
    expected_keys = {
        "schema_version",
        "outcome",
        "historical_prepare_receipt_sha256",
        "historical_incomplete_postcommit_receipt_sha256",
        "successor_prepare_receipt_sha256",
        "successor_postcommit_receipt_sha256",
        "successor_release_id",
        "successor_post_activation_proof_sha256",
        "historical_executor_release_id",
        "historical_superseded_endpoint_release_id",
        "historical_manager_sha256",
        "historical_manager_mutation_scope",
        "continuation_transactions",
        "resolution_evidence",
        "resolved_at",
        "formal_write_count",
        "authority",
    }
    descriptor = SUPERSEDED_TRANSACTION_RECOVERY_DESCRIPTORS.get(
        historical_prepare_sha256
    )
    if descriptor is None or set(value) != expected_keys:
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    if (
        value.get("schema_version") != DEPLOYMENT_RECOVERY_MARKER_V2_SCHEMA
        or value.get("outcome") != DEPLOYMENT_RECOVERY_MARKER_V2_OUTCOME
        or value.get("historical_prepare_receipt_sha256")
        != historical_prepare_sha256
        or value.get("historical_incomplete_postcommit_receipt_sha256")
        != descriptor["historical_incomplete_postcommit_receipt_sha256"]
        or value.get("successor_prepare_receipt_sha256")
        != descriptor["successor_prepare_receipt_sha256"]
        or value.get("successor_postcommit_receipt_sha256")
        != descriptor["successor_postcommit_receipt_sha256"]
        or value.get("successor_release_id") != descriptor["successor_release_id"]
        or value.get("successor_post_activation_proof_sha256")
        != descriptor["successor_post_activation_proof_sha256"]
        or value.get("historical_executor_release_id")
        != descriptor["historical_executor_release_id"]
        or value.get("historical_superseded_endpoint_release_id")
        != descriptor["historical_superseded_endpoint_release_id"]
        or value.get("historical_manager_sha256")
        != descriptor["historical_manager_sha256"]
        or value.get("historical_manager_mutation_scope")
        != descriptor["historical_manager_mutation_scope"]
        or value.get("continuation_transactions")
        != [dict(item) for item in descriptor.get("continuation_transactions", ())]
        or type(value.get("formal_write_count")) is not int
        or value.get("formal_write_count") != 0
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    resolution_evidence = value.get("resolution_evidence")
    if (
        not isinstance(resolution_evidence, Mapping)
        or set(resolution_evidence)
        != {
            "current_release_id",
            "current_link_target",
            "states",
            "dashboard_projection",
            "formal_write_count",
        }
        or resolution_evidence.get("current_release_id")
        != descriptor["resolution_head_release_id"]
        or resolution_evidence.get("current_link_target")
        != str(release_base / "releases" / descriptor["resolution_head_release_id"])
        or resolution_evidence.get("formal_write_count") != 0
        or not isinstance(resolution_evidence.get("states"), Mapping)
        or set(resolution_evidence["states"]) != set(RESUMABLE_SUBJECTS)
        or not isinstance(resolution_evidence.get("dashboard_projection"), Mapping)
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    try:
        head_config = json.loads(
            (
                release_base
                / "releases"
                / str(descriptor["resolution_head_release_id"])
                / "config.json"
            ).read_text("utf-8")
        )
        resolution_runtime_root = Path(
            str(head_config["runtime_root"])
        ).expanduser().resolve()
    except (OSError, UnicodeError, json.JSONDecodeError, KeyError) as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc
    for subject in RESUMABLE_SUBJECTS:
        snapshot = resolution_evidence["states"].get(subject)
        expected_state_path = str(
            resolution_runtime_root
            / "dispatch"
            / "state"
            / "production-canary"
            / f"{subject}.json"
        )
        if (
            not isinstance(snapshot, Mapping)
            or set(snapshot)
            != {"path", "sha256", "value", "activation_receipt", "terminal_index"}
            or not isinstance(snapshot.get("value"), Mapping)
            or snapshot.get("path") != expected_state_path
            or not isinstance(snapshot.get("sha256"), str)
            or SHA256_RE.fullmatch(str(snapshot.get("sha256") or "")) is None
            or sha256_bytes(canonical_bytes(snapshot["value"]))
            != snapshot["sha256"]
            or snapshot["value"].get("subject") != subject
            or snapshot["value"].get("release_id")
            != descriptor["resolution_head_release_id"]
            or snapshot["value"].get("formal_write_count") != 0
            or snapshot["value"].get("sol_enabled") is not False
            or not isinstance(snapshot["value"].get("authority"), Mapping)
            or SHA256_RE.fullmatch(
                str(snapshot["value"].get("terminal_index_sha256") or "")
            )
            is None
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        _verify_recovery_v2_dispatch_authority(
            snapshot["value"],
            runtime_root=resolution_runtime_root,
            purpose="dispatch-production-canary-state",
        )
        for member, purpose in (
            ("activation_receipt", "dispatch-production-canary-activation"),
            ("terminal_index", "dispatch-production-canary-terminal-index"),
        ):
            evidence = snapshot.get(member)
            if (
                not isinstance(evidence, Mapping)
                or set(evidence) != {"path", "sha256", "value"}
                or not isinstance(evidence.get("value"), Mapping)
                or sha256_bytes(canonical_bytes(evidence["value"]))
                != evidence.get("sha256")
                or evidence["value"].get("subject") != subject
                or evidence["value"].get("release_id")
                != descriptor["resolution_head_release_id"]
                or evidence["value"].get("activation_id")
                != snapshot["value"].get("activation_id")
                or evidence["value"].get("formal_write_count") != 0
                or evidence["value"].get("sol_enabled") is not False
                or not isinstance(evidence["value"].get("authority"), Mapping)
                or evidence["value"]["authority"].get("purpose") != purpose
                or evidence.get("path")
                != snapshot["value"].get(
                    "activation_receipt_path"
                    if member == "activation_receipt"
                    else "terminal_index_path"
                )
            ):
                raise ReleaseError("deployment_recovery_marker_v2_invalid")
            _verify_recovery_v2_dispatch_authority(
                evidence["value"],
                runtime_root=resolution_runtime_root,
                purpose=purpose,
            )
            _verify_recovery_v2_member_semantics(
                evidence["value"], member=member
            )
            state_sha_field = (
                "activation_receipt_sha256"
                if member == "activation_receipt"
                else "terminal_index_sha256"
            )
            if snapshot["value"].get(state_sha_field) != evidence["sha256"]:
                raise ReleaseError("deployment_recovery_marker_v2_invalid")
            root = (
                resolution_runtime_root
                / "dispatch"
                / "production-canary"
                / ("receipts" if member == "activation_receipt" else "terminal-indexes")
                / subject
            )
            path = Path(str(evidence["path"]))
            if root not in path.parents or path.name != f"{evidence['sha256']}.json":
                raise ReleaseError("deployment_recovery_marker_v2_invalid")
        _verify_recovery_v2_member_cross_bindings(
            snapshot["value"],
            activation=snapshot["activation_receipt"]["value"],
            terminal_index=snapshot["terminal_index"]["value"],
        )
    _verify_recovery_v2_dashboard_identity(
        resolution_evidence["dashboard_projection"],
        states=resolution_evidence["states"],
        runtime_root=resolution_runtime_root,
        release_id=str(descriptor["resolution_head_release_id"]),
        release_base=release_base,
        descriptor=descriptor,
    )
    try:
        _verify_deployment_authority(
            value,
            release_base=release_base,
            purpose=DEPLOYMENT_RECOVERY_MARKER_V2_PURPOSE,
        )
    except ReleaseError as exc:
        raise ReleaseError("deployment_recovery_marker_v2_invalid") from exc

    historical_time = _deployment_receipt_timestamp(
        historical_prepare, "prepared_at"
    )
    resolved_time = _deployment_receipt_timestamp(value, "resolved_at")
    if (
        historical_prepare.get("schema_version") != DEPLOYMENT_PREPARE_SCHEMA
        or historical_prepare.get("operation") != descriptor["historical_operation"]
        or historical_prepare.get("release_id")
        != descriptor["historical_release_id"]
        or historical_prepare.get("expected_current")
        != descriptor["historical_expected_current_release_id"]
        or historical_prepare.get("observed_current")
        != descriptor["historical_expected_current_release_id"]
        or historical_prepare.get("active_link") != descriptor["historical_active_link"]
        or historical_prepare.get("rollback_path")
        != {
            "release_dir": str(
                Path(str(descriptor["historical_active_link"])).parent
                / "releases" / descriptor["historical_expected_current_release_id"]
            ),
            "release_id": descriptor["historical_expected_current_release_id"],
            "service_restart_order": ["math", "cs408", "english", "dashboard"],
        }
        or sha256_bytes(canonical_bytes(historical_prepare.get("service_topology")))
        != descriptor["historical_service_topology_sha256"]
        or sha256_bytes(
            canonical_bytes(historical_prepare.get("previous_service_topology"))
        )
        != descriptor["historical_service_topology_sha256"]
        or sha256_bytes(
            canonical_bytes(historical_prepare.get("service_activation_policy"))
        )
        != descriptor["historical_service_activation_policy_sha256"]
        or type(historical_prepare.get("formal_write_count")) is not int
        or historical_prepare.get("formal_write_count") != 0
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    _verify_historical_manager_script(
        release_base=release_base,
        release_id=str(descriptor["historical_manager_release_id"]),
        expected_sha256=str(descriptor["historical_manager_sha256"]),
    )
    _verify_historical_executor_release(
        release_base=release_base,
        release_id=str(descriptor["historical_executor_release_id"]),
        expected_manifest_sha256=str(
            descriptor["historical_executor_release_manifest_sha256"]
        ),
    )

    incomplete_id = descriptor["historical_incomplete_postcommit_receipt_sha256"]
    historical_postcommit_ids = {
        receipt_sha256
        for receipt_sha256, candidate in receipts.items()
        if (
            candidate.get("schema_version") == DEPLOYMENT_POSTCOMMIT_SCHEMA
            and candidate.get("prepare_receipt_sha256")
            == historical_prepare_sha256
        )
    }
    if incomplete_id is None:
        if historical_postcommit_ids:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        incomplete_time = historical_time
    else:
        if historical_postcommit_ids != {str(incomplete_id)}:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        incomplete = receipts.get(str(incomplete_id))
        if incomplete is None:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        incomplete_time = _deployment_receipt_timestamp(incomplete, "completed_at")
        if (
            incomplete.get("schema_version") != DEPLOYMENT_POSTCOMMIT_SCHEMA
            or incomplete.get("prepare_receipt_sha256")
            != historical_prepare_sha256
            or incomplete.get("operation") != descriptor["historical_operation"]
            or incomplete.get("release_id") != descriptor["historical_release_id"]
            or incomplete.get("status")
            != descriptor["historical_incomplete_status"]
            or type(incomplete.get("formal_write_count")) is not int
            or incomplete.get("formal_write_count") != 0
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")

    successor_prepare_id = str(descriptor["successor_prepare_receipt_sha256"])
    successor_postcommit_id = str(descriptor["successor_postcommit_receipt_sha256"])
    successor_prepare = receipts.get(successor_prepare_id)
    successor_postcommit = receipts.get(successor_postcommit_id)
    if successor_prepare is None or successor_postcommit is None:
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    successor_prepare_time = _deployment_receipt_timestamp(
        successor_prepare, "prepared_at"
    )
    successor_postcommit_time = _deployment_receipt_timestamp(
        successor_postcommit, "completed_at"
    )
    successor_release_id = descriptor["successor_release_id"]
    if (
        successor_prepare.get("schema_version") != DEPLOYMENT_PREPARE_SCHEMA
        or successor_prepare.get("operation") != descriptor["successor_operation"]
        or successor_prepare.get("release_id") != successor_release_id
        or successor_prepare.get("expected_current")
        != descriptor["historical_superseded_endpoint_release_id"]
        or successor_prepare.get("observed_current")
        != descriptor["historical_superseded_endpoint_release_id"]
        or type(successor_prepare.get("formal_write_count")) is not int
        or successor_prepare.get("formal_write_count") != 0
        or successor_postcommit.get("schema_version")
        != DEPLOYMENT_POSTCOMMIT_SCHEMA
        or successor_postcommit.get("operation")
        != descriptor["successor_operation"]
        or successor_postcommit.get("release_id") != successor_release_id
        or successor_postcommit.get("status") != "committed"
        or successor_postcommit.get("prepare_receipt_sha256") != successor_prepare_id
        or successor_postcommit.get("previous_release_id")
        != descriptor["historical_superseded_endpoint_release_id"]
        or type(successor_postcommit.get("formal_write_count")) is not int
        or successor_postcommit.get("formal_write_count") != 0
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    proof = successor_postcommit.get("post_activation_verification")
    if (
        not isinstance(proof, Mapping)
        or proof.get("schema_version") != POST_ACTIVATION_SCHEMA
        or proof.get("release_id") != successor_release_id
        or proof.get("status") != descriptor["successor_post_activation_status"]
        or proof.get("current_path") != descriptor.get("successor_proof_current_path")
        or type(proof.get("formal_write_count")) is not int
        or proof.get("formal_write_count") != 0
        or sha256_bytes(canonical_bytes(proof))
        != descriptor["successor_post_activation_proof_sha256"]
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    proof_time = _deployment_receipt_timestamp(proof, "verified_at")
    if not (
        historical_time <= incomplete_time <= successor_prepare_time
        <= proof_time <= successor_postcommit_time <= resolved_time
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")
    previous_release_id = successor_release_id
    previous_time = successor_postcommit_time
    for continuation in descriptor.get("continuation_transactions", ()):
        continuation_prepare = receipts.get(
            str(continuation["prepare_receipt_sha256"])
        )
        continuation_postcommit = receipts.get(
            str(continuation["postcommit_receipt_sha256"])
        )
        if continuation_prepare is None or continuation_postcommit is None:
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        continuation_prepare_time = _deployment_receipt_timestamp(
            continuation_prepare, "prepared_at"
        )
        continuation_postcommit_time = _deployment_receipt_timestamp(
            continuation_postcommit, "completed_at"
        )
        continuation_proof = continuation_postcommit.get(
            "post_activation_verification"
        )
        if (
            continuation_prepare.get("schema_version")
            != DEPLOYMENT_PREPARE_SCHEMA
            or continuation_prepare.get("operation") != continuation["operation"]
            or continuation_prepare.get("release_id") != continuation["release_id"]
            or continuation_prepare.get("expected_current") != previous_release_id
            or continuation_prepare.get("observed_current") != previous_release_id
            or type(continuation_prepare.get("formal_write_count")) is not int
            or continuation_prepare.get("formal_write_count") != 0
            or continuation_postcommit.get("schema_version")
            != DEPLOYMENT_POSTCOMMIT_SCHEMA
            or continuation_postcommit.get("operation") != continuation["operation"]
            or continuation_postcommit.get("release_id")
            != continuation["release_id"]
            or continuation_postcommit.get("status") != "committed"
            or continuation_postcommit.get("prepare_receipt_sha256")
            != continuation["prepare_receipt_sha256"]
            or continuation_postcommit.get("previous_release_id")
            != previous_release_id
            or type(continuation_postcommit.get("formal_write_count")) is not int
            or continuation_postcommit.get("formal_write_count") != 0
            or not isinstance(continuation_proof, Mapping)
            or continuation_proof.get("schema_version")
            != THREE_SUBJECT_CANARY_POST_ACTIVATION_SCHEMA
            or continuation_proof.get("status")
            != "verified_production_canary_active"
            or continuation_proof.get("release_id") != continuation["release_id"]
            or continuation_proof.get("formal_write_count") != 0
            or continuation_proof.get("sol_enabled") is not False
            or sha256_bytes(canonical_bytes(continuation_proof))
            != continuation["post_activation_proof_sha256"]
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        service_release_ids = continuation_proof.get("service_release_ids")
        subject_controls = continuation_proof.get("subject_controls")
        if (
            not isinstance(service_release_ids, Mapping)
            or service_release_ids
            != {
                name: continuation["release_id"]
                for name in ("math", "cs408", "english", "dashboard")
            }
            or not isinstance(subject_controls, list)
            or {row.get("subject") for row in subject_controls if isinstance(row, Mapping)}
            != set(RESUMABLE_SUBJECTS)
            or any(
                not isinstance(row, Mapping)
                or row.get("enabled") is not True
                or row.get("running") is not True
                or row.get("draining") is not True
                for row in subject_controls
            )
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        continuation_proof_time = _deployment_receipt_timestamp(
            continuation_proof, "verified_at"
        )
        if not (
            previous_time <= continuation_prepare_time <= continuation_proof_time
            <= continuation_postcommit_time <= resolved_time
        ):
            raise ReleaseError("deployment_recovery_marker_v2_invalid")
        previous_release_id = str(continuation["release_id"])
        previous_time = continuation_postcommit_time
    if (
        descriptor.get("continuation_transactions")
        and previous_release_id != descriptor["resolution_head_release_id"]
    ):
        raise ReleaseError("deployment_recovery_marker_v2_invalid")


def _cs408_retirement_postcommit_closes_prepare(
    *,
    prepare: Mapping[str, Any],
    postcommit: Mapping[str, Any],
    receipts: Mapping[str, Mapping[str, Any]],
    release_base: Path,
    runner: CommandRunner | None = None,
) -> bool:
    authorization = prepare.get(
        "cs408_terminal_retirement_authorization_descriptor"
    )
    expected_authorization = {
        **CS408_TERMINAL_RETIREMENT_DESCRIPTOR,
        "authorization_descriptor_sha256": _authorization_descriptor_sha256(
            CS408_TERMINAL_RETIREMENT_DESCRIPTOR
        ),
    }
    if authorization != expected_authorization:
        return False
    retirement = postcommit.get("cs408_terminal_retirement_proof")
    binding = postcommit.get("cs408_writer_retirement_binding")
    accounting = postcommit.get(
        "cs408_terminal_retirement_mcp_accounting"
    )
    retirement_schema_status = (
        retirement.get("schema_version"),
        retirement.get("status"),
    ) if isinstance(retirement, Mapping) else (None, None)
    if (
        not isinstance(retirement, Mapping)
        or retirement_schema_status
        not in {
            (
                "study-intake-cs408-terminal-batch-retirement-result-v1",
                "retired",
            ),
            (
                "study-intake-cs408-terminal-batch-retirement-reopen-result-v1",
                "reopened",
            ),
        }
        or retirement.get("authorization_descriptor_sha256")
        != expected_authorization["authorization_descriptor_sha256"]
        or retirement.get("terminal_receipt_sha256")
        != expected_authorization["terminal_receipt_sha256"]
        or retirement.get("authority_snapshot_mcp_tool_call_count")
        != (2 if retirement.get("status") == "retired" else 0)
        or (
            retirement.get("status") == "reopened"
            and retirement.get("reopen_read_only") is not True
        )
        or retirement.get("model_mcp_tool_call_count") != 0
        or retirement.get("formal_write_count") != 0
        or not isinstance(accounting, Mapping)
        or accounting.get("schema_version")
        != "study-intake-cs408-terminal-retirement-mcp-accounting-v1"
        or accounting.get(
            "locked_preflight_authority_snapshot_mcp_tool_call_count"
        )
        != 3
        or accounting.get(
            "retirement_authority_snapshot_mcp_tool_call_count"
        )
        != 2
        or accounting.get("model_mcp_tool_call_count") != 0
        or accounting.get("model_call_count") != 0
        or accounting.get("provider_request_count") != 0
        or accounting.get("formal_write_count") != 0
    ):
        return False
    status = postcommit.get("status")
    if status == "committed":
        if retirement.get("status") != "retired":
            return False
        if accounting != _cs408_retirement_apply_mcp_accounting(
            retirement_completed=True,
            english_recovery_completed=True,
            arm_preflight_completed=True,
        ):
            return False
        activation_receipt_sha256 = postcommit.get(
            "canary_activation_receipt_sha256"
        )
        activation_receipt = (
            receipts.get(activation_receipt_sha256)
            if isinstance(activation_receipt_sha256, str)
            else None
        )
        canary_arm_proof = postcommit.get("canary_arm_proof")
        if (
            not isinstance(activation_receipt, Mapping)
            or not isinstance(binding, Mapping)
            or not isinstance(canary_arm_proof, Mapping)
            or activation_receipt.get("schema_version")
            != THREE_SUBJECT_CANARY_RECEIPT_V4_SCHEMA
            or activation_receipt.get("cs408_writer_retirement_binding")
            != binding
            or activation_receipt.get("subject_batch_recovery_binding")
            != postcommit.get("subject_batch_recovery_binding")
            or canary_arm_proof.get("cs408_writer_retirement_binding")
            != binding
            or sha256_bytes(canonical_bytes(canary_arm_proof))
            != activation_receipt.get("pre_activation_verification_sha256")
        ):
            return False
        try:
            _validate_three_subject_canary_activation_receipt(
                activation_receipt, release_base=release_base
            )
        except ReleaseError:
            return False
        receipt_path_raw = binding.get("retirement_receipt_path")
        if (
            not isinstance(receipt_path_raw, str)
            or retirement.get("retirement_receipt_path") != receipt_path_raw
            or binding.get("retirement_receipt_path_sha256")
            != sha256_bytes(receipt_path_raw.encode("utf-8"))
            or binding.get("retirement_receipt_sha256")
            != retirement.get("retirement_receipt_sha256")
            or binding.get("retirement_rollback_token")
            != retirement.get("rollback_token")
            or binding.get("writer_postimage_sha256")
            != retirement.get("writer_postimage_sha256")
            or binding.get("postimage_verification_sha256")
            != retirement.get("postimage_verification_sha256")
        ):
            return False
        receipt_path = Path(receipt_path_raw)
        try:
            if (
                receipt_path.is_symlink()
                or not receipt_path.is_file()
                or receipt_path.name
                != f"{retirement['retirement_receipt_sha256']}.json"
                or sha256_file(receipt_path)
                != retirement["retirement_receipt_sha256"]
            ):
                return False
        except OSError:
            return False
        target = release_base / "releases" / str(prepare.get("release_id") or "")
        try:
            if target.is_symlink() or not target.is_dir():
                return False
            verified_target = verify_release(target)
            if verified_target.get("release_id") != prepare.get("release_id"):
                return False
            reopened = (
                _reopen_cs408_terminal_batch_retirement_after_uncertain_attempt(
                    target=target,
                    runner=runner or _subprocess_command_runner,
                    retirement_receipt_path=receipt_path,
                )
            )
        except (OSError, ReleaseError):
            return False
        for key in (
            "authorization_descriptor_sha256",
            "retirement_receipt_sha256",
            "retirement_receipt_path",
            "rollback_token",
            "writer_postimage_sha256",
            "postimage_verification_sha256",
        ):
            if reopened.get(key) != retirement.get(key):
                return False
        return True
    if status == "rolled_back":
        early_staged_activation_failure = (
            postcommit.get("error_code")
            == "english_subject_batch_recovery_staged_activation_failed"
            and postcommit.get(
                "subject_batch_recovery_staged_activation_proof"
            )
            is None
            and postcommit.get("subject_batch_recovery_finalization_proof")
            is None
            and postcommit.get("subject_batch_recovery_arm_proof") is None
        )
        valid_accounting = accounting in (
            # A failure after English recovery but before all-subject arm has
            # an exact total of seven. A later health/service failure has ten.
            _cs408_retirement_apply_mcp_accounting(
                retirement_completed=True,
                english_recovery_completed=True,
                arm_preflight_completed=False,
            ),
            _cs408_retirement_apply_mcp_accounting(
                retirement_completed=True,
                english_recovery_completed=True,
                arm_preflight_completed=True,
            ),
        )
        rollback = postcommit.get(
            "cs408_terminal_retirement_rollback_proof"
        )
        recovery = postcommit.get("subject_batch_recovery_proof")
        recovery_rollback = postcommit.get(
            "subject_batch_recovery_rollback_proof"
        )
        english_expectations = prepare.get("subject_recovery_expectations")
        if (
            not valid_accounting
            or postcommit.get("rollback_errors") != []
            or not isinstance(english_expectations, Mapping)
            or set(english_expectations) != {"english"}
            or SHA256_RE.fullmatch(
                str(english_expectations.get("english") or "")
            )
            is None
            or not isinstance(recovery, Mapping)
            or recovery.get("schema_version")
            != "study-intake-subject-batch-recovery-result-v1"
            or recovery.get("subject") != "english"
            or recovery.get("status") != "recovered"
            or recovery.get("original_preclaim_failure_receipt_sha256")
            != english_expectations["english"]
            or recovery.get("authority_snapshot_mcp_tool_call_count") != 2
            or recovery.get("model_mcp_tool_call_count") != 0
            or recovery.get("mcp_tool_call_count") != 2
            or recovery.get("model_call_count") != 0
            or recovery.get("provider_request_count") != 0
            or recovery.get("formal_write_count") != 0
            or recovery.get("sol_enabled") is not False
            or not isinstance(recovery_rollback, Mapping)
            or recovery_rollback.get("schema_version")
            != "study-intake-subject-batch-recovery-rollback-result-v1"
            or recovery_rollback.get("subject") != "english"
            or recovery_rollback.get("status") != "rolled_back"
            or recovery_rollback.get("recovery_receipt_sha256")
            != recovery.get("recovery_receipt_sha256")
            or recovery_rollback.get("rollback_token")
            != recovery.get("rollback_token")
            or recovery_rollback.get("preserved_queue_entry_sha256")
            != recovery.get("preserved_queue_entry_sha256")
            or recovery_rollback.get("target_queue_withdrawn") is not True
            or not isinstance(
                recovery_rollback.get("removed_mutable_pointer_count"), int
            )
            or isinstance(
                recovery_rollback.get("removed_mutable_pointer_count"), bool
            )
            or recovery_rollback.get("removed_mutable_pointer_count") < 0
            or (
                recovery_rollback.get("removed_mutable_pointer_count") == 0
                and not early_staged_activation_failure
            )
            or SHA256_RE.fullmatch(
                str(recovery_rollback.get("writer_state_restored_sha256") or "")
            )
            is None
            or SHA256_RE.fullmatch(
                str(recovery_rollback.get("batch_pointer_restored_sha256") or "")
            )
            is None
            or SHA256_RE.fullmatch(
                str(recovery_rollback.get("canary_state_restored_sha256") or "")
            )
            is None
            or recovery_rollback.get("authority_snapshot_count") != 0
            or recovery_rollback.get(
                "authority_snapshot_mcp_tool_call_count"
            )
            != 0
            or recovery_rollback.get("model_mcp_tool_call_count") != 0
            or recovery_rollback.get("mcp_tool_call_count") != 0
            or recovery_rollback.get("model_call_count") != 0
            or recovery_rollback.get("provider_request_count") != 0
            or recovery_rollback.get("formal_write_count") != 0
            or recovery_rollback.get("sol_enabled") is not False
            or not isinstance(rollback, Mapping)
            or rollback.get("schema_version")
            != "study-intake-cs408-terminal-batch-retirement-rollback-result-v1"
            or rollback.get("subject") != "cs408"
            or rollback.get("status") != "rolled_back"
            or rollback.get("retirement_receipt_sha256")
            != retirement.get("retirement_receipt_sha256")
            or rollback.get("rollback_token")
            != retirement.get("rollback_token")
            or rollback.get("writer_state_restored_sha256")
            != CS408_TERMINAL_RETIREMENT_DESCRIPTOR[
                "writer_preimage_sha256"
            ]
            or rollback.get("retirement_pointer_withdrawn") is not True
            or rollback.get("retirement_intent_withdrawn") is not True
            or rollback.get("old_batch_sha256")
            != CS408_TERMINAL_RETIREMENT_DESCRIPTOR["batch_sha256"]
            or rollback.get("batch_pointer_unchanged_sha256")
            != CS408_TERMINAL_RETIREMENT_DESCRIPTOR[
                "batch_pointer_sha256"
            ]
            or rollback.get("batch_snapshot_unchanged_sha256")
            != CS408_TERMINAL_RETIREMENT_DESCRIPTOR["snapshot_sha256"]
            or rollback.get("terminal_receipt_unchanged_sha256")
            != CS408_TERMINAL_RETIREMENT_DESCRIPTOR[
                "terminal_receipt_sha256"
            ]
            or SHA256_RE.fullmatch(
                str(
                    rollback.get("rollback_postimage_verification_sha256")
                    or ""
                )
            )
            is None
            or rollback.get("rollback_receipt_reopened") is not True
            or rollback.get("authority_snapshot_count") != 0
            or rollback.get("authority_snapshot_mcp_tool_call_count") != 0
            or rollback.get("model_mcp_tool_call_count") != 0
            or rollback.get("mcp_tool_call_count") != 0
            or rollback.get("model_call_count") != 0
            or rollback.get("provider_request_count") != 0
            or rollback.get("formal_write_count") != 0
            or rollback.get("sol_enabled") is not False
        ):
            return False
        target = release_base / "releases" / str(prepare.get("release_id") or "")
        recovery_path = recovery.get("recovery_receipt_path")
        recovery_digest = recovery.get("recovery_receipt_sha256")
        english_rollback_path = recovery_rollback.get("rollback_receipt_path")
        english_rollback_digest = recovery_rollback.get(
            "rollback_receipt_sha256"
        )
        retirement_path = retirement.get("retirement_receipt_path")
        retirement_digest = retirement.get("retirement_receipt_sha256")
        rollback_path = rollback.get("rollback_receipt_path")
        rollback_digest = rollback.get("rollback_receipt_sha256")
        restore_proofs = postcommit.get(
            "previous_canary_state_restore_proofs"
        )
        english_restore = (
            restore_proofs.get("english")
            if isinstance(restore_proofs, Mapping)
            else None
        )
        if not isinstance(english_restore, Mapping):
            return False
        restore_core = {
            key: english_restore.get(key)
            for key in (
                "path",
                "snapshot_state",
                "snapshot_sha256",
                "restored_state",
                "restored_sha256",
            )
        }
        deployment_canary_state_sha256 = english_restore.get(
            "restored_sha256"
        )
        if (
            set(english_restore) != {*restore_core, "proof_sha256"}
            or english_restore.get("snapshot_state") != "present"
            or english_restore.get("restored_state") != "present"
            or english_restore.get("snapshot_sha256")
            != deployment_canary_state_sha256
            or SHA256_RE.fullmatch(
                str(deployment_canary_state_sha256 or "")
            )
            is None
            or english_restore.get("proof_sha256")
            != sha256_bytes(canonical_bytes(restore_core))
        ):
            return False
        try:
            verified_target = verify_release(target)
            if verified_target.get("release_id") != prepare.get("release_id"):
                return False
            ca_pairs = (
                (recovery_path, recovery_digest),
                (english_rollback_path, english_rollback_digest),
                (retirement_path, retirement_digest),
                (rollback_path, rollback_digest),
            )
            for path_raw, digest in ca_pairs:
                candidate = Path(str(path_raw))
                if (
                    SHA256_RE.fullmatch(str(digest or "")) is None
                    or candidate.is_symlink()
                    or not candidate.is_file()
                    or candidate.name != f"{digest}.json"
                    or sha256_file(candidate) != digest
                ):
                    return False
            english_reopened = _reopen_subject_batch_recovery_rollback(
                target=target,
                recovery=recovery,
                rollback=recovery_rollback,
                runner=runner or _subprocess_command_runner,
                deployment_canary_state_sha256=str(
                    deployment_canary_state_sha256
                ),
                expected_finalization_rollback_proof_count=(
                    0 if early_staged_activation_failure else 1
                ),
                script_root=SOURCE_ROOT,
            )
            cs408_reopened = (
                _reopen_cs408_terminal_batch_retirement_rollback(
                    target=target,
                    retirement=retirement,
                    rollback=rollback,
                    runner=runner or _subprocess_command_runner,
                )
            )
        except (OSError, ReleaseError):
            return False
        return (
            english_reopened.get("canary_state_restored_sha256")
            == recovery_rollback.get("canary_state_restored_sha256")
            and english_reopened.get(
                "deployment_canary_state_postimage_sha256"
            )
            == deployment_canary_state_sha256
            and english_reopened.get(
                "finalization_rollback_proof_count"
            )
            == (0 if early_staged_activation_failure else 1)
            and english_reopened.get("target_queue_withdrawn") is True
            and english_reopened.get("mutable_recovery_intents_withdrawn")
            is True
            and cs408_reopened.get("rollback_postimage_verification_sha256")
            == rollback.get("rollback_postimage_verification_sha256")
            and cs408_reopened.get("rollback_receipt_reopened") is True
        )
    return False


def _english_review_repair_postcommit_closes_prepare(
    *,
    prepare: Mapping[str, Any],
    postcommit: Mapping[str, Any],
    receipts: Mapping[str, Mapping[str, Any]],
    release_base: Path,
    runner: CommandRunner | None = None,
) -> bool:
    authorization = prepare.get(
        "english_preserved_review_repair_authorization"
    )
    if (
        not isinstance(authorization, Mapping)
        or set(authorization)
        != {
            "authorization_descriptor_sha256",
            "preview_sha256",
            "source_gate_preimage_sha256",
        }
        or authorization.get("authorization_descriptor_sha256")
        != ENGLISH_PRESERVED_REVIEW_REPAIR_DESCRIPTOR_SHA256
        or SHA256_RE.fullmatch(
            str(authorization.get("preview_sha256") or "")
        )
        is None
        or authorization.get("source_gate_preimage_sha256")
        != ENGLISH_PRESERVED_REVIEW_REPAIR_SOURCE_GATE_SHA256
        or postcommit.get("schema_version")
        != DEPLOYMENT_POSTCOMMIT_SCHEMA
        or postcommit.get("operation") != prepare.get("operation")
        or postcommit.get("release_id") != prepare.get("release_id")
        or postcommit.get("formal_write_count") != 0
    ):
        return False
    if postcommit.get("status") == "committed":
        repair = postcommit.get("english_preserved_review_repair_proof")
        reopened = postcommit.get(
            "english_preserved_review_repair_reopen_proof"
        )
        staged = postcommit.get(
            "english_preserved_review_repair_staged_gate_proof"
        )
        binding = postcommit.get(
            "english_preserved_review_repair_binding"
        )
        arm = postcommit.get("canary_arm_proof")
        activation_sha256 = postcommit.get(
            "canary_activation_receipt_sha256"
        )
        activation = (
            receipts.get(activation_sha256)
            if isinstance(activation_sha256, str)
            else None
        )
        if (
            not all(
                isinstance(row, Mapping)
                for row in (repair, reopened, staged, binding, arm, activation)
            )
            or activation.get("schema_version")
            != THREE_SUBJECT_CANARY_RECEIPT_V5_SCHEMA
            or activation.get(
                "english_preserved_review_repair_binding"
            )
            != binding
            or arm.get("english_preserved_review_repair_binding")
            != binding
            or binding.get("source_preview_sha256")
            != authorization.get("preview_sha256")
            or binding.get("staged_gate_proof_sha256")
            != sha256_bytes(canonical_bytes(staged))
            or binding.get("reopen_proof_sha256")
            != sha256_bytes(canonical_bytes(reopened))
            or binding.get("arm_proof_sha256")
            != sha256_bytes(
                canonical_bytes(
                    {
                        key: copy.deepcopy(value)
                        for key, value in arm.items()
                        if key
                        != "english_preserved_review_repair_binding"
                    }
                )
            )
            or sha256_bytes(canonical_bytes(arm))
            != activation.get("pre_activation_verification_sha256")
            or postcommit.get(
                "english_preserved_review_repair_rollback_proof"
            )
            is not None
            or postcommit.get(
                "english_preserved_review_repair_rollback_reopen_proof"
            )
            is not None
        ):
            return False
        try:
            _validate_three_subject_canary_activation_receipt(
                activation, release_base=release_base
            )
            _validate_english_preserved_review_repair_canary_binding(
                binding,
                release_id=str(prepare["release_id"]),
                release_base=release_base,
            )
            repair = _validate_english_preserved_review_repair_result(
                repair,
                release_id=str(binding["target_release_id"]),
                activation_id=str(binding["target_activation_id"]),
                target_generation=str(binding["target_generation"]),
                target_subject_authority_fingerprint=str(
                    binding["target_subject_authority_fingerprint"]
                ),
                target_producer_authority_fingerprint=str(
                    binding["target_producer_authority_fingerprint"]
                ),
                staged_target_canary_state_sha256=str(
                    binding["staged_target_canary_state_sha256"]
                ),
            )
            _validate_english_preserved_review_repair_reopen(
                reopened, repair=repair
            )
            target = (
                release_base / "releases" / str(prepare["release_id"])
            )
            verified = verify_release(target)
            if verified.get("release_id") != prepare.get("release_id"):
                return False
            live_reopen = _validate_english_preserved_review_repair_reopen(
                _reopen_english_preserved_review_repair(
                    target=target,
                    runner=runner or _subprocess_command_runner,
                    repair_receipt_sha256=str(
                        repair["repair_receipt_sha256"]
                    ),
                ),
                repair=repair,
            )
        except (OSError, ReleaseError):
            return False
        return sha256_bytes(canonical_bytes(live_reopen)) == binding.get(
            "reopen_proof_sha256"
        )
    if postcommit.get("status") == "rolled_back":
        # The exact rollback branch is validated by the immutable runtime
        # rollback/reopen receipts.  A pre-mutation failure is accepted only
        # when no correction proof exists and the deployment restored the
        # byte-locked English source gate snapshot.
        repair = postcommit.get("english_preserved_review_repair_proof")
        rollback = postcommit.get(
            "english_preserved_review_repair_rollback_proof"
        )
        rollback_reopen = postcommit.get(
            "english_preserved_review_repair_rollback_reopen_proof"
        )
        restores = postcommit.get("previous_canary_state_restore_proofs")
        english_restore = (
            restores.get("english")
            if isinstance(restores, Mapping)
            else None
        )
        if (
            postcommit.get("rollback_errors") != []
            or not isinstance(english_restore, Mapping)
            or english_restore.get("restored_sha256")
            != ENGLISH_PRESERVED_REVIEW_REPAIR_SOURCE_GATE_SHA256
        ):
            return False
        if repair is None:
            uncertain = postcommit.get(
                "english_preserved_review_repair_reopen_proof"
            )
            return bool(
                rollback is None
                and rollback_reopen is None
                and (
                    uncertain is None
                    or (
                        isinstance(uncertain, Mapping)
                        and uncertain.get("schema_version")
                        == "study-intake-english-preserved-review-repair-uncertain-reopen-v1"
                        and uncertain.get("status")
                        in {
                            "not_prepared_no_mutation",
                            "rolled_back_same_process",
                        }
                        and uncertain.get("mutation_observed") is False
                        and (
                            uncertain.get("status")
                            == "not_prepared_no_mutation"
                            or uncertain.get("rollback_complete") is True
                        )
                        and uncertain.get("formal_write_count") == 0
                    )
                )
            )
        if not isinstance(rollback, Mapping) or not isinstance(
            rollback_reopen, Mapping
        ):
            return False
        try:
            target = (
                release_base / "releases" / str(prepare["release_id"])
            )
            live = _reopen_english_preserved_review_repair_rollback(
                target=target,
                repair=repair,
                rollback=rollback,
                runner=runner or _subprocess_command_runner,
            )
        except (OSError, ReleaseError):
            return False
        return live == rollback_reopen
    return False


def _exact_20260814_6043_fenced_preserved_closes_prepare(
    *,
    prepare_receipt_sha256: str,
    prepare: Mapping[str, Any],
    postcommit: Mapping[str, Any],
    receipts: Mapping[str, Mapping[str, Any]],
    release_base: Path,
) -> bool:
    """Close only the audited 84ab fenced postimage without live reads."""

    descriptor = EXACT_20260814_6043_FENCED_PRESERVED_CLOSURE
    fenced = receipts.get(str(descriptor["fenced_receipt_sha256"]))
    proof = postcommit.get("fenced_preserved_closure")
    if (
        prepare_receipt_sha256 != descriptor["prepare_receipt_sha256"]
        or prepare.get("release_id") != descriptor["target_release_id"]
        or postcommit.get("schema_version") != DEPLOYMENT_POSTCOMMIT_SCHEMA
        or postcommit.get("operation") != "activate"
        or postcommit.get("status") != "closed_fenced_preserved_review"
        or postcommit.get("release_id") != descriptor["target_release_id"]
        or postcommit.get("prepare_receipt_sha256")
        != descriptor["prepare_receipt_sha256"]
        or postcommit.get("failed_postcommit_receipt_sha256")
        != descriptor["failed_postcommit_receipt_sha256"]
        or postcommit.get("fenced_receipt_sha256")
        != descriptor["fenced_receipt_sha256"]
        or postcommit.get("repair_receipt_sha256")
        != descriptor["repair_receipt_sha256"]
        or postcommit.get("formal_write_count") != 0
        or not isinstance(fenced, Mapping)
        or not isinstance(proof, Mapping)
        or proof.get("schema_version")
        != "study-intake-exact-fenced-preserved-closure-v1"
        or proof.get("descriptor_sha256")
        != sha256_bytes(canonical_bytes(descriptor))
        or proof.get("fenced_receipt_sha256")
        != descriptor["fenced_receipt_sha256"]
        or proof.get("repair_receipt_sha256")
        != descriptor["repair_receipt_sha256"]
        or any(
            proof.get(key) != 0
            for key in (
                "model_call_count",
                "provider_request_count",
                "mcp_tool_call_count",
                "formal_write_count",
            )
        )
        or fenced.get("schema_version")
        != "study-intake-exact-forward-recovery-fenced-v1"
        or fenced.get("status") != "fence_incomplete"
        or fenced.get("prepare_receipt_sha256")
        != descriptor["prepare_receipt_sha256"]
        or fenced.get("failed_postcommit_receipt_sha256")
        != descriptor["failed_postcommit_receipt_sha256"]
        or fenced.get("target_release_id") != descriptor["target_release_id"]
        or fenced.get("formal_write_count") != 0
        or fenced.get("port_8767_owner_pids") != []
    ):
        return False
    try:
        _verify_deployment_authority(
            fenced,
            release_base=release_base,
            purpose="exact-20260814-6043-forward-fenced",
        )
        _verify_deployment_authority(
            proof,
            release_base=release_base,
            purpose="exact-20260814-6043-fenced-preserved-closure",
        )
        repair_path = (
            release_base
            / "dispatch/production-canary/english-preserved-review-repairs/receipts"
            / "sha256"
            / str(descriptor["repair_receipt_sha256"])[:2]
            / f"{descriptor['repair_receipt_sha256']}.json"
        )
        if (
            repair_path.is_symlink()
            or not repair_path.is_file()
            or sha256_file(repair_path) != descriptor["repair_receipt_sha256"]
        ):
            return False
        repair = _bounded_manifest(repair_path)
        if (
            repair.get("schema_version")
            != "study-intake-english-preserved-review-repair-receipt-v1"
            or repair.get("target_release_id") != descriptor["target_release_id"]
            or repair.get("report_available") is not True
            or repair.get("report_disposition") != "needs_sol_review"
            or repair.get("sol_review_status") != "pending"
            or repair.get("formal_write_eligible") is not False
            or repair.get("formal_write_count") != 0
            or repair.get("new_task_count") != 0
            or repair.get("new_queue_count") != 0
            or repair.get("capture_replay_count") != 0
        ):
            return False
    except (OSError, ReleaseError):
        return False
    return True


