def _external_content_json(
    path: Path, *, maximum_bytes: int, error_code: str
) -> tuple[dict[str, Any], str]:
    candidate = path.expanduser().absolute()
    try:
        node = candidate.lstat()
        size = node.st_size
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if (
        candidate.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or node.st_uid != os.getuid()
        or stat.S_IMODE(node.st_mode) & 0o022
        or size <= 0
        or size > maximum_bytes
    ):
        raise ReleaseError(error_code)
    digest = sha256_file(candidate)
    if candidate.name != f"{digest}.json":
        raise ReleaseError(error_code)
    try:
        value = json.loads(candidate.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError(error_code) from exc
    if not isinstance(value, dict):
        raise ReleaseError(error_code)
    return value, digest


def _default_producer_authority_resolver(
    *, target: Path, release_id: str, subject: str
) -> Mapping[str, Any]:
    """Read one immutable producer binding without opening a consumer lane."""

    script = (
        "import json,sys; from pathlib import Path; "
        "sys.path.insert(0,sys.argv[1]); "
        "import preprocessor_core as p; "
        "from core_dispatch_bridge import producer_authority_binding; "
        "cfg=p.load_config(Path(sys.argv[2])); "
        "print(json.dumps(producer_authority_binding(cfg,sys.argv[3],sys.argv[4]),"
        "ensure_ascii=False,sort_keys=True))"
    )
    environment = dict(os.environ)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    environment.pop("STUDY_PREPROCESSOR_RUN_REAL_RUNTIME_TESTS", None)
    try:
        completed = subprocess.run(
            [
                sys.executable,
                "-B",
                "-c",
                script,
                str(target / "lib"),
                str(target / "config.json"),
                subject,
                release_id,
            ],
            cwd=target,
            env=environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
            check=False,
        )
    except (OSError, subprocess.SubprocessError) as exc:
        raise ReleaseError(
            f"producer_authority_probe_failed:{subject}"
        ) from exc
    if completed.returncode != 0 or len(completed.stdout) > 128 * 1024:
        raise ReleaseError(f"producer_authority_probe_failed:{subject}")
    try:
        value = json.loads(completed.stdout.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError(
            f"producer_authority_probe_invalid:{subject}"
        ) from exc
    if not isinstance(value, Mapping):
        raise ReleaseError(f"producer_authority_probe_invalid:{subject}")
    return value


def _validate_producer_authority(
    value: Mapping[str, Any], *, release_id: str, subject: str
) -> dict[str, Any]:
    expected_keys = {
        "schema_version",
        "subject",
        "release_id",
        "loaded_core_sha256",
        "processing_contract_sha256",
        "model",
        "reasoning_effort",
        "formal_write_count",
        "authority_fingerprint",
    }
    core = {
        key: copy.deepcopy(value[key])
        for key in expected_keys - {"authority_fingerprint"}
        if key in value
    }
    if (
        set(value) != expected_keys
        or value.get("schema_version") != "study-intake-producer-authority-v1"
        or value.get("subject") != subject
        or value.get("release_id") != release_id
        or value.get("model") != REQUIRED_MODEL_CONTRACT["model"]
        or value.get("reasoning_effort")
        != REQUIRED_MODEL_CONTRACT["reasoning_effort"]
        or value.get("formal_write_count") != 0
        or SHA256_RE.fullmatch(str(value.get("loaded_core_sha256") or ""))
        is None
        or SHA256_RE.fullmatch(
            str(value.get("processing_contract_sha256") or "")
        )
        is None
        or value.get("authority_fingerprint")
        != sha256_bytes(
            json.dumps(
                core,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        )
    ):
        raise ReleaseError(f"producer_authority_invalid:{subject}")
    return copy.deepcopy(dict(value))


def prepare_canary_manifest(
    *,
    release_base: Path,
    release_id: str,
    output_dir: Path,
    authority_resolver: Callable[..., Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    """Create the v2 canary input from a strictly target-capable release."""

    release_base = _safe_base(release_base, label="release_base")
    if SHA256_RE.fullmatch(release_id) is None:
        raise ReleaseError("release_id_invalid")
    target = (release_base / "releases" / release_id).resolve()
    verified = verify_release(target)
    _three_subject_canary_capability(target, verified)
    resolver = authority_resolver or _default_producer_authority_resolver
    slots: dict[str, dict[str, Any]] = {}
    authorities: dict[str, dict[str, Any]] = {}
    for subject in RESUMABLE_SUBJECTS:
        authority = _validate_producer_authority(
            resolver(target=target, release_id=release_id, subject=subject),
            release_id=release_id,
            subject=subject,
        )
        authorities[subject] = authority
        slots[subject] = {
            "subject": subject,
            "producer_authority_fingerprint": authority[
                "authority_fingerprint"
            ],
            "state": "planned",
            "capture_id": None,
            "completion_receipt_sha256": None,
        }
    manifest = {
        "schema_version": THREE_SUBJECT_CANARY_ACTIVATION_SCHEMA,
        "status": "ready",
        "release_id": release_id,
        "release_manifest_sha256": sha256_file(target / "release.json"),
        "post_activation_only": True,
        "historical_backlog_drained": True,
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "slots": slots,
        "model_call_count": 0,
        "provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
        "production_accepted": False,
    }
    raw = canonical_bytes(manifest)
    digest = sha256_bytes(raw)
    destination_root = output_dir.expanduser().absolute()
    if destination_root in {Path("/"), Path.home(), SOURCE_ROOT.resolve()}:
        raise ReleaseError("canary_manifest_output_dir_invalid")
    if destination_root.is_symlink():
        raise ReleaseError("canary_manifest_output_dir_invalid")
    destination_root.mkdir(parents=True, exist_ok=True)
    if not destination_root.is_dir():
        raise ReleaseError("canary_manifest_output_dir_invalid")
    destination = destination_root / f"{digest}.json"
    if destination.exists():
        if (
            destination.is_symlink()
            or not destination.is_file()
            or destination.read_bytes() != raw
            or stat.S_IMODE(destination.stat().st_mode) & 0o022
        ):
            raise ReleaseError("canary_manifest_content_address_conflict")
    else:
        atomic_json(destination, manifest, mode=SEALED_GENERATED_MODE)
    checked = _validate_three_subject_canary_manifest(
        destination,
        release_id=release_id,
        target=target,
    )
    return {
        "schema_version": THREE_SUBJECT_CANARY_ACTIVATION_SCHEMA,
        "status": "prepared",
        "release_id": release_id,
        "path": str(destination),
        "canary_manifest_sha256": checked["canary_manifest_sha256"],
        "producer_authority_fingerprints": {
            subject: authorities[subject]["authority_fingerprint"]
            for subject in RESUMABLE_SUBJECTS
        },
        "model_call_count": 0,
        "provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }


def _validate_three_subject_canary_manifest(
    path: Path,
    *,
    release_id: str,
    target: Path,
) -> dict[str, Any]:
    value, digest = _external_content_json(
        path,
        maximum_bytes=8 * 1024 * 1024,
        error_code="three_subject_canary_manifest_invalid",
    )
    if (
        set(value)
        != {
            "schema_version",
            "status",
            "release_id",
            "release_manifest_sha256",
            "post_activation_only",
            "historical_backlog_drained",
            "initial_canary_inflight_limit",
            "continuous_concurrency_limit",
            "requested_service_tier",
            "fast_mode_requested",
            "fast_mode_effective",
            "slots",
            "model_call_count",
            "provider_request_count",
            "formal_write_count",
            "sol_enabled",
            "production_accepted",
        }
        or value.get("schema_version") != THREE_SUBJECT_CANARY_ACTIVATION_SCHEMA
        or value.get("status") != "ready"
        or value.get("release_id") != release_id
        or value.get("release_manifest_sha256")
        != sha256_file(target / "release.json")
        or value.get("post_activation_only") is not True
        or value.get("historical_backlog_drained") is not True
        or value.get("initial_canary_inflight_limit")
        != INITIAL_CANARY_INFLIGHT_LIMIT
        or value.get("continuous_concurrency_limit")
        != CONTINUOUS_CONCURRENCY_LIMIT
        or value.get("requested_service_tier") is not REQUESTED_SERVICE_TIER
        or value.get("fast_mode_requested") is not FAST_MODE_REQUESTED
        or value.get("fast_mode_effective") != FAST_MODE_EFFECTIVE
        or value.get("model_call_count") != 0
        or value.get("provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
        or value.get("production_accepted") is not False
    ):
        raise ReleaseError("three_subject_canary_manifest_invalid")
    slots = value.get("slots")
    if not isinstance(slots, Mapping) or set(slots) != set(RESUMABLE_SUBJECTS):
        raise ReleaseError("three_subject_canary_manifest_invalid")
    for subject in RESUMABLE_SUBJECTS:
        row = slots.get(subject)
        if (
            not isinstance(row, Mapping)
            or set(row)
            != {
                "subject",
                "producer_authority_fingerprint",
                "state",
                "capture_id",
                "completion_receipt_sha256",
            }
        ):
            raise ReleaseError("three_subject_canary_manifest_invalid")
    context = {
        key: copy.deepcopy(value[key])
        for key in (
            "schema_version",
            "release_id",
            "release_manifest_sha256",
            "post_activation_only",
            "historical_backlog_drained",
            "initial_canary_inflight_limit",
            "continuous_concurrency_limit",
            "requested_service_tier",
            "fast_mode_requested",
            "fast_mode_effective",
            "slots",
            "model_call_count",
            "provider_request_count",
            "formal_write_count",
            "sol_enabled",
            "production_accepted",
        )
    }
    context["canary_manifest_sha256"] = digest
    return _validate_canary_context(context, release_id=release_id)


def activate_canary_release(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    canary_manifest: Path,
    apply: bool = False,
    expected_current: str | None = None,
    drain_receipt: Path | None = None,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    codex_config_path: Path = DEFAULT_CODEX_CONFIG,
    morning_pointer_path: Path = DEFAULT_MORNING_POINTER,
    plugin_cache_root: Path = DEFAULT_PLUGIN_CACHE_ROOT,
    command_runner: CommandRunner | None = None,
    lock_timeout_seconds: float = 3.0,
    process_inspector: Callable[[str | None, str | None], Mapping[str, Any]] | None = None,
    post_activation_verifier: Callable[..., Mapping[str, Any]] | None = None,
    rollback_drain_controller: Callable[..., Mapping[str, Any]] | None = None,
    canary_pre_activation_verifier: Callable[..., Mapping[str, Any]] | None = None,
    canary_rollback_controller: Callable[..., Mapping[str, Any]] | None = None,
    subject_recovery_expectations: Mapping[str, str] | None = None,
    cs408_terminal_retirement_terminal_receipt_sha256: str | None = None,
    english_preserved_review_repair_descriptor_sha256: str | None = None,
    math_pending_queue_migration_intent_sha256: str | None = None,
    preview_state_inspector: Callable[..., Mapping[str, Any]] | None = None,
    claim_gate_timeout_seconds: float = 30.0,
    process_exit_timeout_seconds: float = 30.0,
    heartbeat_timeout_seconds: float = 90.0,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    if SHA256_RE.fullmatch(release_id) is None:
        raise ReleaseError("release_id_invalid")
    target = (release_base / "releases" / release_id).resolve()
    verified = verify_release(target)
    _three_subject_canary_capability(target, verified)
    context = _validate_three_subject_canary_manifest(
        canary_manifest,
        release_id=release_id,
        target=target,
    )
    return activate_release(
        release_base=release_base,
        release_id=release_id,
        active_link=active_link,
        apply=apply,
        operation="activate",
        expected_current=expected_current,
        drain_receipt=drain_receipt,
        launchagent_dir=launchagent_dir,
        codex_config_path=codex_config_path,
        morning_pointer_path=morning_pointer_path,
        plugin_cache_root=plugin_cache_root,
        command_runner=command_runner,
        lock_timeout_seconds=lock_timeout_seconds,
        process_inspector=process_inspector,
        post_activation_verifier=post_activation_verifier,
        rollback_drain_controller=rollback_drain_controller,
        canary_context=context,
        canary_pre_activation_verifier=canary_pre_activation_verifier,
        canary_rollback_controller=canary_rollback_controller,
        subject_recovery_expectations=subject_recovery_expectations,
        cs408_terminal_retirement_terminal_receipt_sha256=(
            cs408_terminal_retirement_terminal_receipt_sha256
        ),
        english_preserved_review_repair_descriptor_sha256=(
            english_preserved_review_repair_descriptor_sha256
        ),
        math_pending_queue_migration_intent_sha256=(
            math_pending_queue_migration_intent_sha256
        ),
        preview_state_inspector=preview_state_inspector,
        claim_gate_timeout_seconds=claim_gate_timeout_seconds,
        process_exit_timeout_seconds=process_exit_timeout_seconds,
        heartbeat_timeout_seconds=heartbeat_timeout_seconds,
    )


def _validate_math_resume_acceptance(
    path: Path, *, release_id: str
) -> dict[str, Any]:
    value, digest = _external_content_json(
        path,
        maximum_bytes=8 * 1024 * 1024,
        error_code="math_resume_acceptance_invalid",
    )
    inventory = value.get("inventory")
    reports = value.get("controlled_replay_reports")
    checks = value.get("business_checks")
    surface = value.get("formal_surface_guard")
    if (
        value.get("schema_version") != MATH_RESUME_ACCEPTANCE_SCHEMA
        or value.get("status") != "passed"
        or value.get("release_id") != release_id
        or value.get("unknown_backlog_count") != 0
        or value.get("formal_write_count") != 0
        or not isinstance(inventory, Mapping)
        or not isinstance(reports, list)
        or not reports
        or not isinstance(checks, list)
        or not isinstance(surface, Mapping)
        or surface.get("before_sha256") != surface.get("after_sha256")
        or SHA256_RE.fullmatch(str(surface.get("before_sha256") or "")) is None
    ):
        raise ReleaseError("math_resume_acceptance_invalid")
    expected_counts = {"math": 2, "cs408": 4, "english": 3}
    observed_capture_ids: set[tuple[str, str]] = set()
    inventory_counts: dict[str, int] = {}
    for subject, expected_count in expected_counts.items():
        rows = inventory.get(subject)
        if not isinstance(rows, list) or len(rows) != expected_count:
            raise ReleaseError("math_resume_acceptance_inventory_invalid")
        for row in rows:
            if not isinstance(row, Mapping):
                raise ReleaseError("math_resume_acceptance_inventory_invalid")
            capture_id = row.get("capture_id")
            fingerprint = row.get("input_fingerprint")
            generation = row.get("generation")
            if (
                not isinstance(capture_id, str)
                or not capture_id
                or (subject, capture_id) in observed_capture_ids
                or SHA256_RE.fullmatch(str(fingerprint or "")) is None
                or not isinstance(generation, int)
                or isinstance(generation, bool)
                or generation < 1
                or row.get("status") not in {"succeeded", "expected_failure"}
            ):
                raise ReleaseError("math_resume_acceptance_inventory_invalid")
            observed_capture_ids.add((subject, capture_id))
        inventory_counts[subject] = len(rows)
    report_summaries: list[dict[str, Any]] = []
    total_model_calls = 0
    for item in reports:
        if not isinstance(item, Mapping):
            raise ReleaseError("math_resume_acceptance_report_invalid")
        raw_path = item.get("path")
        raw_sha256 = item.get("sha256")
        if not isinstance(raw_path, str) or not isinstance(raw_sha256, str):
            raise ReleaseError("math_resume_acceptance_report_invalid")
        report, report_sha256 = _external_content_json(
            Path(raw_path),
            maximum_bytes=64 * 1024 * 1024,
            error_code="math_resume_acceptance_report_invalid",
        )
        results = report.get("results")
        if (
            report_sha256 != raw_sha256
            or report.get("schema_version")
            != "study-intake-controlled-replay-report-v1"
            or report.get("status") != "passed"
            or report.get("release_id") != release_id
            or report.get("formal_write_count") != 0
            or not isinstance(results, list)
            or not results
        ):
            raise ReleaseError("math_resume_acceptance_report_invalid")
        for result in results:
            if (
                not isinstance(result, Mapping)
                or result.get("outcome") != "succeeded"
                or not isinstance(result.get("model_call_count"), int)
                or result.get("model_call_count", 0) <= 0
                or result.get("formal_write_count") != 0
            ):
                raise ReleaseError("math_resume_acceptance_report_invalid")
        for case in report.get("preflight_cases") or []:
            if (
                not isinstance(case, Mapping)
                or case.get("status") != "passed"
                or case.get("model_call_count") != 0
                or case.get("formal_write_count") != 0
            ):
                raise ReleaseError("math_resume_acceptance_report_invalid")
        calls = report.get("model_call_count")
        if not isinstance(calls, int) or isinstance(calls, bool) or calls <= 0:
            raise ReleaseError("math_resume_acceptance_report_invalid")
        total_model_calls += calls
        report_summaries.append(
            {"path": str(Path(raw_path).resolve()), "sha256": report_sha256}
        )
    observed_checks: set[str] = set()
    for row in checks:
        if not isinstance(row, Mapping):
            raise ReleaseError("math_resume_business_checks_invalid")
        check_id = row.get("check_id")
        refs = row.get("evidence_refs")
        if (
            not isinstance(check_id, str)
            or check_id in observed_checks
            or row.get("status") != "passed"
            or not isinstance(refs, list)
            or not refs
            or not all(isinstance(ref, str) and ref for ref in refs)
        ):
            raise ReleaseError("math_resume_business_checks_invalid")
        observed_checks.add(check_id)
    if not MATH_RESUME_REQUIRED_CHECKS.issubset(observed_checks):
        raise ReleaseError("math_resume_business_checks_incomplete")
    return {
        "acceptance_manifest_path": str(path.resolve()),
        "acceptance_manifest_sha256": digest,
        "inventory_counts": inventory_counts,
        "business_check_count": len(observed_checks),
        "controlled_replay_reports": report_summaries,
        "model_call_count": total_model_calls,
        "formal_surface_sha256": surface["before_sha256"],
        "formal_write_count": 0,
    }


def seal_math_resume_acceptance(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    acceptance_manifest: Path,
    output_path: Path,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    current_id, current_path = _current_release(active_link.expanduser().absolute())
    if current_id != release_id or current_path is None:
        raise ReleaseError("math_resume_current_mismatch")
    verified = verify_release(Path(current_path))
    config = json.loads((Path(current_path) / "config.json").read_text(encoding="utf-8"))
    if (
        verified.get("release_profile") != "concurrent_v2"
        or config.get("adapters", {}).get("math", {}).get("enabled") is not True
    ):
        raise ReleaseError("math_resume_release_not_capable")
    acceptance = _validate_math_resume_acceptance(
        acceptance_manifest, release_id=release_id
    )
    core = {
        "schema_version": MATH_RESUME_RECEIPT_SCHEMA,
        "status": "accepted",
        "release_id": release_id,
        **acceptance,
        "created_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "formal_write_count": 0,
    }
    receipt = _seal_deployment_value(
        core, release_base=release_base, purpose=MATH_RESUME_AUTHORITY_PURPOSE
    )
    destination = output_path.expanduser().absolute()
    if destination in {Path("/"), Path.home()} or destination.is_symlink():
        raise ReleaseError("math_resume_receipt_path_invalid")
    atomic_json(destination, receipt, mode=0o400)
    return {
        "schema_version": MATH_RESUME_RECEIPT_SCHEMA,
        "status": "sealed",
        "release_id": release_id,
        "path": str(destination),
        "sha256": sha256_file(destination),
        "formal_write_count": 0,
    }


def _verify_math_resume_receipt(
    path: Path, *, release_base: Path, release_id: str
) -> dict[str, Any]:
    value = _bounded_manifest(path.expanduser().absolute())
    _verify_deployment_authority(
        value, release_base=release_base, purpose=MATH_RESUME_AUTHORITY_PURPOSE
    )
    if (
        value.get("schema_version") != MATH_RESUME_RECEIPT_SCHEMA
        or value.get("status") != "accepted"
        or value.get("release_id") != release_id
        or value.get("formal_write_count") != 0
    ):
        raise ReleaseError("math_resume_receipt_invalid")
    acceptance_path = value.get("acceptance_manifest_path")
    acceptance_sha256 = value.get("acceptance_manifest_sha256")
    if not isinstance(acceptance_path, str) or not isinstance(acceptance_sha256, str):
        raise ReleaseError("math_resume_receipt_invalid")
    acceptance = _validate_math_resume_acceptance(
        Path(acceptance_path), release_id=release_id
    )
    if acceptance["acceptance_manifest_sha256"] != acceptance_sha256:
        raise ReleaseError("math_resume_receipt_invalid")
    return {**dict(value), "acceptance": acceptance}


def resume_math_dispatcher(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    acceptance_receipt: Path,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    apply: bool = False,
    command_runner: CommandRunner | None = None,
    heartbeat_timeout_seconds: float = 90.0,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    active_link = active_link.expanduser().absolute()
    current_id, current_path = _current_release(active_link)
    if current_id != release_id or current_path is None:
        raise ReleaseError("math_resume_current_mismatch")
    target = Path(current_path)
    verified = verify_release(target)
    config = json.loads((target / "config.json").read_text(encoding="utf-8"))
    if (
        verified.get("release_profile") != "concurrent_v2"
        or config.get("adapters", {}).get("math", {}).get("enabled") is not True
    ):
        raise ReleaseError("math_resume_release_not_capable")
    acceptance = _verify_math_resume_receipt(
        acceptance_receipt,
        release_base=release_base,
        release_id=release_id,
    )
    launchagent_dir = _safe_launchagent_dir(launchagent_dir, create=False)
    topology = _service_commands(verified["service_topology"], launchagent_dir)
    math_service = next(
        (row for row in topology if row.get("name") == "math"), None
    )
    if not isinstance(math_service, Mapping):
        raise ReleaseError("math_resume_service_missing")
    rendered = _render_launchagent_plists(
        target,
        verified["service_topology"],
        active_link,
        Path(str(verified["runtime_data_root"])),
    )
    for service in topology:
        installed = launchagent_dir / f"{service['label']}.plist"
        expected_plist = rendered.get(str(service["label"]))
        try:
            installed_bytes = installed.read_bytes()
        except OSError as exc:
            raise ReleaseError("math_resume_plist_invalid") from exc
        if installed.is_symlink() or installed_bytes != expected_plist:
            raise ReleaseError("math_resume_plist_invalid")
    runner = command_runner or _subprocess_command_runner

    def run_json(
        subject: str, suffix: Sequence[str], error_code: str
    ) -> dict[str, Any]:
        dispatcher = [
            sys.executable,
            str(active_link / "bin" / "preprocess_dispatcher.py"),
            "--config",
            str(active_link / "config.json"),
            "--subject",
            subject,
        ]
        completed = runner([*dispatcher, *suffix])
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(error_code) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(error_code)
        return payload

    subjects = ("math", "cs408", "english")
    before = {
        subject: run_json(
            subject, ["status"], "math_resume_status_invalid"
        )
        for subject in subjects
    }
    if any(
        value.get("draining") is not True
        or value.get("active_count") != 0
        or value.get("claimed_total") != 0
        for value in before.values()
    ):
        raise ReleaseError("math_resume_not_drained")
    audits = {
        subject: run_json(
            subject, ["audit"], "math_resume_backlog_audit_failed"
        )
        for subject in subjects
    }
    if any(
        value.get("eligible_count") != 0
        or value.get("formal_write_count") != 0
        for value in audits.values()
    ):
        raise ReleaseError("math_resume_unknown_backlog")
    planned = {
        "schema_version": MATH_RESUME_PROOF_SCHEMA,
        "status": "planned" if not apply else "resumed",
        "release_id": release_id,
        "acceptance_receipt_sha256": sha256_file(acceptance_receipt),
        "acceptance_manifest_sha256": acceptance["acceptance"][
            "acceptance_manifest_sha256"
        ],
        "backlog_audits": audits,
        "subject_status_before": {
            subject: _public_dispatch_control_status(value)
            for subject, value in before.items()
        },
        "formal_write_count": 0,
    }
    if not apply:
        return planned
    if heartbeat_timeout_seconds <= 0 or heartbeat_timeout_seconds > 180:
        raise ReleaseError("math_resume_heartbeat_timeout_invalid")
    lock_path = release_base / "deployments" / "activation.lock"
    with _activation_lock(lock_path, 3.0):
        locked_id, _ = _current_release(active_link)
        if locked_id != release_id:
            raise ReleaseError("math_resume_current_mismatch")
        try:
            for subject in subjects:
                resumed = run_json(
                    subject, ["resume"], "math_resume_drain_clear_failed"
                )
                if resumed.get("draining") is not False:
                    raise ReleaseError("math_resume_drain_clear_failed")
            for phase in ("enable", "bootstrap", "verify"):
                command = math_service.get(phase)
                result = runner(command) if isinstance(command, list) else None
                if not isinstance(command, list) or _command_returncode(result) != 0:
                    raise ReleaseError(f"math_resume_service_{phase}_failed")
            heartbeat_root = (
                Path(str(verified["runtime_data_root"]))
                / "dispatch"
                / "state"
                / "subject-projections"
            )
            deadline = time.monotonic() + heartbeat_timeout_seconds
            after: dict[str, dict[str, Any]] = {}
            heartbeats: dict[str, dict[str, Any]] = {}
            while time.monotonic() < deadline:
                try:
                    after = {
                        subject: run_json(
                            subject,
                            ["status"],
                            "math_resume_status_invalid",
                        )
                        for subject in subjects
                    }
                    heartbeats = {
                        subject: _bounded_manifest(
                            heartbeat_root / f"{subject}.json"
                        )
                        for subject in subjects
                    }
                except ReleaseError:
                    time.sleep(0.2)
                    continue
                if all(
                    after[subject].get("draining") is False
                    and heartbeats[subject].get("subject") == subject
                    and heartbeats[subject].get("release_id") == release_id
                    and heartbeats[subject].get("daemon_status") == "running"
                    for subject in subjects
                ):
                    break
                time.sleep(0.2)
            else:
                raise ReleaseError("math_resume_heartbeat_missing")
        except Exception as exc:
            try:
                for subject in subjects:
                    run_json(
                        subject,
                        ["drain"],
                        "math_resume_failure_drain_failed",
                    )
                for phase in ("disable", "bootout"):
                    command = math_service.get(phase)
                    if isinstance(command, list):
                        runner(command)
            finally:
                failure = _seal_deployment_value(
                    {
                        **planned,
                        "status": "failed_drained",
                        "error_code": str(exc),
                        "failed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                    },
                    release_base=release_base,
                    purpose="math-resume-proof",
                )
                _write_deployment_receipt(release_base, failure)
            raise ReleaseError("math_resume_failed_drained") from exc
    proof = _seal_deployment_value(
        {
            **planned,
            "status": "resumed",
            "subject_status_after": after,
            "heartbeat_sha256s": {
                subject: sha256_file(heartbeat_root / f"{subject}.json")
                for subject in subjects
            },
            "resumed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        release_base=release_base,
        purpose="math-resume-proof",
    )
    proof_id = _write_deployment_receipt(release_base, proof)
    return {**proof, "proof_sha256": proof_id}


def _external_bound_json(
    path: Path, *, maximum_bytes: int, error_code: str
) -> tuple[dict[str, Any], str]:
    candidate = path.expanduser().absolute()
    if not path.is_absolute() or candidate in {Path("/"), Path.home()}:
        raise ReleaseError(error_code)
    try:
        node = candidate.lstat()
        size = node.st_size
    except OSError as exc:
        raise ReleaseError(error_code) from exc
    if (
        candidate.is_symlink()
        or not stat.S_ISREG(node.st_mode)
        or node.st_uid != os.getuid()
        or stat.S_IMODE(node.st_mode) & 0o022
        or size <= 0
        or size > maximum_bytes
    ):
        raise ReleaseError(error_code)
    digest = sha256_file(candidate)
    try:
        value = json.loads(candidate.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError(error_code) from exc
    if not isinstance(value, dict):
        raise ReleaseError(error_code)
    return value, digest


def _integer_at_least(value: Any, minimum: int) -> bool:
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and value >= minimum
    )


def _three_subject_resume_capability(
    target: Path, verified: Mapping[str, Any]
) -> tuple[dict[str, Any], Mapping[str, Any]]:
    try:
        config = json.loads((target / "config.json").read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReleaseError("three_subject_resume_release_not_capable") from exc
    adapters = config.get("adapters")
    test_results = verified.get("test_results")
    formal_gate = (
        test_results.get("formal_surface_gate")
        if isinstance(test_results, Mapping)
        else None
    )
    if (
        verified.get("release_profile") != "concurrent_v2"
        or verified.get("formal_write_count") != 0
        or not isinstance(adapters, Mapping)
        or any(
            not isinstance(adapters.get(subject), Mapping)
            or adapters[subject].get("enabled") is not True
            for subject in RESUMABLE_SUBJECTS
        )
        or not isinstance(test_results, Mapping)
        or test_results.get("status") != "passed"
        or test_results.get("real_model_call_count") != 0
        or test_results.get("formal_write_count") != 0
        or not isinstance(formal_gate, Mapping)
        or formal_gate.get("status") != "passed"
        or formal_gate.get("verification_status") != "unchanged"
    ):
        raise ReleaseError("three_subject_resume_release_not_capable")
    return config, formal_gate


def _verify_legacy_priority_resume_release(
    target: Path,
) -> dict[str, Any]:
    """Reopen only the historical priority release accepted by v1 evidence.

    The v1 three-subject resume receipts require requested priority service
    tier. They must never become an alternate control plane for the current
    no-fast-mode target contract, even when both releases use the concurrent
    service topology.
    """

    verified = verify_rollback_release(target)
    if (
        verified.get("verification_role")
        != "historical_reopen_or_rollback_only"
        or verified.get("historical_contract") != "historical_priority_v1"
        or verified.get("model_contract")
        != HISTORICAL_PRIORITY_MODEL_CONTRACT
    ):
        raise ReleaseError("three_subject_resume_legacy_priority_only")
    _three_subject_resume_capability(target, verified)
    return verified


def _validate_three_subject_resume_acceptance(
    path: Path,
    *,
    release_id: str,
    target: Path,
    verified: Mapping[str, Any],
) -> dict[str, Any]:
    value, digest = _external_content_json(
        path,
        maximum_bytes=8 * 1024 * 1024,
        error_code="three_subject_resume_acceptance_invalid",
    )
    _config, release_formal_gate = _three_subject_resume_capability(
        target, verified
    )
    subject_refs = value.get("subject_receipts")
    concurrency_ref = value.get("concurrency_receipt")
    fingerprints = value.get("mcp_authority_fingerprints")
    formal_guard = value.get("formal_surface_guard")
    if (
        set(value)
        != {
            "schema_version",
            "status",
            "release_id",
            "release_manifest_sha256",
            "subject_receipts",
            "concurrency_receipt",
            "mcp_authority_fingerprints",
            "formal_surface_guard",
            "seal_model_call_count",
            "seal_provider_request_count",
            "formal_write_count",
            "sol_enabled",
        }
        or value.get("schema_version")
        != THREE_SUBJECT_RESUME_ACCEPTANCE_SCHEMA
        or value.get("status") != "passed"
        or value.get("release_id") != release_id
        or value.get("release_manifest_sha256")
        != sha256_file(target / "release.json")
        or value.get("seal_model_call_count") != 0
        or value.get("seal_provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
        or not isinstance(subject_refs, Mapping)
        or set(subject_refs) != set(RESUMABLE_SUBJECTS)
        or not isinstance(concurrency_ref, Mapping)
        or not isinstance(fingerprints, Mapping)
        or set(fingerprints) != set(RESUMABLE_SUBJECTS)
        or any(
            SHA256_RE.fullmatch(str(fingerprints.get(subject) or "")) is None
            for subject in RESUMABLE_SUBJECTS
        )
        or not isinstance(formal_guard, Mapping)
    ):
        raise ReleaseError("three_subject_resume_acceptance_invalid")
    expected_formal = {
        "baseline_file_sha256": release_formal_gate.get(
            "baseline_file_sha256"
        ),
        "config_file_sha256": release_formal_gate.get("config_file_sha256"),
        "baseline_manifest_sha256": release_formal_gate.get(
            "baseline_manifest_sha256"
        ),
        "before_manifest_sha256": release_formal_gate.get(
            "current_manifest_sha256"
        ),
        "after_manifest_sha256": release_formal_gate.get(
            "current_manifest_sha256"
        ),
    }
    if (
        dict(formal_guard) != expected_formal
        or any(
            SHA256_RE.fullmatch(str(formal_guard.get(key) or "")) is None
            for key in expected_formal
        )
        or formal_guard.get("before_manifest_sha256")
        != formal_guard.get("after_manifest_sha256")
    ):
        raise ReleaseError("three_subject_resume_formal_binding_invalid")

    bound_subjects: dict[str, dict[str, Any]] = {}
    subject_receipt_sha256s: dict[str, str] = {}
    bound_model_calls = 0
    bound_provider_requests = 0
    for subject in RESUMABLE_SUBJECTS:
        ref = subject_refs.get(subject)
        if not isinstance(ref, Mapping) or set(ref) != {"path", "sha256"}:
            raise ReleaseError("three_subject_resume_subject_receipt_invalid")
        raw_path = ref.get("path")
        expected_sha256 = ref.get("sha256")
        if not isinstance(raw_path, str) or not isinstance(expected_sha256, str):
            raise ReleaseError("three_subject_resume_subject_receipt_invalid")
        receipt, receipt_sha256 = _external_bound_json(
            Path(raw_path),
            maximum_bytes=64 * 1024 * 1024,
            error_code="three_subject_resume_subject_receipt_invalid",
        )
        model_calls = receipt.get("model_call_count")
        provider_requests = receipt.get("provider_request_count")
        evidence_refs = receipt.get("evidence_refs")
        effective_tier = receipt.get("effective_service_tier")
        if (
            set(receipt)
            != {
                "schema_version",
                "status",
                "subject",
                "release_id",
                "mcp_authority_fingerprint",
                "mcp_read_completed",
                "mcp_read_call_count",
                "analysis_completed",
                "report_generated",
                "report_sha256",
                "requested_service_tier",
                "effective_service_tier",
                "model_call_count",
                "provider_request_count",
                "real_luna_run_count",
                "formal_surface_sha256",
                "formal_write_count",
                "sol_enabled",
                "production_accepted",
                "evidence_refs",
            }
            or receipt_sha256 != expected_sha256
            or receipt.get("schema_version")
            != THREE_SUBJECT_RESUME_EVIDENCE_SCHEMA
            or receipt.get("status") != "passed"
            or receipt.get("subject") != subject
            or receipt.get("release_id") != release_id
            or receipt.get("mcp_authority_fingerprint")
            != fingerprints[subject]
            or receipt.get("mcp_read_completed") is not True
            or not _integer_at_least(receipt.get("mcp_read_call_count"), 1)
            or receipt.get("analysis_completed") is not True
            or receipt.get("report_generated") is not True
            or SHA256_RE.fullmatch(str(receipt.get("report_sha256") or ""))
            is None
            or receipt.get("requested_service_tier") != "priority"
            or effective_tier not in {"priority", "requested_unverified"}
            or not isinstance(model_calls, int)
            or isinstance(model_calls, bool)
            or model_calls < 1
            or not isinstance(provider_requests, int)
            or isinstance(provider_requests, bool)
            or provider_requests < 1
            or not _integer_at_least(receipt.get("real_luna_run_count"), 1)
            or receipt.get("formal_surface_sha256")
            != formal_guard["after_manifest_sha256"]
            or receipt.get("formal_write_count") != 0
            or receipt.get("sol_enabled") is not False
            or receipt.get("production_accepted") is not False
            or not isinstance(evidence_refs, list)
            or not evidence_refs
            or not all(isinstance(item, str) and item for item in evidence_refs)
        ):
            raise ReleaseError("three_subject_resume_subject_receipt_invalid")
        subject_receipt_sha256s[subject] = receipt_sha256
        bound_model_calls += model_calls
        bound_provider_requests += provider_requests
        bound_subjects[subject] = {
            "path": str(Path(raw_path).resolve()),
            "sha256": receipt_sha256,
            "mcp_authority_fingerprint": fingerprints[subject],
            "effective_service_tier": effective_tier,
            "report_sha256": receipt["report_sha256"],
        }

    if set(concurrency_ref) != {"path", "sha256"}:
        raise ReleaseError("three_subject_resume_concurrency_receipt_invalid")
    raw_concurrency_path = concurrency_ref.get("path")
    expected_concurrency_sha256 = concurrency_ref.get("sha256")
    if not isinstance(raw_concurrency_path, str) or not isinstance(
        expected_concurrency_sha256, str
    ):
        raise ReleaseError("three_subject_resume_concurrency_receipt_invalid")
    concurrency, concurrency_sha256 = _external_bound_json(
        Path(raw_concurrency_path),
        maximum_bytes=64 * 1024 * 1024,
        error_code="three_subject_resume_concurrency_receipt_invalid",
    )
    peaks = concurrency.get("per_subject_peak_active")
    concurrency_fingerprints = concurrency.get("mcp_authority_fingerprints")
    concurrency_receipt_sha256s = concurrency.get("subject_receipt_sha256s")
    if (
        set(concurrency)
        != {
            "schema_version",
            "status",
            "release_id",
            "subjects",
            "barrier_expected",
            "barrier_arrived",
            "global_peak_active",
            "per_subject_peak_active",
            "mcp_read_subject_count",
            "analysis_completed_subject_count",
            "report_generated_count",
            "real_luna_run_count",
            "requested_service_tier",
            "effective_service_tier",
            "model_call_count",
            "provider_request_count",
            "mcp_authority_fingerprints",
            "subject_receipt_sha256s",
            "formal_surface_sha256",
            "formal_write_count",
            "sol_enabled",
            "production_accepted",
        }
        or concurrency_sha256 != expected_concurrency_sha256
        or concurrency.get("schema_version")
        != THREE_SUBJECT_CONCURRENCY_EVIDENCE_SCHEMA
        or concurrency.get("status") != "passed"
        or concurrency.get("release_id") != release_id
        or concurrency.get("subjects") != list(RESUMABLE_SUBJECTS)
        or concurrency.get("barrier_expected") != len(RESUMABLE_SUBJECTS)
        or concurrency.get("barrier_arrived") != len(RESUMABLE_SUBJECTS)
        or not _integer_at_least(
            concurrency.get("global_peak_active"), len(RESUMABLE_SUBJECTS)
        )
        or not isinstance(peaks, Mapping)
        or set(peaks) != set(RESUMABLE_SUBJECTS)
        or any(
            not isinstance(peaks.get(subject), int)
            or isinstance(peaks.get(subject), bool)
            or peaks[subject] < 1
            for subject in RESUMABLE_SUBJECTS
        )
        or concurrency.get("mcp_read_subject_count")
        != len(RESUMABLE_SUBJECTS)
        or concurrency.get("analysis_completed_subject_count")
        != len(RESUMABLE_SUBJECTS)
        or concurrency.get("report_generated_count")
        != len(RESUMABLE_SUBJECTS)
        or concurrency.get("real_luna_run_count")
        != len(RESUMABLE_SUBJECTS)
        or concurrency.get("requested_service_tier") != "priority"
        or concurrency.get("effective_service_tier")
        not in {"priority", "requested_unverified"}
        or not _integer_at_least(
            concurrency.get("model_call_count"), len(RESUMABLE_SUBJECTS)
        )
        or not _integer_at_least(
            concurrency.get("provider_request_count"),
            len(RESUMABLE_SUBJECTS),
        )
        or concurrency_fingerprints != fingerprints
        or concurrency_receipt_sha256s != subject_receipt_sha256s
        or concurrency.get("formal_surface_sha256")
        != formal_guard["after_manifest_sha256"]
        or concurrency.get("formal_write_count") != 0
        or concurrency.get("sol_enabled") is not False
        or concurrency.get("production_accepted") is not False
    ):
        raise ReleaseError("three_subject_resume_concurrency_receipt_invalid")
    return {
        "acceptance_manifest_path": str(path.resolve()),
        "acceptance_manifest_sha256": digest,
        "release_manifest_sha256": value["release_manifest_sha256"],
        "subject_receipts": bound_subjects,
        "subject_receipt_sha256s": subject_receipt_sha256s,
        "concurrency_receipt": {
            "path": str(Path(raw_concurrency_path).resolve()),
            "sha256": concurrency_sha256,
            "effective_service_tier": concurrency["effective_service_tier"],
        },
        "mcp_authority_fingerprints": dict(fingerprints),
        "formal_surface_guard": dict(formal_guard),
        "bound_model_call_count": bound_model_calls,
        "bound_provider_request_count": bound_provider_requests,
        "seal_model_call_count": 0,
        "seal_provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }


def seal_three_subject_resume_acceptance(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    acceptance_manifest: Path,
    output_path: Path,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    active_link = active_link.expanduser().absolute()
    current_id, current_path = _current_release(active_link)
    if current_id != release_id or current_path is None:
        raise ReleaseError("three_subject_resume_current_mismatch")
    target = Path(current_path)
    verified = _verify_legacy_priority_resume_release(target)
    acceptance = _validate_three_subject_resume_acceptance(
        acceptance_manifest,
        release_id=release_id,
        target=target,
        verified=verified,
    )
    core = {
        "schema_version": THREE_SUBJECT_RESUME_RECEIPT_SCHEMA,
        "status": "accepted",
        "release_id": release_id,
        **acceptance,
        "created_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        "formal_write_count": 0,
        "sol_enabled": False,
    }
    receipt = _seal_deployment_value(
        core,
        release_base=release_base,
        purpose=THREE_SUBJECT_RESUME_AUTHORITY_PURPOSE,
    )
    destination = output_path.expanduser().absolute()
    if destination in {Path("/"), Path.home()} or destination.is_symlink():
        raise ReleaseError("three_subject_resume_receipt_path_invalid")
    atomic_json(destination, receipt, mode=0o400)
    return {
        "schema_version": THREE_SUBJECT_RESUME_RECEIPT_SCHEMA,
        "status": "sealed",
        "release_id": release_id,
        "path": str(destination),
        "sha256": sha256_file(destination),
        "seal_model_call_count": 0,
        "seal_provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }


def _verify_three_subject_resume_receipt(
    path: Path,
    *,
    release_base: Path,
    release_id: str,
    target: Path,
    verified: Mapping[str, Any],
) -> dict[str, Any]:
    value = _bounded_manifest(path.expanduser().absolute())
    _verify_deployment_authority(
        value,
        release_base=release_base,
        purpose=THREE_SUBJECT_RESUME_AUTHORITY_PURPOSE,
    )
    if (
        value.get("schema_version") != THREE_SUBJECT_RESUME_RECEIPT_SCHEMA
        or value.get("status") != "accepted"
        or value.get("release_id") != release_id
        or value.get("seal_model_call_count") != 0
        or value.get("seal_provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
    ):
        raise ReleaseError("three_subject_resume_receipt_invalid")
    acceptance_path = value.get("acceptance_manifest_path")
    acceptance_sha256 = value.get("acceptance_manifest_sha256")
    if not isinstance(acceptance_path, str) or not isinstance(
        acceptance_sha256, str
    ):
        raise ReleaseError("three_subject_resume_receipt_invalid")
    acceptance = _validate_three_subject_resume_acceptance(
        Path(acceptance_path),
        release_id=release_id,
        target=target,
        verified=verified,
    )
    if acceptance["acceptance_manifest_sha256"] != acceptance_sha256:
        raise ReleaseError("three_subject_resume_receipt_invalid")
    return {**dict(value), "acceptance": acceptance}


def _parse_resume_timestamp(value: Any) -> dt.datetime:
    if not isinstance(value, str) or len(value) > 64:
        raise ReleaseError("three_subject_resume_heartbeat_invalid")
    try:
        parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ReleaseError("three_subject_resume_heartbeat_invalid") from exc
    if parsed.tzinfo is None:
        raise ReleaseError("three_subject_resume_heartbeat_invalid")
    return parsed.astimezone(dt.timezone.utc)


def _validate_fresh_resume_heartbeat(
    value: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    resumed_at: dt.datetime,
    observed_at: dt.datetime,
) -> None:
    heartbeat_at = _parse_resume_timestamp(value.get("updated_at"))
    interval = value.get("heartbeat_interval_seconds")
    if (
        value.get("subject") != subject
        or value.get("release_id") != release_id
        or value.get("daemon_status") != "running"
        or value.get("draining") is not False
        or value.get("formal_write_count") != 0
        or not isinstance(interval, (int, float))
        or isinstance(interval, bool)
        or interval <= 0
        or interval > POST_ACTIVATION_HEARTBEAT_TIMEOUT_MAX_SECONDS
        or heartbeat_at < resumed_at
        or heartbeat_at > observed_at + dt.timedelta(seconds=5)
        or (observed_at - heartbeat_at).total_seconds() > max(5.0, interval * 2)
    ):
        raise ReleaseError("three_subject_resume_heartbeat_invalid")


def _public_dispatch_control_status(value: Mapping[str, Any]) -> dict[str, Any]:
    public = {
        key: copy.deepcopy(value.get(key))
        for key in (
            "subject",
            "release_id",
            "daemon_status",
            "draining",
            "active_count",
            "claimed_total",
            "stale_count",
            "formal_write_count",
            "status",
            "error_code",
        )
        if key in value
    }
    gate = value.get("canary_gate")
    if isinstance(gate, Mapping):
        public["canary_gate"] = {
            key: copy.deepcopy(gate.get(key))
            for key in (
                "schema_version",
                "status",
                "state",
                "subject",
                "release_id",
                "activation_id",
                "activated_at",
                "producer_authority_fingerprint",
                "producer_high_watermark_sha256",
                "producer_capture_enabled",
                "luna_consumer_enabled",
                "queue_depth",
                "canary_queue_count",
                "active_task_count",
                "blocking_reason",
                "next_action",
                "formal_write_count",
                "sol_enabled",
                "production_accepted",
            )
            if key in gate
        }
    public["status_sha256"] = sha256_bytes(canonical_bytes(value))
    return public


def _emergency_cancel_public_proof(
    gate: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    before: Mapping[str, Any],
) -> dict[str, Any] | None:
    active_before = before.get("active_task_count")
    if not isinstance(active_before, int) or isinstance(active_before, bool):
        raise ReleaseError(
            f"three_subject_emergency_active_count_invalid:{subject}"
        )
    if active_before == 0:
        return None
    receipt_sha256 = gate.get("last_emergency_cancel_receipt_sha256")
    receipt_path = gate.get("last_terminal_receipt_path")
    if (
        gate.get("subject") != subject
        or gate.get("release_id") != release_id
        or gate.get("active_task_count") != 0
        or gate.get("late_result_fence_status") != "sealed"
        or SHA256_RE.fullmatch(str(receipt_sha256 or "")) is None
        or gate.get("last_terminal_receipt_sha256") != receipt_sha256
        or not isinstance(gate.get("last_emergency_cancel_at"), str)
        or not isinstance(receipt_path, str)
        or not receipt_path
    ):
        raise ReleaseError(
            f"three_subject_emergency_cancel_proof_invalid:{subject}"
        )
    path = Path(receipt_path).expanduser().absolute()
    if (
        path.is_symlink()
        or path.name != f"{receipt_sha256}.json"
        or not path.is_file()
        or sha256_file(path) != receipt_sha256
    ):
        raise ReleaseError(
            f"three_subject_emergency_cancel_proof_invalid:{subject}"
        )
    receipt = _bounded_manifest(path)
    if (
        receipt.get("subject") != subject
        or receipt.get("release_id") != release_id
        or receipt.get("activation_id") != gate.get("activation_id")
        or receipt.get("terminal_kind") != "emergency_hard_cancel"
        or receipt.get("late_result_fenced") is not True
        or receipt.get("outcome") != "cancelled"
        or receipt.get("error_code") != "daemon_shutdown"
        or receipt.get("package_path") is not None
        or receipt.get("package_sha256") is not None
        or receipt.get("formal_write_count") != 0
        or receipt.get("sol_enabled") is not False
        or not isinstance(receipt.get("authority"), Mapping)
    ):
        raise ReleaseError(
            f"three_subject_emergency_cancel_proof_invalid:{subject}"
        )
    return {
        "subject": subject,
        "terminal_kind": "emergency_hard_cancel",
        "terminal_receipt_sha256": receipt_sha256,
        "late_result_fence_status": "sealed",
        "cancelled_at": gate["last_emergency_cancel_at"],
        "formal_write_count": 0,
    }


def _canary_v2_common_controls_valid(value: Mapping[str, Any]) -> bool:
    return (
        value.get("schema_version")
        in {
            "study-intake-production-canary-state-v2",
            "study-intake-production-canary-state-v3",
        }
        and value.get("post_activation_only") is True
        and value.get("initial_canary_inflight_limit")
        == INITIAL_CANARY_INFLIGHT_LIMIT
        and value.get("continuous_concurrency_limit")
        == CONTINUOUS_CONCURRENCY_LIMIT
        and value.get("requested_service_tier") is REQUESTED_SERVICE_TIER
        and value.get("fast_mode_requested") is FAST_MODE_REQUESTED
        and value.get("fast_mode_effective") == FAST_MODE_EFFECTIVE
        and value.get("keep_backlog_drained") is True
        and value.get("production_accepted") is False
        and value.get("model_call_count") == 0
        and value.get("provider_request_count") == 0
        and value.get("formal_write_count") == 0
        and value.get("sol_enabled") is False
    )


def _canary_active_limit(value: Mapping[str, Any]) -> int:
    return (
        CONTINUOUS_CONCURRENCY_LIMIT
        if value.get("state") == "continuous_concurrent_unlocked"
        else INITIAL_CANARY_INFLIGHT_LIMIT
    )


def _validate_emergency_paused_canary_gate(
    value: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    before: Mapping[str, Any],
) -> dict[str, Any]:
    stable_fields = (
        "activation_id",
        "activated_at",
        "producer_authority_fingerprint",
        "producer_high_watermark",
        "producer_high_watermark_sha256",
    )
    if (
        not _canary_v2_common_controls_valid(value)
        or before.get("release_id") != release_id
        or value.get("status") != "production_canary_active"
        or value.get("state") != "paused_drained"
        or value.get("subject") != subject
        or value.get("release_id") != release_id
        or SHA256_RE.fullmatch(str(value.get("activation_id") or "")) is None
        or SHA256_RE.fullmatch(
            str(value.get("producer_authority_fingerprint") or "")
        )
        is None
        or not isinstance(value.get("producer_high_watermark"), Mapping)
        or SHA256_RE.fullmatch(
            str(value.get("producer_high_watermark_sha256") or "")
        )
        is None
        or value.get("producer_capture_enabled") is not True
        or value.get("luna_consumer_enabled") is not False
        or value.get("sol_formal_curation_enabled") is not False
        or value.get("active_task_count") != 0
        or not isinstance(value.get("queue_depth"), int)
        or isinstance(value.get("queue_depth"), bool)
        or value.get("queue_depth") < 0
        or not isinstance(value.get("canary_queue_count"), int)
        or isinstance(value.get("canary_queue_count"), bool)
        or value.get("canary_queue_count") < 0
        or (
            isinstance(before.get("canary_queue_count"), int)
            and not isinstance(before.get("canary_queue_count"), bool)
            and value.get("canary_queue_count")
            < before.get("canary_queue_count")
        )
        or value.get("blocking_reason") != "paused_by_user"
        or value.get("next_action") != "explicit_subject_resume_required"
        or value.get("model_call_count") != 0
        or value.get("provider_request_count") != 0
        or value.get("formal_write_count") != 0
        or value.get("sol_enabled") is not False
        or value.get("production_accepted") is not False
        or not isinstance(value.get("authority"), Mapping)
        or any(value.get(field) != before.get(field) for field in stable_fields)
    ):
        raise ReleaseError(
            f"three_subject_emergency_canary_pause_invalid:{subject}"
        )
    cancel_proof = _emergency_cancel_public_proof(
        value,
        subject=subject,
        release_id=release_id,
        before=before,
    )
    return {
        "subject": subject,
        "status": "production_canary_active",
        "state": "paused_drained",
        "release_id": release_id,
        "activation_id": value["activation_id"],
        "producer_high_watermark_sha256": value[
            "producer_high_watermark_sha256"
        ],
        "producer_capture_enabled": True,
        "luna_consumer_enabled": False,
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "queue_depth": value.get("queue_depth"),
        "canary_queue_count": value.get("canary_queue_count"),
        "emergency_cancel": cancel_proof,
        "formal_write_count": 0,
        "sol_enabled": False,
        "status_sha256": sha256_bytes(canonical_bytes(value)),
    }


def _rollback_three_subject_dispatchers(
    *,
    release_id: str,
    subjects: Sequence[str],
    services: Sequence[Mapping[str, Any]],
    run_json: Callable[[str, Sequence[str], str], dict[str, Any]],
    runner: CommandRunner,
    gate_before: Mapping[str, Mapping[str, Any]] | None = None,
    shutdown_timeout_seconds: float = 15.0,
    require_complete_gate_set: bool = True,
) -> tuple[
    dict[str, dict[str, Any]],
    dict[str, dict[str, Any]],
    list[str],
]:
    errors: list[str] = []
    drained: dict[str, dict[str, Any]] = {}
    original_gates = {
        subject: copy.deepcopy(dict(gate))
        for subject, gate in (gate_before or {}).items()
        if subject in set(subjects) and isinstance(gate, Mapping)
    }
    if (
        isinstance(shutdown_timeout_seconds, bool)
        or shutdown_timeout_seconds <= 0
        or shutdown_timeout_seconds > 60
    ):
        return {}, {}, ["shutdown_timeout_invalid"]
    # Stop KeepAlive and signal the daemon before waiting on leases.  A
    # production-canary daemon intentionally ignores the generic drain marker
    # while its gate is live; bootout is what triggers its bounded cancellation
    # and late-completion fence.
    for phase in ("disable", "bootout"):
        for service in services:
            try:
                if phase == "bootout":
                    succeeded = _run_service_bootout_idempotent(service, runner)
                else:
                    command = service.get(phase)
                    result = runner(command) if isinstance(command, list) else None
                    succeeded = (
                        isinstance(command, list)
                        and _command_returncode(result) == 0
                    )
                if not succeeded:
                    raise ReleaseError(
                        f"service_{phase}_failed:{service.get('name')}"
                    )
            except Exception as exc:
                errors.append(f"{phase}:{service.get('name')}:{exc}")
    shutdown_deadline = time.monotonic() + shutdown_timeout_seconds
    shutdown_ready: set[str] = set()
    for subject in subjects:
        last_error: Exception | None = None
        while time.monotonic() < shutdown_deadline:
            try:
                value = run_json(
                    subject,
                    ["status"],
                    "three_subject_emergency_shutdown_status_invalid",
                )
                gate = value.get("canary_gate")
                if (
                    isinstance(gate, Mapping)
                    and not (
                        not require_complete_gate_set
                        and gate.get("release_id") != release_id
                    )
                ):
                    original_gates.setdefault(subject, copy.deepcopy(dict(gate)))
                if (
                    value.get("subject") != subject
                    or value.get("active_count") != 0
                    or value.get("claimed_total") != 0
                ):
                    raise ReleaseError(
                        "three_subject_emergency_shutdown_not_drained"
                    )
                before_gate = original_gates.get(subject)
                if before_gate is not None:
                    if not isinstance(gate, Mapping):
                        raise ReleaseError(
                            "three_subject_emergency_canary_gate_missing"
                        )
                    _emergency_cancel_public_proof(
                        gate,
                        subject=subject,
                        release_id=release_id,
                        before=before_gate,
                    )
                if value.get("draining") is not True:
                    value = run_json(
                        subject,
                        ["drain"],
                        "three_subject_resume_failure_drain_failed",
                    )
                if (
                    value.get("subject") != subject
                    or value.get("draining") is not True
                    or value.get("active_count") != 0
                    or value.get("claimed_total") != 0
                ):
                    raise ReleaseError(
                        "three_subject_emergency_shutdown_not_drained"
                    )
                drained[subject] = _public_dispatch_control_status(value)
                shutdown_ready.add(subject)
                break
            except Exception as exc:
                last_error = exc
                time.sleep(0.2)
        if subject not in shutdown_ready:
            errors.append(f"shutdown:{subject}:{last_error}")
    if (
        require_complete_gate_set
        and original_gates
        and set(original_gates) != set(subjects)
    ):
        errors.append("pause:partial_canary_gate_set")
    paused_gates: dict[str, dict[str, Any]] = {}
    for subject in subjects:
        before_gate = original_gates.get(subject)
        if before_gate is None or subject not in shutdown_ready:
            continue
        try:
            paused = run_json(
                subject,
                ["pause-canary"],
                "three_subject_emergency_canary_pause_failed",
            )
            paused_gates[subject] = _validate_emergency_paused_canary_gate(
                paused,
                subject=subject,
                release_id=release_id,
                before=before_gate,
            )
        except Exception as exc:
            errors.append(f"pause:{subject}:{exc}")
    for subject in subjects:
        try:
            value = run_json(
                subject,
                ["status"],
                "three_subject_resume_rollback_status_invalid",
            )
            if (
                value.get("subject") != subject
                or value.get("draining") is not True
                or value.get("active_count") != 0
                or value.get("claimed_total") != 0
            ):
                raise ReleaseError("three_subject_resume_rollback_status_invalid")
            drained[subject] = _public_dispatch_control_status(value)
            before_gate = original_gates.get(subject)
            if before_gate is not None:
                gate = value.get("canary_gate")
                if not isinstance(gate, Mapping):
                    raise ReleaseError(
                        "three_subject_emergency_canary_pause_missing"
                    )
                paused_gates[subject] = _validate_emergency_paused_canary_gate(
                    gate,
                    subject=subject,
                    release_id=release_id,
                    before=before_gate,
                )
        except Exception as exc:
            errors.append(f"verify_drained:{subject}:{exc}")
    expected_paused_subjects = (
        set(subjects) if require_complete_gate_set else set(original_gates)
    )
    if original_gates and set(paused_gates) != expected_paused_subjects:
        errors.append("pause:canary_gate_set_incomplete")
    return drained, paused_gates, errors


def _canary_resume_binding(
    gate: Mapping[str, Any], *, subject: str, release_id: str
) -> dict[str, Any]:
    if (
        not _canary_v2_common_controls_valid(gate)
        or gate.get("status") != "production_canary_active"
        or gate.get("state") not in {"paused_drained", "failed_drained"}
        or gate.get("subject") != subject
        or gate.get("release_id") != release_id
        or SHA256_RE.fullmatch(str(gate.get("activation_id") or "")) is None
        or SHA256_RE.fullmatch(
            str(gate.get("producer_authority_fingerprint") or "")
        )
        is None
        or not isinstance(gate.get("producer_high_watermark"), Mapping)
        or SHA256_RE.fullmatch(
            str(gate.get("producer_high_watermark_sha256") or "")
        )
        is None
        or gate.get("producer_capture_enabled") is not True
        or gate.get("luna_consumer_enabled") is not False
        or gate.get("sol_formal_curation_enabled") is not False
        or gate.get("active_task_count") != 0
        or not isinstance(gate.get("canary_queue_count"), int)
        or isinstance(gate.get("canary_queue_count"), bool)
        or gate.get("canary_queue_count") < 0
        or gate.get("formal_write_count") != 0
        or gate.get("sol_enabled") is not False
        or gate.get("production_accepted") is not False
        or not isinstance(gate.get("authority"), Mapping)
    ):
        raise ReleaseError(f"canary_resume_gate_invalid:{subject}")
    return {
        "subject": subject,
        "state": gate["state"],
        "activation_id": gate["activation_id"],
        "activated_at": gate["activated_at"],
        "producer_authority_fingerprint": gate[
            "producer_authority_fingerprint"
        ],
        "producer_high_watermark": copy.deepcopy(
            gate["producer_high_watermark"]
        ),
        "producer_high_watermark_sha256": gate[
            "producer_high_watermark_sha256"
        ],
        "canary_queue_count": gate["canary_queue_count"],
        "unlocked_once": gate.get("unlocked_once") is True,
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "status_sha256": sha256_bytes(canonical_bytes(gate)),
    }


def _validate_resumed_canary_gate(
    gate: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    before: Mapping[str, Any],
) -> dict[str, Any]:
    stable_fields = (
        "activation_id",
        "activated_at",
        "producer_authority_fingerprint",
        "producer_high_watermark",
        "producer_high_watermark_sha256",
    )
    if (
        not _canary_v2_common_controls_valid(gate)
        or gate.get("status") != "production_canary_active"
        or gate.get("state")
        not in {
            "armed",
            "canary_in_flight",
            "continuous_concurrent_unlocked",
        }
        or gate.get("subject") != subject
        or gate.get("release_id") != release_id
        or gate.get("producer_capture_enabled") is not True
        or gate.get("luna_consumer_enabled") is not True
        or gate.get("sol_formal_curation_enabled") is not False
        or not isinstance(gate.get("active_task_count"), int)
        or isinstance(gate.get("active_task_count"), bool)
        or not 0 <= gate.get("active_task_count") <= _canary_active_limit(gate)
        or not isinstance(gate.get("canary_queue_count"), int)
        or isinstance(gate.get("canary_queue_count"), bool)
        or gate.get("canary_queue_count") < before["canary_queue_count"]
        or gate.get("formal_write_count") != 0
        or gate.get("sol_enabled") is not False
        or gate.get("production_accepted") is not False
        or not isinstance(gate.get("authority"), Mapping)
        or any(gate.get(field) != before.get(field) for field in stable_fields)
        or (
            before.get("unlocked_once") is True
            and gate.get("state") == "armed"
        )
    ):
        raise ReleaseError(f"canary_resume_gate_invalid:{subject}")
    return {
        "subject": subject,
        "state": gate["state"],
        "release_id": release_id,
        "activation_id": gate["activation_id"],
        "producer_high_watermark_sha256": gate[
            "producer_high_watermark_sha256"
        ],
        "producer_capture_enabled": True,
        "luna_consumer_enabled": True,
        "canary_queue_count": gate["canary_queue_count"],
        "active_task_count": gate["active_task_count"],
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "formal_write_count": 0,
        "sol_enabled": False,
        "status_sha256": sha256_bytes(canonical_bytes(gate)),
    }


def _validate_canary_resume_heartbeat(
    value: Mapping[str, Any],
    *,
    subject: str,
    release_id: str,
    resumed_at: dt.datetime,
    observed_at: dt.datetime,
) -> None:
    try:
        heartbeat_at = _parse_resume_timestamp(value.get("updated_at"))
    except ReleaseError as exc:
        raise ReleaseError("canary_resume_heartbeat_invalid") from exc
    interval = value.get("heartbeat_interval_seconds")
    if (
        value.get("subject") != subject
        or value.get("release_id") != release_id
        or value.get("daemon_status") != "running"
        or value.get("draining") is not True
        or value.get("formal_write_count") != 0
        or not isinstance(interval, (int, float))
        or isinstance(interval, bool)
        or interval <= 0
        or interval > POST_ACTIVATION_HEARTBEAT_TIMEOUT_MAX_SECONDS
        or heartbeat_at < resumed_at
        or heartbeat_at > observed_at + dt.timedelta(seconds=5)
        or (observed_at - heartbeat_at).total_seconds()
        > max(5.0, interval * 2)
    ):
        raise ReleaseError("canary_resume_heartbeat_invalid")


def resume_canary_dispatchers(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    subject: str,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    apply: bool = False,
    command_runner: CommandRunner | None = None,
    heartbeat_timeout_seconds: float = 90.0,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    active_link = active_link.expanduser().absolute()
    if subject not in {*RESUMABLE_SUBJECTS, "all"}:
        raise ReleaseError("canary_resume_subject_invalid")
    targets = (
        tuple(RESUMABLE_SUBJECTS) if subject == "all" else (subject,)
    )
    current_id, current_path = _current_release(active_link)
    if current_id != release_id or current_path is None:
        raise ReleaseError("canary_resume_current_mismatch")
    target = Path(current_path)
    verified = verify_release(target)
    _three_subject_canary_capability(target, verified)
    launchagent_dir = _safe_launchagent_dir(launchagent_dir, create=False)
    topology = _service_commands(verified["service_topology"], launchagent_dir)
    services = [row for row in topology if row.get("name") in set(targets)]
    if len(services) != len(targets):
        raise ReleaseError("canary_resume_service_topology_invalid")
    rendered = _render_launchagent_plists(
        target,
        verified["service_topology"],
        active_link,
        Path(str(verified["runtime_data_root"])),
    )
    for service in services:
        installed = launchagent_dir / f"{service['label']}.plist"
        try:
            installed_bytes = installed.read_bytes()
        except OSError as exc:
            raise ReleaseError("canary_resume_plist_invalid") from exc
        if (
            installed.is_symlink()
            or installed_bytes != rendered.get(str(service["label"]))
        ):
            raise ReleaseError("canary_resume_plist_invalid")
    runner = command_runner or _subprocess_command_runner

    def run_json(
        selected: str, suffix: Sequence[str], error_code: str
    ) -> dict[str, Any]:
        completed = runner(
            [
                sys.executable,
                str(active_link / "bin" / "preprocess_dispatcher.py"),
                "--config",
                str(active_link / "config.json"),
                "--subject",
                selected,
                *suffix,
            ]
        )
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(error_code) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(error_code)
        return payload

    def read_bindings() -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, Any]]]:
        statuses: dict[str, dict[str, Any]] = {}
        bindings: dict[str, dict[str, Any]] = {}
        for selected in targets:
            status = run_json(
                selected, ["status"], "canary_resume_status_invalid"
            )
            gate = status.get("canary_gate")
            if (
                status.get("subject") != selected
                or status.get("draining") is not True
                or status.get("active_count") != 0
                or status.get("claimed_total") != 0
                or not isinstance(gate, Mapping)
            ):
                raise ReleaseError(f"canary_resume_status_invalid:{selected}")
            statuses[selected] = status
            bindings[selected] = _canary_resume_binding(
                gate, subject=selected, release_id=release_id
            )
        return statuses, bindings

    _statuses, bindings = read_bindings()
    planned = {
        "schema_version": CANARY_RESUME_PROOF_SCHEMA,
        "status": "canary_resume_planned" if not apply else "canary_resume_started",
        "release_id": release_id,
        "subject": subject,
        "target_subjects": list(targets),
        "current_link_changed": False,
        "gate_bindings_before": bindings,
        "service_labels": [str(row["label"]) for row in services],
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "control_model_call_count": 0,
        "control_provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }
    if not apply:
        return planned
    if (
        heartbeat_timeout_seconds <= 0
        or heartbeat_timeout_seconds
        > POST_ACTIVATION_HEARTBEAT_TIMEOUT_MAX_SECONDS
    ):
        raise ReleaseError("canary_resume_heartbeat_timeout_invalid")
    heartbeat_root = (
        Path(str(verified["runtime_data_root"]))
        / "dispatch"
        / "state"
        / "subject-projections"
    )
    lock_path = release_base / "deployments" / "activation.lock"
    with _activation_lock(lock_path, 3.0):
        locked_id, _ = _current_release(active_link)
        if locked_id != release_id:
            raise ReleaseError("canary_resume_current_mismatch")
        _locked_statuses, bindings = read_bindings()
        resumed_at = dt.datetime.now(dt.timezone.utc)
        latest_runtime_gates = {
            selected: copy.deepcopy(
                dict(_locked_statuses[selected]["canary_gate"])
            )
            for selected in targets
        }
        try:
            for service in services:
                disable = service.get("disable")
                if (
                    not isinstance(disable, list)
                    or _command_returncode(runner(disable)) != 0
                    or not _run_service_bootout_idempotent(service, runner)
                ):
                    raise ReleaseError(
                        f"canary_resume_service_stop_failed:{service.get('name')}"
                    )
            resumed_gates: dict[str, dict[str, Any]] = {}
            for selected in targets:
                resumed_gate = run_json(
                    selected,
                    ["resume-canary"],
                    "canary_resume_runtime_failed",
                )
                latest_runtime_gates[selected] = copy.deepcopy(
                    dict(resumed_gate)
                )
                resumed_gates[selected] = _validate_resumed_canary_gate(
                    resumed_gate,
                    subject=selected,
                    release_id=release_id,
                    before=bindings[selected],
                )
            resumed_service_proofs: list[dict[str, Any]] = []
            for phase in ("enable", "bootstrap", "verify"):
                for service in services:
                    command = service.get(phase)
                    result = runner(command) if isinstance(command, list) else None
                    if not isinstance(command, list) or _command_returncode(result) != 0:
                        raise ReleaseError(
                            f"canary_resume_service_{phase}_failed:"
                            f"{service.get('name')}"
                        )
                    if phase == "verify":
                        matched = re.search(
                            r"(?:^|\n)\s*pid\s*=\s*(\d+)\s*(?:\n|$)",
                            _command_stdout(result),
                        )
                        if matched is not None:
                            resumed_service_proofs.append(
                                {
                                    "label": str(service["label"]),
                                    "pid": int(matched.group(1)),
                                }
                            )
            stalled_deadline = time.monotonic() + heartbeat_timeout_seconds
            progress_token: tuple[tuple[int, str], ...] | None = None
            statuses_after: dict[str, dict[str, Any]] = {}
            heartbeats: dict[str, dict[str, Any]] = {}
            while True:
                try:
                    observed_at = dt.datetime.now(dt.timezone.utc)
                    for selected in targets:
                        status = run_json(
                            selected,
                            ["status"],
                            "canary_resume_status_invalid",
                        )
                        gate = status.get("canary_gate")
                        if (
                            status.get("subject") != selected
                            or status.get("draining") is not True
                            or not isinstance(status.get("active_count"), int)
                            or isinstance(status.get("active_count"), bool)
                            or not 0 <= status.get("active_count")
                            <= CONTINUOUS_CONCURRENCY_LIMIT
                            or not isinstance(gate, Mapping)
                        ):
                            raise ReleaseError("canary_resume_status_invalid")
                        latest_runtime_gates[selected] = copy.deepcopy(
                            dict(gate)
                        )
                        resumed_gates[selected] = _validate_resumed_canary_gate(
                            gate,
                            subject=selected,
                            release_id=release_id,
                            before=bindings[selected],
                        )
                        heartbeat = _bounded_manifest(
                            heartbeat_root / f"{selected}.json"
                        )
                        _validate_canary_resume_heartbeat(
                            heartbeat,
                            subject=selected,
                            release_id=release_id,
                            resumed_at=resumed_at,
                            observed_at=observed_at,
                        )
                        statuses_after[selected] = status
                        heartbeats[selected] = heartbeat
                except ReleaseError:
                    current_progress = _running_service_progress_token(
                        service_proofs=resumed_service_proofs,
                        heartbeat_root=heartbeat_root,
                    )
                    now = time.monotonic()
                    if current_progress != progress_token:
                        progress_token = current_progress
                        stalled_deadline = now + heartbeat_timeout_seconds
                    elif now >= stalled_deadline:
                        raise ReleaseError("canary_resume_heartbeat_stalled")
                    time.sleep(0.2)
                    continue
                break
            final_id, _ = _current_release(active_link)
            if final_id != release_id:
                raise ReleaseError("canary_resume_current_mismatch")
        except Exception as exc:
            rollback_snapshot_errors: list[str] = []
            for selected in targets:
                try:
                    failure_status = run_json(
                        selected,
                        ["status"],
                        "canary_resume_failure_status_invalid",
                    )
                    failure_gate = failure_status.get("canary_gate")
                    active_count = failure_status.get("active_count")
                    claimed_total = failure_status.get("claimed_total")
                    if (
                        failure_status.get("subject") != selected
                        or not isinstance(failure_gate, Mapping)
                        or failure_gate.get("subject") != selected
                        or failure_gate.get("release_id") != release_id
                        or not isinstance(active_count, int)
                        or isinstance(active_count, bool)
                        or not 0 <= active_count
                        <= CONTINUOUS_CONCURRENCY_LIMIT
                        or not isinstance(claimed_total, int)
                        or isinstance(claimed_total, bool)
                        or not 0 <= claimed_total
                        <= CONTINUOUS_CONCURRENCY_LIMIT
                        or not _canary_v2_common_controls_valid(failure_gate)
                        or active_count > _canary_active_limit(failure_gate)
                        or claimed_total > _canary_active_limit(failure_gate)
                        or failure_gate.get("active_task_count") != active_count
                    ):
                        raise ReleaseError(
                            "canary_resume_failure_status_invalid"
                        )
                    latest_runtime_gates[selected] = copy.deepcopy(
                        dict(failure_gate)
                    )
                except Exception as snapshot_exc:
                    rollback_snapshot_errors.append(
                        f"failure_snapshot:{selected}:{snapshot_exc}"
                    )
            _drained, paused_gates, rollback_errors = (
                _rollback_three_subject_dispatchers(
                    release_id=release_id,
                    subjects=targets,
                    services=services,
                    run_json=run_json,
                    runner=runner,
                    gate_before=latest_runtime_gates,
                )
            )
            rollback_errors = [*rollback_snapshot_errors, *rollback_errors]
            failure = _seal_deployment_value(
                {
                    **planned,
                    "status": (
                        "canary_resume_failed_paused"
                        if not rollback_errors
                        else "canary_resume_failed_rollback_incomplete"
                    ),
                    "error_code": str(exc),
                    "canary_gates_after": paused_gates,
                    "rollback_errors": rollback_errors,
                    "failed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                },
                release_base=release_base,
                purpose=CANARY_RESUME_PROOF_PURPOSE,
            )
            _write_deployment_receipt(release_base, failure)
            if rollback_errors:
                raise ReleaseError("canary_resume_failed_rollback_incomplete") from exc
            raise ReleaseError("canary_resume_failed_paused") from exc
    proof = _seal_deployment_value(
        {
            **planned,
            "status": "canary_resumed",
            "gate_bindings_before": bindings,
            "canary_gates_after": resumed_gates,
            "heartbeat_sha256s": {
                selected: sha256_file(heartbeat_root / f"{selected}.json")
                for selected in targets
            },
            "completed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        release_base=release_base,
        purpose=CANARY_RESUME_PROOF_PURPOSE,
    )
    proof_id = _write_deployment_receipt(release_base, proof)
    return {**proof, "proof_sha256": proof_id}


def _canary_pause_binding(
    gate: Mapping[str, Any], *, subject: str, release_id: str
) -> dict[str, Any]:
    state = gate.get("state")
    active = gate.get("active_task_count")
    consumer_expected = state not in {"paused_drained", "failed_drained"}
    if (
        not _canary_v2_common_controls_valid(gate)
        or gate.get("status") != "production_canary_active"
        or state
        not in {
            "armed",
            "canary_in_flight",
            "continuous_concurrent_unlocked",
            "failed_drained",
            "paused_drained",
        }
        or gate.get("subject") != subject
        or gate.get("release_id") != release_id
        or SHA256_RE.fullmatch(str(gate.get("activation_id") or "")) is None
        or SHA256_RE.fullmatch(
            str(gate.get("producer_authority_fingerprint") or "")
        )
        is None
        or not isinstance(gate.get("producer_high_watermark"), Mapping)
        or SHA256_RE.fullmatch(
            str(gate.get("producer_high_watermark_sha256") or "")
        )
        is None
        or gate.get("producer_capture_enabled") is not True
        or gate.get("luna_consumer_enabled") is not consumer_expected
        or gate.get("sol_formal_curation_enabled") is not False
        or not isinstance(active, int)
        or isinstance(active, bool)
        or not 0 <= active <= _canary_active_limit(gate)
        or (state in {"paused_drained", "failed_drained"} and active != 0)
        or not isinstance(gate.get("canary_queue_count"), int)
        or isinstance(gate.get("canary_queue_count"), bool)
        or gate.get("canary_queue_count") < 0
        or gate.get("formal_write_count") != 0
        or gate.get("sol_enabled") is not False
        or gate.get("production_accepted") is not False
        or not isinstance(gate.get("authority"), Mapping)
    ):
        raise ReleaseError(f"canary_pause_gate_invalid:{subject}")
    return {
        "subject": subject,
        "state": state,
        "activation_id": gate["activation_id"],
        "activated_at": gate["activated_at"],
        "producer_authority_fingerprint": gate[
            "producer_authority_fingerprint"
        ],
        "producer_high_watermark_sha256": gate[
            "producer_high_watermark_sha256"
        ],
        "canary_queue_count": gate["canary_queue_count"],
        "active_task_count": active,
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "status_sha256": sha256_bytes(canonical_bytes(gate)),
    }


def pause_canary_dispatchers(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    subject: str,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    apply: bool = False,
    command_runner: CommandRunner | None = None,
    heartbeat_timeout_seconds: float = 90.0,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    active_link = active_link.expanduser().absolute()
    if subject not in {*RESUMABLE_SUBJECTS, "all"}:
        raise ReleaseError("canary_pause_subject_invalid")
    targets = tuple(RESUMABLE_SUBJECTS) if subject == "all" else (subject,)
    current_id, current_path = _current_release(active_link)
    if current_id != release_id or current_path is None:
        raise ReleaseError("canary_pause_current_mismatch")
    target = Path(current_path)
    verified = verify_release(target)
    _three_subject_canary_capability(target, verified)
    launchagent_dir = _safe_launchagent_dir(launchagent_dir, create=False)
    topology = _service_commands(verified["service_topology"], launchagent_dir)
    services = [row for row in topology if row.get("name") in set(targets)]
    if len(services) != len(targets):
        raise ReleaseError("canary_pause_service_topology_invalid")
    rendered = _render_launchagent_plists(
        target,
        verified["service_topology"],
        active_link,
        Path(str(verified["runtime_data_root"])),
    )
    for service in services:
        installed = launchagent_dir / f"{service['label']}.plist"
        try:
            installed_bytes = installed.read_bytes()
        except OSError as exc:
            raise ReleaseError("canary_pause_plist_invalid") from exc
        if (
            installed.is_symlink()
            or installed_bytes != rendered.get(str(service["label"]))
        ):
            raise ReleaseError("canary_pause_plist_invalid")
    runner = command_runner or _subprocess_command_runner

    def run_json(
        selected: str, suffix: Sequence[str], error_code: str
    ) -> dict[str, Any]:
        completed = runner(
            [
                sys.executable,
                str(active_link / "bin" / "preprocess_dispatcher.py"),
                "--config",
                str(active_link / "config.json"),
                "--subject",
                selected,
                *suffix,
            ]
        )
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(error_code) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(error_code)
        return payload

    def read_pause_state() -> tuple[
        dict[str, dict[str, Any]],
        dict[str, dict[str, Any]],
    ]:
        statuses: dict[str, dict[str, Any]] = {}
        gates: dict[str, dict[str, Any]] = {}
        for selected in targets:
            status = run_json(
                selected, ["status"], "canary_pause_status_invalid"
            )
            gate = status.get("canary_gate")
            if (
                status.get("subject") != selected
                or status.get("draining") is not True
                or not isinstance(status.get("active_count"), int)
                or isinstance(status.get("active_count"), bool)
                or not 0 <= status.get("active_count")
                <= CONTINUOUS_CONCURRENCY_LIMIT
                or status.get("claimed_total") != status.get("active_count")
                or not isinstance(gate, Mapping)
                or gate.get("active_task_count") != status.get("active_count")
            ):
                raise ReleaseError(f"canary_pause_status_invalid:{selected}")
            _canary_pause_binding(
                gate, subject=selected, release_id=release_id
            )
            statuses[selected] = status
            gates[selected] = copy.deepcopy(dict(gate))
        return statuses, gates

    _statuses, gates_before = read_pause_state()
    planned = {
        "schema_version": CANARY_PAUSE_PROOF_SCHEMA,
        "status": "canary_pause_planned" if not apply else "canary_pause_started",
        "release_id": release_id,
        "subject": subject,
        "target_subjects": list(targets),
        "current_link_changed": False,
        "gate_bindings_before": {
            selected: _canary_pause_binding(
                gates_before[selected], subject=selected, release_id=release_id
            )
            for selected in targets
        },
        "watcher_policy": "running_materialize_only_consumer_paused",
        "initial_canary_inflight_limit": INITIAL_CANARY_INFLIGHT_LIMIT,
        "continuous_concurrency_limit": CONTINUOUS_CONCURRENCY_LIMIT,
        "requested_service_tier": REQUESTED_SERVICE_TIER,
        "fast_mode_requested": FAST_MODE_REQUESTED,
        "fast_mode_effective": FAST_MODE_EFFECTIVE,
        "control_model_call_count": 0,
        "control_provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }
    if not apply:
        return planned
    if (
        heartbeat_timeout_seconds <= 0
        or heartbeat_timeout_seconds
        > POST_ACTIVATION_HEARTBEAT_TIMEOUT_MAX_SECONDS
    ):
        raise ReleaseError("canary_pause_heartbeat_timeout_invalid")
    heartbeat_root = (
        Path(str(verified["runtime_data_root"]))
        / "dispatch"
        / "state"
        / "subject-projections"
    )
    lock_path = release_base / "deployments" / "activation.lock"
    with _activation_lock(lock_path, 3.0):
        locked_id, _ = _current_release(active_link)
        if locked_id != release_id:
            raise ReleaseError("canary_pause_current_mismatch")
        _locked_statuses, gates_before = read_pause_state()
        paused_statuses, paused_gates, pause_errors = (
            _rollback_three_subject_dispatchers(
                release_id=release_id,
                subjects=targets,
                services=services,
                run_json=run_json,
                runner=runner,
                gate_before=gates_before,
            )
        )
        if pause_errors:
            failure = _seal_deployment_value(
                {
                    **planned,
                    "status": "canary_pause_failed_incomplete",
                    "canary_gates_after": paused_gates,
                    "errors": pause_errors,
                    "failed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                },
                release_base=release_base,
                purpose=CANARY_PAUSE_PROOF_PURPOSE,
            )
            _write_deployment_receipt(release_base, failure)
            raise ReleaseError("canary_pause_failed_incomplete")
        watcher_started_at = dt.datetime.now(dt.timezone.utc)
        try:
            for phase in ("enable", "bootstrap", "verify"):
                for service in services:
                    command = service.get(phase)
                    if (
                        not isinstance(command, list)
                        or _command_returncode(runner(command)) != 0
                    ):
                        raise ReleaseError(
                            f"canary_pause_watcher_{phase}_failed:"
                            f"{service.get('name')}"
                        )
            deadline = time.monotonic() + heartbeat_timeout_seconds
            heartbeats: dict[str, dict[str, Any]] = {}
            while time.monotonic() < deadline:
                try:
                    observed_at = dt.datetime.now(dt.timezone.utc)
                    for selected in targets:
                        status = run_json(
                            selected,
                            ["status"],
                            "canary_pause_status_invalid",
                        )
                        gate = status.get("canary_gate")
                        if (
                            status.get("subject") != selected
                            or status.get("draining") is not True
                            or status.get("active_count") != 0
                            or status.get("claimed_total") != 0
                            or not isinstance(gate, Mapping)
                        ):
                            raise ReleaseError("canary_pause_status_invalid")
                        paused_gates[selected] = (
                            _validate_emergency_paused_canary_gate(
                                gate,
                                subject=selected,
                                release_id=release_id,
                                before=gates_before[selected],
                            )
                        )
                        heartbeat = _bounded_manifest(
                            heartbeat_root / f"{selected}.json"
                        )
                        _validate_canary_resume_heartbeat(
                            heartbeat,
                            subject=selected,
                            release_id=release_id,
                            resumed_at=watcher_started_at,
                            observed_at=observed_at,
                        )
                        heartbeats[selected] = heartbeat
                except ReleaseError:
                    time.sleep(0.2)
                    continue
                break
            else:
                raise ReleaseError("canary_pause_heartbeat_missing")
            final_id, _ = _current_release(active_link)
            if final_id != release_id:
                raise ReleaseError("canary_pause_current_mismatch")
        except Exception as exc:
            _drained, failed_gates, rollback_errors = (
                _rollback_three_subject_dispatchers(
                    release_id=release_id,
                    subjects=targets,
                    services=services,
                    run_json=run_json,
                    runner=runner,
                    gate_before=gates_before,
                )
            )
            failure = _seal_deployment_value(
                {
                    **planned,
                    "status": (
                        "canary_pause_watcher_failed_paused"
                        if not rollback_errors
                        else "canary_pause_failed_incomplete"
                    ),
                    "error_code": str(exc),
                    "canary_gates_after": failed_gates,
                    "rollback_errors": rollback_errors,
                    "failed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                },
                release_base=release_base,
                purpose=CANARY_PAUSE_PROOF_PURPOSE,
            )
            _write_deployment_receipt(release_base, failure)
            if rollback_errors:
                raise ReleaseError("canary_pause_failed_incomplete") from exc
            raise ReleaseError("canary_pause_watcher_failed_paused") from exc
    proof = _seal_deployment_value(
        {
            **planned,
            "status": "canary_paused_watcher_running",
            "gate_bindings_before": {
                selected: _canary_pause_binding(
                    gates_before[selected],
                    subject=selected,
                    release_id=release_id,
                )
                for selected in targets
            },
            "canary_gates_after": paused_gates,
            "subject_status_after": paused_statuses,
            "heartbeat_sha256s": {
                selected: sha256_file(heartbeat_root / f"{selected}.json")
                for selected in targets
            },
            "completed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
        },
        release_base=release_base,
        purpose=CANARY_PAUSE_PROOF_PURPOSE,
    )
    proof_id = _write_deployment_receipt(release_base, proof)
    return {**proof, "proof_sha256": proof_id}


def resume_all_dispatchers(
    *,
    release_base: Path,
    release_id: str,
    active_link: Path,
    acceptance_receipt: Path | None,
    launchagent_dir: Path = DEFAULT_LAUNCHAGENT_DIR,
    apply: bool = False,
    rollback: bool = False,
    command_runner: CommandRunner | None = None,
    heartbeat_timeout_seconds: float = 90.0,
) -> dict[str, Any]:
    release_base = _safe_base(release_base, label="release_base")
    active_link = active_link.expanduser().absolute()
    current_id, current_path = _current_release(active_link)
    if current_id != release_id or current_path is None:
        raise ReleaseError("three_subject_resume_current_mismatch")
    target = Path(current_path)
    if rollback:
        verified = verify_rollback_release(target)
        _three_subject_resume_capability(target, verified)
    else:
        verified = _verify_legacy_priority_resume_release(target)
    acceptance = None
    if acceptance_receipt is not None:
        acceptance = _verify_three_subject_resume_receipt(
            acceptance_receipt,
            release_base=release_base,
            release_id=release_id,
            target=target,
            verified=verified,
        )
    elif not rollback:
        raise ReleaseError("three_subject_resume_receipt_required")
    launchagent_dir = _safe_launchagent_dir(launchagent_dir, create=False)
    topology = _service_commands(verified["service_topology"], launchagent_dir)
    services = [
        service
        for service in topology
        if service.get("name") in set(RESUMABLE_SUBJECTS)
    ]
    if (
        len(services) != len(RESUMABLE_SUBJECTS)
        or {str(service.get("name")) for service in services}
        != set(RESUMABLE_SUBJECTS)
    ):
        raise ReleaseError("three_subject_resume_service_topology_invalid")
    rendered = _render_launchagent_plists(
        target,
        verified["service_topology"],
        active_link,
        Path(str(verified["runtime_data_root"])),
    )
    if not rollback:
        for service in topology:
            installed = launchagent_dir / f"{service['label']}.plist"
            try:
                installed_bytes = installed.read_bytes()
            except OSError as exc:
                raise ReleaseError("three_subject_resume_plist_invalid") from exc
            if installed.is_symlink() or installed_bytes != rendered.get(
                str(service["label"])
            ):
                raise ReleaseError("three_subject_resume_plist_invalid")
    runner = command_runner or _subprocess_command_runner

    def run_json(
        subject: str, suffix: Sequence[str], error_code: str
    ) -> dict[str, Any]:
        command = [
            sys.executable,
            str(active_link / "bin" / "preprocess_dispatcher.py"),
            "--config",
            str(active_link / "config.json"),
            "--subject",
            subject,
            *suffix,
        ]
        completed = runner(command)
        try:
            payload = json.loads(_command_stdout(completed))
        except json.JSONDecodeError as exc:
            raise ReleaseError(error_code) from exc
        if _command_returncode(completed) != 0 or not isinstance(payload, dict):
            raise ReleaseError(error_code)
        return payload

    before: dict[str, dict[str, Any]] = {}
    before_errors: list[str] = []
    for subject in RESUMABLE_SUBJECTS:
        try:
            before[subject] = run_json(
                subject, ["status"], "three_subject_resume_status_invalid"
            )
        except ReleaseError as exc:
            if not rollback:
                raise
            before_errors.append(f"status:{subject}:{exc}")
            before[subject] = {
                "subject": subject,
                "status": "unavailable",
                "error_code": str(exc),
            }
    if not rollback and any(
        value.get("subject") != subject
        or value.get("draining") is not True
        or value.get("active_count") != 0
        or value.get("claimed_total") != 0
        for subject, value in before.items()
    ):
        raise ReleaseError("three_subject_resume_not_drained")
    gate_before = {
        subject: value["canary_gate"]
        for subject, value in before.items()
        if isinstance(value.get("canary_gate"), Mapping)
    }
    audits: dict[str, dict[str, Any]] = {}
    if not rollback:
        audits = {
            subject: run_json(
                subject,
                ["audit"],
                "three_subject_resume_backlog_audit_failed",
            )
            for subject in RESUMABLE_SUBJECTS
        }
        if any(
            value.get("subject") != subject
            or value.get("model_call_count") != 0
            or value.get("formal_write_count") != 0
            for subject, value in audits.items()
        ):
            raise ReleaseError("three_subject_resume_backlog_audit_failed")
    planned = {
        "schema_version": THREE_SUBJECT_RESUME_PROOF_SCHEMA,
        "status": (
            "rollback_planned"
            if rollback and not apply
            else "rollback_started"
            if rollback
            else "planned"
            if not apply
            else "resume_started"
        ),
        "operation": "rollback" if rollback else "resume",
        "global_emergency_stop": rollback,
        "canary_pause_policy": (
            "preserve_activation_high_watermark_queue_and_producer"
            if rollback
            else None
        ),
        "release_id": release_id,
        "active_link": str(active_link),
        "current_link_changed": False,
        "acceptance_receipt_sha256": (
            sha256_file(acceptance_receipt)
            if acceptance_receipt is not None
            else None
        ),
        "acceptance_manifest_sha256": (
            acceptance["acceptance"]["acceptance_manifest_sha256"]
            if isinstance(acceptance, Mapping)
            else None
        ),
        "subject_status_before": before,
        "preflight_errors": before_errors,
        "backlog_audits": audits,
        "dispatcher_labels": [str(service["label"]) for service in services],
        "resume_model_call_count": 0,
        "resume_provider_request_count": 0,
        "formal_write_count": 0,
        "sol_enabled": False,
    }
    if not apply:
        return planned
    if (
        heartbeat_timeout_seconds <= 0
        or heartbeat_timeout_seconds
        > POST_ACTIVATION_HEARTBEAT_TIMEOUT_MAX_SECONDS
    ):
        raise ReleaseError("three_subject_resume_heartbeat_timeout_invalid")
    lock_path = release_base / "deployments" / "activation.lock"
    with _activation_lock(lock_path, 3.0):
        locked_id, _ = _current_release(active_link)
        if locked_id != release_id:
            raise ReleaseError("three_subject_resume_current_mismatch")
        if rollback:
            drained, paused_gates, rollback_errors = (
                _rollback_three_subject_dispatchers(
                release_id=release_id,
                subjects=RESUMABLE_SUBJECTS,
                services=services,
                run_json=run_json,
                runner=runner,
                gate_before=gate_before,
                )
            )
            final_id, _ = _current_release(active_link)
            if final_id != release_id:
                rollback_errors.append("current_release_changed_during_rollback")
            status = (
                "rolled_back_drained"
                if not rollback_errors
                else "rollback_incomplete"
            )
            proof = _seal_deployment_value(
                {
                    **planned,
                    "status": status,
                    "subject_status_after": drained,
                    "canary_gates_after": paused_gates,
                    "producer_queues_preserved": True,
                    "rollback_errors": rollback_errors,
                    "completed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                },
                release_base=release_base,
                purpose=THREE_SUBJECT_RESUME_PROOF_PURPOSE,
            )
            proof_id = _write_deployment_receipt(release_base, proof)
            if rollback_errors:
                raise ReleaseError("three_subject_resume_rollback_incomplete")
            return {**proof, "proof_sha256": proof_id}

        acceptance = _verify_three_subject_resume_receipt(
            acceptance_receipt,
            release_base=release_base,
            release_id=release_id,
            target=target,
            verified=verified,
        )
        locked_before = {
            subject: run_json(
                subject, ["status"], "three_subject_resume_status_invalid"
            )
            for subject in RESUMABLE_SUBJECTS
        }
        if any(
            value.get("subject") != subject
            or value.get("draining") is not True
            or value.get("active_count") != 0
            or value.get("claimed_total") != 0
            for subject, value in locked_before.items()
        ):
            raise ReleaseError("three_subject_resume_not_drained")
        resumed_at = dt.datetime.now(dt.timezone.utc)
        try:
            for subject in RESUMABLE_SUBJECTS:
                resumed = run_json(
                    subject,
                    ["resume"],
                    "three_subject_resume_drain_clear_failed",
                )
                if (
                    resumed.get("subject") != subject
                    or resumed.get("draining") is not False
                ):
                    raise ReleaseError("three_subject_resume_drain_clear_failed")
            for phase in ("enable", "bootstrap", "verify"):
                for service in services:
                    command = service.get(phase)
                    result = runner(command) if isinstance(command, list) else None
                    if (
                        not isinstance(command, list)
                        or _command_returncode(result) != 0
                    ):
                        raise ReleaseError(
                            f"three_subject_resume_service_{phase}_failed:"
                            f"{service.get('name')}"
                        )
            heartbeat_root = (
                Path(str(verified["runtime_data_root"]))
                / "dispatch"
                / "state"
                / "subject-projections"
            )
            deadline = time.monotonic() + heartbeat_timeout_seconds
            after: dict[str, dict[str, Any]] = {}
            heartbeats: dict[str, dict[str, Any]] = {}
            while time.monotonic() < deadline:
                try:
                    after = {
                        subject: run_json(
                            subject,
                            ["status"],
                            "three_subject_resume_status_invalid",
                        )
                        for subject in RESUMABLE_SUBJECTS
                    }
                    heartbeats = {
                        subject: _bounded_manifest(
                            heartbeat_root / f"{subject}.json"
                        )
                        for subject in RESUMABLE_SUBJECTS
                    }
                    observed_at = dt.datetime.now(dt.timezone.utc)
                    for subject in RESUMABLE_SUBJECTS:
                        if (
                            after[subject].get("subject") != subject
                            or after[subject].get("draining") is not False
                        ):
                            raise ReleaseError(
                                "three_subject_resume_heartbeat_invalid"
                            )
                        _validate_fresh_resume_heartbeat(
                            heartbeats[subject],
                            subject=subject,
                            release_id=release_id,
                            resumed_at=resumed_at,
                            observed_at=observed_at,
                        )
                except ReleaseError:
                    time.sleep(0.2)
                    continue
                break
            else:
                raise ReleaseError("three_subject_resume_heartbeat_missing")
            final_id, _ = _current_release(active_link)
            if final_id != release_id:
                raise ReleaseError("three_subject_resume_current_mismatch")
        except Exception as exc:
            drained, paused_gates, rollback_errors = (
                _rollback_three_subject_dispatchers(
                release_id=release_id,
                subjects=RESUMABLE_SUBJECTS,
                services=services,
                run_json=run_json,
                runner=runner,
                gate_before={
                    subject: value["canary_gate"]
                    for subject, value in locked_before.items()
                    if isinstance(value.get("canary_gate"), Mapping)
                },
                )
            )
            failure_status = (
                "failed_drained"
                if not rollback_errors
                else "failed_rollback_incomplete"
            )
            failure = _seal_deployment_value(
                {
                    **planned,
                    "status": failure_status,
                    "error_code": str(exc),
                    "subject_status_after": drained,
                    "canary_gates_after": paused_gates,
                    "producer_queues_preserved": True,
                    "rollback_errors": rollback_errors,
                    "failed_at": dt.datetime.now(dt.timezone.utc).isoformat(),
                },
                release_base=release_base,
                purpose=THREE_SUBJECT_RESUME_PROOF_PURPOSE,
            )
            _write_deployment_receipt(release_base, failure)
            if rollback_errors:
                raise ReleaseError(
                    "three_subject_resume_failed_rollback_incomplete"
                ) from exc
            raise ReleaseError("three_subject_resume_failed_drained") from exc
    proof = _seal_deployment_value(
        {
            **planned,
            "status": "resumed",
            "acceptance_manifest_sha256": acceptance["acceptance"][
                "acceptance_manifest_sha256"
            ],
            "subject_status_after": after,
            "heartbeat_sha256s": {
                subject: sha256_file(heartbeat_root / f"{subject}.json")
                for subject in RESUMABLE_SUBJECTS
            },
            "heartbeat_updated_at": {
                subject: heartbeats[subject]["updated_at"]
                for subject in RESUMABLE_SUBJECTS
            },
            "resumed_at": resumed_at.isoformat(),
        },
        release_base=release_base,
        purpose=THREE_SUBJECT_RESUME_PROOF_PURPOSE,
    )
    proof_id = _write_deployment_receipt(release_base, proof)
    return {**proof, "proof_sha256": proof_id}


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser(description="Immutable study preprocessor release manager")
    sub = root.add_subparsers(dest="command", required=True)

    build = sub.add_parser("build")
    build.add_argument("--source-root", type=Path, default=SOURCE_ROOT)
    build.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    build.add_argument("--runtime-data-root", type=Path, default=DEFAULT_RUNTIME_DATA_ROOT)
    build.add_argument("--skip-tests", action="store_true")
    build.add_argument("--formal-config", type=Path)
    build.add_argument("--formal-baseline", type=Path)
    build.add_argument("--historical-test-input-manifest", type=Path)

    legacy = sub.add_parser("build-legacy-rollback")
    legacy.add_argument("--current-link", type=Path, default=DEFAULT_ACTIVE_LINK)
    legacy.add_argument("--expected-current", required=True)
    legacy.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    legacy.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    legacy.add_argument(
        "--runtime-data-root", type=Path, default=DEFAULT_RUNTIME_DATA_ROOT
    )
    legacy.add_argument("--skip-tests", action="store_true")
    legacy.add_argument("--formal-config", type=Path)
    legacy.add_argument("--formal-baseline", type=Path)
    legacy.add_argument("--historical-test-input-manifest", type=Path)

    prepare_drain = sub.add_parser("prepare-drain")
    prepare_drain.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    prepare_drain.add_argument("--active-link", type=Path, default=DEFAULT_ACTIVE_LINK)
    prepare_drain.add_argument("--target-release-id", required=True)
    prepare_drain.add_argument("--output", type=Path, required=True)
    prepare_drain.add_argument(
        "--operation", choices=("activate", "rollback"), default="activate"
    )
    prepare_drain.add_argument(
        "--claim-gate-timeout-seconds", type=float, default=3600.0
    )

    verify = sub.add_parser("verify")
    verify.add_argument("--release-dir", type=Path, required=True)

    verify_legacy = sub.add_parser("verify-legacy-rollback")
    verify_legacy.add_argument("--release-dir", type=Path, required=True)
    verify_legacy.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    verify_legacy.add_argument("--expected-source-release-id", required=True)

    prepare_canary = sub.add_parser("prepare-canary-manifest")
    prepare_canary.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    prepare_canary.add_argument("--release-id", required=True)
    prepare_canary.add_argument("--output-dir", type=Path, required=True)

    seal_resume = sub.add_parser("seal-math-resume-acceptance")
    seal_resume.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    seal_resume.add_argument("--release-id", required=True)
    seal_resume.add_argument("--active-link", type=Path, default=DEFAULT_ACTIVE_LINK)
    seal_resume.add_argument("--acceptance-manifest", type=Path, required=True)
    seal_resume.add_argument("--output", type=Path, required=True)

    resume_math = sub.add_parser("resume-math")
    resume_math.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
    resume_math.add_argument("--release-id", required=True)
    resume_math.add_argument("--active-link", type=Path, default=DEFAULT_ACTIVE_LINK)
    resume_math.add_argument("--acceptance-receipt", type=Path, required=True)
    resume_math.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    resume_math.add_argument("--apply", action="store_true")
    resume_math.add_argument(
        "--heartbeat-timeout-seconds", type=float, default=90.0
    )

    seal_all_resume = sub.add_parser(
        "seal-three-subject-resume-acceptance"
    )
    seal_all_resume.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    seal_all_resume.add_argument("--release-id", required=True)
    seal_all_resume.add_argument(
        "--active-link", type=Path, default=DEFAULT_ACTIVE_LINK
    )
    seal_all_resume.add_argument(
        "--acceptance-manifest", type=Path, required=True
    )
    seal_all_resume.add_argument("--output", type=Path, required=True)

    resume_all = sub.add_parser("resume-all")
    resume_all.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    resume_all.add_argument("--release-id", required=True)
    resume_all.add_argument(
        "--active-link", type=Path, default=DEFAULT_ACTIVE_LINK
    )
    resume_all.add_argument("--acceptance-receipt", type=Path)
    resume_all.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    resume_all.add_argument("--apply", action="store_true")
    resume_all.add_argument("--rollback", action="store_true")
    resume_all.add_argument(
        "--heartbeat-timeout-seconds", type=float, default=90.0
    )

    resume_canary = sub.add_parser("resume-canary")
    resume_canary.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    resume_canary.add_argument("--release-id", required=True)
    resume_canary.add_argument(
        "--active-link", type=Path, default=DEFAULT_ACTIVE_LINK
    )
    resume_canary.add_argument(
        "--subject", choices=[*RESUMABLE_SUBJECTS, "all"], required=True
    )
    resume_canary.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    resume_canary.add_argument("--apply", action="store_true")
    resume_canary.add_argument(
        "--heartbeat-timeout-seconds", type=float, default=90.0
    )

    pause_canary = sub.add_parser("pause-canary")
    pause_canary.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    pause_canary.add_argument("--release-id", required=True)
    pause_canary.add_argument(
        "--active-link", type=Path, default=DEFAULT_ACTIVE_LINK
    )
    pause_canary.add_argument(
        "--subject", choices=[*RESUMABLE_SUBJECTS, "all"], required=True
    )
    pause_canary.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    pause_canary.add_argument("--apply", action="store_true")
    pause_canary.add_argument(
        "--heartbeat-timeout-seconds", type=float, default=90.0
    )

    activate_canary = sub.add_parser("activate-canary")
    activate_canary.add_argument(
        "--release-base", type=Path, default=DEFAULT_RELEASE_BASE
    )
    activate_canary.add_argument("--release-id", required=True)
    activate_canary.add_argument(
        "--active-link", type=Path, default=DEFAULT_ACTIVE_LINK
    )
    activate_canary.add_argument(
        "--canary-manifest", type=Path, required=True
    )
    activate_canary.add_argument(
        "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
    )
    activate_canary.add_argument(
        "--codex-config", type=Path, default=DEFAULT_CODEX_CONFIG
    )
    activate_canary.add_argument(
        "--morning-pointer", type=Path, default=DEFAULT_MORNING_POINTER
    )
    activate_canary.add_argument(
        "--plugin-cache-root", type=Path, default=DEFAULT_PLUGIN_CACHE_ROOT
    )
    activate_canary.add_argument(
        "--drain-receipt",
        type=Path,
        help="required for --apply when an active release is being replaced",
    )
    activate_canary.add_argument("--apply", action="store_true")
    activate_canary.add_argument(
        "--preview",
        action="store_true",
        help="explicit spelling for the default read-only no-apply audit",
    )
    activate_canary.add_argument(
        "--expected-current",
        help="64-hex current release id, or 'absent' when no current link exists",
    )
    activate_canary.add_argument(
        "--claim-gate-timeout-seconds", type=float, default=3600.0
    )
    activate_canary.add_argument(
        "--process-exit-timeout-seconds", type=float, default=30.0
    )
    activate_canary.add_argument(
        "--heartbeat-timeout-seconds", type=float, default=90.0
    )

    for name in ("activate", "rollback"):
        command = sub.add_parser(name)
        command.add_argument("--release-base", type=Path, default=DEFAULT_RELEASE_BASE)
        command.add_argument("--release-id", required=True)
        command.add_argument("--active-link", type=Path, default=DEFAULT_ACTIVE_LINK)
        command.add_argument(
            "--launchagent-dir", type=Path, default=DEFAULT_LAUNCHAGENT_DIR
        )
        command.add_argument(
            "--codex-config", type=Path, default=DEFAULT_CODEX_CONFIG
        )
        command.add_argument(
            "--morning-pointer", type=Path, default=DEFAULT_MORNING_POINTER
        )
        command.add_argument(
            "--plugin-cache-root", type=Path, default=DEFAULT_PLUGIN_CACHE_ROOT
        )
        command.add_argument(
            "--drain-receipt",
            type=Path,
            help="required for --apply when an active release is being replaced",
        )
        command.add_argument("--apply", action="store_true")
        command.add_argument(
            "--expected-current",
            help="64-hex current release id, or 'absent' when no current link exists",
        )
        command.add_argument(
            "--claim-gate-timeout-seconds", type=float, default=3600.0
        )
        command.add_argument(
            "--process-exit-timeout-seconds", type=float, default=30.0
        )
        command.add_argument(
            "--heartbeat-timeout-seconds", type=float, default=90.0
        )
    return root


def main() -> int:
    args = parser().parse_args()
    try:
        if args.command == "build":
            result = build_release(
                source_root=args.source_root,
                release_base=args.release_base,
                runtime_data_root=args.runtime_data_root,
                skip_tests=args.skip_tests,
                release_profile="concurrent_v2",
                formal_config=args.formal_config,
                formal_baseline=args.formal_baseline,
                historical_test_input_manifest=args.historical_test_input_manifest,
            )
        elif args.command == "build-legacy-rollback":
            result = build_legacy_rollback(
                current_link=args.current_link,
                expected_current=args.expected_current,
                release_base=args.release_base,
                runtime_data_root=args.runtime_data_root,
                skip_tests=args.skip_tests,
                launchagent_dir=args.launchagent_dir,
                formal_config=args.formal_config,
                formal_baseline=args.formal_baseline,
                historical_test_input_manifest=args.historical_test_input_manifest,
            )
        elif args.command == "prepare-drain":
            result = create_drain_receipt(
                release_base=args.release_base,
                active_link=args.active_link,
                target_release_id=args.target_release_id,
                output_path=args.output,
                operation=args.operation,
                claim_gate_timeout_seconds=args.claim_gate_timeout_seconds,
            )
        elif args.command == "prepare-canary-manifest":
            result = prepare_canary_manifest(
                release_base=args.release_base,
                release_id=args.release_id,
                output_dir=args.output_dir,
            )
        elif args.command == "verify":
            result = verify_release(args.release_dir)
        elif args.command == "verify-legacy-rollback":
            result = verify_legacy_rollback(
                release_dir=args.release_dir,
                release_base=args.release_base,
                expected_source_release_id=args.expected_source_release_id,
            )
        elif args.command == "seal-math-resume-acceptance":
            result = seal_math_resume_acceptance(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                acceptance_manifest=args.acceptance_manifest,
                output_path=args.output,
            )
        elif args.command == "resume-math":
            result = resume_math_dispatcher(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                acceptance_receipt=args.acceptance_receipt,
                launchagent_dir=args.launchagent_dir,
                apply=args.apply,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        elif args.command == "seal-three-subject-resume-acceptance":
            result = seal_three_subject_resume_acceptance(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                acceptance_manifest=args.acceptance_manifest,
                output_path=args.output,
            )
        elif args.command == "resume-all":
            result = resume_all_dispatchers(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                acceptance_receipt=args.acceptance_receipt,
                launchagent_dir=args.launchagent_dir,
                apply=args.apply,
                rollback=args.rollback,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        elif args.command == "activate-canary":
            if args.preview and args.apply:
                raise ReleaseError("canary_preview_apply_conflict")
            result = activate_canary_release(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                canary_manifest=args.canary_manifest,
                apply=args.apply,
                expected_current=args.expected_current,
                drain_receipt=args.drain_receipt,
                launchagent_dir=args.launchagent_dir,
                codex_config_path=args.codex_config,
                morning_pointer_path=args.morning_pointer,
                plugin_cache_root=args.plugin_cache_root,
                claim_gate_timeout_seconds=args.claim_gate_timeout_seconds,
                process_exit_timeout_seconds=args.process_exit_timeout_seconds,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        elif args.command == "resume-canary":
            result = resume_canary_dispatchers(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                subject=args.subject,
                launchagent_dir=args.launchagent_dir,
                apply=args.apply,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        elif args.command == "pause-canary":
            result = pause_canary_dispatchers(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                subject=args.subject,
                launchagent_dir=args.launchagent_dir,
                apply=args.apply,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        else:
            result = activate_release(
                release_base=args.release_base,
                release_id=args.release_id,
                active_link=args.active_link,
                apply=args.apply,
                operation=args.command,
                expected_current=args.expected_current,
                drain_receipt=args.drain_receipt,
                launchagent_dir=args.launchagent_dir,
                codex_config_path=args.codex_config,
                morning_pointer_path=args.morning_pointer,
                plugin_cache_root=args.plugin_cache_root,
                claim_gate_timeout_seconds=args.claim_gate_timeout_seconds,
                process_exit_timeout_seconds=args.process_exit_timeout_seconds,
                heartbeat_timeout_seconds=args.heartbeat_timeout_seconds,
            )
        print(json.dumps(result, ensure_ascii=False, sort_keys=True))
        return 0
    except (ReleaseError, OSError, ValueError, json.JSONDecodeError) as exc:
        print(json.dumps({"status": "error", "error_code": str(exc)}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
